KB.add({"board":"08","title":"近现代文学与红色文艺","note":"交大考过：《三体》（2025名解）、巴金《团圆》与电影《英雄儿女》（2025选择）、《黄河大合唱》与延安新华广播电台（2026选择）、诺贝尔与高密（2013名解，指向莫言）。2026年是鲁迅逝世90周年、茅盾和郁达夫诞辰130周年，这一板块今年权重上调。","clusters":[{"cid":"08a","name":"晚清到五四：从文学改良到文学革命","line":"晚清梁启超倡“诗界革命”“小说界革命”，黄遵宪“我手写我口”，王国维以《人间词话》立“境界”说；1915年陈独秀创《青年杂志》（次年改名《新青年》）开启新文化运动，1917年胡适《文学改良刍议》、陈独秀《文学革命论》发动文学革命，胡适1920年《尝试集》是第一部白话新诗集。"},{"cid":"08b","name":"鲁迅：小说、散文、杂文与周年","line":"鲁迅1918年以《狂人日记》（第一篇现代白话小说）登场，小说结集《呐喊》《彷徨》《故事新编》，散文《朝花夕拾》，散文诗《野草》，学术著作《中国小说史略》，后期以杂文为主并成为左联旗手；1936年10月19日在上海逝世，2026年为逝世90周年。"},{"cid":"08c","name":"五四社团：文学研究会与创造社","line":"1921年两大社团先后成立：文学研究会在北京，主张“为人生而艺术”，茅盾、叶圣陶、冰心、朱自清偏写实；创造社在东京，主张“为艺术而艺术”，郭沫若《女神》、郁达夫《沉沦》偏浪漫抒情。2026年是茅盾、郁达夫诞辰130周年。"},{"cid":"08d","name":"新诗流派：新月、现代派到七月、九叶","line":"白话新诗从胡适《尝试集》起步、郭沫若《女神》奠基；新月派闻一多提出“三美”、徐志摩《再别康桥》讲格律；现代派戴望舒、卞之琳转向象征与意象；抗战时期艾青、七月诗派与九叶诗派各成一脉。"},{"cid":"08e","name":"鲁郭茅巴老曹：长篇小说与话剧高峰","line":"六大家中茅盾《子夜》开社会剖析小说，巴金激流三部曲写封建大家庭，老舍《骆驼祥子》《茶馆》写北京市民，曹禺《雷雨》标志现代话剧成熟；“三部曲”类合称是选择题高频形态。"},{"cid":"08f","name":"京派海派与都市、东北作家","line":"1930年代京海之争：京派以沈从文《边城》为代表写乡土人性，海派含新感觉派与通俗的鸳鸯蝴蝶派；四十年代上海有张爱玲、钱锺书《围城》，萧红等东北作家群写故乡与流亡。"},{"cid":"08g","name":"左翼到延安：左联、讲话与红色文艺","line":"1930年左联在上海成立，鲁迅为旗手；1942年延安文艺座谈会确立文艺为工农兵服务，催生赵树理山药蛋派、孙犁荷花淀派和新歌剧《白毛女》；《义勇军进行曲》《黄河大合唱》、延安新华广播电台同属抗战文艺；建国后“三红一创”等红色经典与电影《英雄儿女》延续这一脉。"},{"cid":"08h","name":"新时期文学：思潮更替与诗歌","line":"1977年后思潮依次更替：伤痕文学、反思文学、改革文学、寻根文学（1985）、先锋文学、新写实小说；诗歌有朦胧诗（北岛、舒婷、顾城）与海子；汪曾祺、史铁生的散淡写作，台港作家余光中、金庸另成一支；高行健2000年获诺贝尔文学奖。"},{"cid":"08i","name":"当代长篇、科幻与文学奖","line":"茅盾文学奖（1981年设立）奖长篇，鲁迅文学奖（1997年首评）奖中短篇等七类；陕西作家《平凡的世界》《白鹿原》、上海作家《长恨歌》《繁花》《千里江山图》都是茅奖作品；莫言2012年获诺贝尔文学奖，刘慈欣《三体》2015年、郝景芳《北京折叠》2016年获雨果奖。"}],"entries":[{"id":"c-051","t":"清华国学研究院四大导师","cid":"08a","p":2,"kind":"合称","alias":["清华四大导师","国学院四大导师","四大导师"],"one":"1925年清华国学研究院的梁启超、王国维、陈寅恪、赵元任。","ans":"清华国学研究院四大导师指**1925年清华学校国学研究院聘请的四位导师：梁启超、王国维、陈寅恪、赵元任**，吴宓任研究院主任。**梁启超**著《清代学术概论》，**王国维**著《人间词话》，**陈寅恪**以史学见长，**赵元任**是语言学家。研究院采用导师制，讲求中西会通，培养了王力、徐中舒、姜亮夫等人，1929年停办，是**中国现代学术史上的重要一页**。","pts":["1925年清华国学研究院，吴宓任主任","梁启超、王国维、陈寅恪、赵元任","导师制，1929年停办"],"members":[["梁启超","《清代学术概论》；新会人"],["王国维","《人间词话》《宋元戏曲史》；1927年自沉昆明湖"],["陈寅恪","史学家，《柳如是别传》"],["赵元任","语言学家，现代语言学奠基人"]],"mem":"口诀：**“梁王陈赵”**，按年龄排梁启超（1873）→王国维（1877）→陈寅恪（1890）→赵元任（1892）。赵元任还是作曲家，《教我如何不想她》是他的作品。","mix":"吴宓是研究院主任，李济是讲师，都不在四大导师之列；胡适常被当作干扰项。","mcq":[{"q":"下列人物中，不属于清华国学研究院“四大导师”的是","o":["胡适","梁启超","王国维","赵元任"],"a":0,"w":"四大导师是梁启超、王国维、陈寅恪、赵元任。"}],"rel":[{"t":"梁启超","n":"四大导师之一"},{"t":"王国维","n":"四大导师之一"},{"t":"王国维《人间词话》","n":"王国维代表作"},{"t":"庚款留学与清华学堂","n":"清华的前身背景"}],"more":"清华国学研究院1925年成立，1929年停办。\n学生有王力、徐中舒、姜亮夫、吴其昌等。","exam":[]},{"id":"c-052","t":"朦胧诗派","cid":"08h","p":2,"kind":"流派","alias":["朦胧诗","朦胧诗人","今天派"],"one":"1970年代末兴起的新诗流派，北岛、舒婷、顾城等，以《今天》为阵地。","ans":"朦胧诗派是**1970年代末兴起的新诗流派**，以**北岛、芒克主编的民间刊物《今天》（1978）**为阵地，代表诗人有**北岛、舒婷、顾城**，还有杨炼、江河、芒克。名称来自1980年章明的批评文章《令人气闷的“朦胧”》。他们用象征与意象表达对历史的怀疑和个人的觉醒，如北岛《回答》、舒婷《致橡树》、顾城《一代人》。它打破了政治抒情诗的模式，引发了关于新诗的论争。","pts":["1970年代末，《今天》为阵地","北岛、舒婷、顾城等","象征意象，打破政治抒情诗模式"],"members":[["北岛","《回答》《结局或开始》"],["舒婷","《致橡树》《祖国啊，我亲爱的祖国》"],["顾城","《一代人》《远和近》"],["杨炼","《诺日朗》"],["江河","《纪念碑》"],["芒克","《阳光中的向日葵》"]],"mem":"记三大名字：**“北舒顾”＝北岛、舒婷、顾城**。三句名句对应：北岛“我不相信”，舒婷“绝不像攀援的凌霄花”，顾城“黑夜给了我黑色的眼睛，我却用它寻找光明”。","mix":"海子不属于朦胧诗派，属稍后一代；“朦胧”原是批评者的贬称，后来成为通行名称。","mcq":[{"q":"“黑夜给了我黑色的眼睛，我却用它寻找光明”的作者是","o":["顾城","北岛","舒婷","海子"],"a":0,"w":"这是顾城《一代人》。"}],"rel":[{"t":"北岛","n":"代表诗人"},{"t":"舒婷","n":"代表诗人"},{"t":"顾城","n":"代表诗人"},{"t":"海子","n":"稍后一代的诗人"},{"t":"伤痕文学","n":"同期的小说潮"}],"more":"《今天》1978年12月创刊，北岛、芒克主编。\n名句：卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭。｜北岛《回答》","exam":[]},{"id":"b08-001","t":"鲁迅","cid":"08b","p":1,"kind":"人物","alias":["周树人","豫才","周豫才"],"one":"中国现代文学奠基人，原名周树人，《狂人日记》开白话小说先河。","ans":"鲁迅（1881–1936），**原名周树人，浙江绍兴人，中国现代文学的奠基人**，被称为文学家、思想家、革命家。**1918年他首次以“鲁迅”为笔名在《新青年》发表《狂人日记》，这是中国现代第一篇白话小说**。小说集有**《呐喊》《彷徨》《故事新编》**，另有回忆性散文集《朝花夕拾》、散文诗集《野草》和大量杂文，学术著作有《中国小说史略》。他以“立人”为核心，批判国民劣根性，晚年是**左翼作家联盟的旗手**，1936年10月19日在上海逝世。","pts":["原名周树人，现代文学奠基人","《狂人日记》第一篇白话小说","三部小说集，批判国民性，左联旗手"],"mem":"体裁对应自编口诀：呐彷故是小说，朝花夕拾是散文，野草是诗（散文诗），史略是学术。“呐喊”1923在前，“彷徨”1926在后，“故事新编”1935最晚。","mix":"《朝花夕拾》是散文集，《野草》是散文诗集，《故事新编》是历史小说集；果戈理也有《狂人日记》；2026年是鲁迅逝世90周年。","mcq":[{"q":"鲁迅《野草》的体裁是","o":["短篇小说集","回忆性散文集","杂文集","散文诗集"],"a":3,"w":"《朝花夕拾》才是回忆性散文集。"},{"q":"鲁迅《狂人日记》首次发表于","o":["《小说月报》","《创造》季刊","《新青年》","《语丝》"],"a":2,"w":"1918年5月《新青年》4卷5号。"}],"rel":[{"t":"《狂人日记》","n":"第一篇白话小说"},{"t":"《呐喊》","n":"第一部小说集"},{"t":"左联","n":"旗手"},{"t":"鲁迅逝世90周年","n":"2026年周年"},{"t":"果戈理","n":"同名小说对照"}],"more":"名句：横眉冷对千夫指，俯首甘为孺子牛。｜《自嘲》\n其实地上本没有路，走的人多了，也便成了路。｜《故乡》\n我以我血荐轩辕。｜《自题小像》\n小说集：《呐喊》《彷徨》《故事新编》\n散文：《朝花夕拾》；散文诗：《野草》\n杂文集：《坟》《热风》《华盖集》《且介亭杂文》\n学术：《中国小说史略》\n名篇：《孔乙己》《药》《故乡》（《呐喊》）；《祝福》（《彷徨》）；《藤野先生》《从百草园到三味书屋》（《朝花夕拾》）","exam":[]},{"id":"b08-002","t":"巴金","cid":"08e","p":1,"kind":"人物","exam":["2025选择"],"alias":["李尧棠","芾甘"],"one":"现代作家，激流三部曲《家》《春》《秋》作者，晚年著《随想录》。","ans":"巴金（1904–2005），**原名李尧棠，四川成都人，现代作家**。代表作有**激流三部曲《家》《春》《秋》**，以高家为原型揭露封建大家庭的腐朽，《家》影响最大；还有**爱情三部曲《雾》《雨》《电》**和长篇小说《寒夜》。**1961年短篇小说《团圆》写抗美援朝，1964年改编为电影《英雄儿女》**。晚年著**《随想录》，提倡“讲真话”**，被誉为“二十世纪中国文学的良心”。","pts":["原名李尧棠；激流三部曲，爱情三部曲","《团圆》改编电影《英雄儿女》","《随想录》讲真话"],"mem":"两组三部曲顺口记：“家春秋”写大家庭，“雾雨电”写爱情，一组是天气，别当成季节。《团圆》→《英雄儿女》，影片里王成喊“为了胜利，向我开炮”，画面一出就能想起巴金。","mix":"茅盾也有两组三部曲：《蚀》三部曲、农村三部曲，与巴金的激流、爱情三部曲分开记；朱自清有散文《春》，曹禺把《家》改编为话剧。","mcq":[{"q":"下列属于巴金“爱情三部曲”的是","o":["《家》《春》《秋》","《幻灭》《动摇》《追求》","《春蚕》《秋收》《残冬》","《雾》《雨》《电》"],"a":3,"w":"《家》《春》《秋》是激流三部曲，后两组属茅盾。"},{"q":"电影《英雄儿女》改编自巴金的","o":["《寒夜》","《憩园》","《团圆》","《随想录》"],"a":2,"w":"短篇小说《团圆》写于1961年，电影1964年上映，2025年交大选择题考过。"}],"rel":[{"t":"《随想录》","n":"晚年代表作"},{"t":"《英雄儿女》","n":"据《团圆》改编"},{"t":"茅盾","n":"同为六大家，对举三部曲"},{"t":"曹禺","n":"改编《家》为话剧"},{"t":"《红楼梦》与曹雪芹","n":"同写封建大家庭"}],"more":"主要作品：激流三部曲《家》《春》《秋》；爱情三部曲《雾》《雨》《电》；《寒夜》《憩园》《随想录》；短篇《团圆》（1961）\n译作：赫尔岑《往事与随想》"},{"id":"b08-003","t":"茅盾","cid":"08e","p":1,"kind":"人物","alias":["沈雁冰","沈德鸿","雁冰"],"one":"原名沈德鸿，文学研究会发起人，《子夜》作者，茅盾文学奖以其命名。","ans":"茅盾（1896–1981），**原名沈德鸿，字雁冰，浙江桐乡人，现代作家、文学评论家**。**1921年为文学研究会发起人之一**，主编革新后的《小说月报》，倡导“为人生”的现实主义。长篇**《子夜》（1933）以上海民族资本家吴荪甫的失败为主线**，是社会剖析小说的代表；另有**《蚀》三部曲（《幻灭》《动摇》《追求》）、农村三部曲（《春蚕》《秋收》《残冬》）**和《林家铺子》。**依其遗愿设立的茅盾文学奖**是中国长篇小说最高奖项之一，2026年是其诞辰130周年。","pts":["原名沈德鸿，文学研究会发起人","《子夜》，《蚀》三部曲，农村三部曲","茅盾文学奖；2026年诞辰130周年"],"mem":"《蚀》三部曲谐音“幻动追”：幻灭、动摇、追求。农村三部曲“春秋冬”：春蚕、秋收、残冬（缺夏）。数字：1896生，2026年正好130周年，1981年逝世。","mix":"《蚀》三部曲、农村三部曲是茅盾的，激流三部曲、爱情三部曲是巴金的；2026年是茅盾诞辰130周年，不是逝世整十周年。","mcq":[{"q":"下列属于茅盾“农村三部曲”的是","o":["《幻灭》《动摇》《追求》","《春蚕》《秋收》《残冬》","《家》《春》《秋》","《雾》《雨》《电》"],"a":1,"w":"《幻灭》《动摇》《追求》是《蚀》三部曲。"},{"q":"以民族资本家吴荪甫为主人公的长篇小说是","o":["《子夜》","《骆驼祥子》","《寒夜》","《林家铺子》"],"a":0,"w":"茅盾1933年出版。"}],"rel":[{"t":"《子夜》","n":"代表长篇"},{"t":"《蚀》三部曲（茅盾）","n":"早期三部曲"},{"t":"农村三部曲（茅盾）","n":"农村题材"},{"t":"茅盾文学奖","n":"遗愿设立"},{"t":"文学研究会","n":"发起人之一"}],"more":"主要作品：《子夜》（1933）、《林家铺子》、《蚀》三部曲、农村三部曲\n2026年 7月4日在京举行纪念茅盾诞辰130周年座谈会","exam":[]},{"id":"b08-004","t":"文学研究会","cid":"08c","p":1,"kind":"流派","alias":["文研会"],"one":"1921年北京成立的新文学社团，主张“为人生而艺术”，会刊《小说月报》。","ans":"文学研究会是**五四时期成立最早、影响最大的新文学社团**，**1921年1月在北京成立**，发起人有周作人、郑振铎、沈雁冰（茅盾）、叶圣陶、许地山等。它**主张“为人生而艺术”**，提倡现实主义，反对把文学当作消遣游戏，成员还有冰心、朱自清等。会刊有**革新后的《小说月报》（沈雁冰主编）和《文学旬刊》**，并大量译介俄国和弱小民族文学。它与主张“为艺术而艺术”的**创造社**形成新文学两大流派，推动了现实主义传统的确立。","pts":["1921年北京成立，最早的新文学社团","为人生而艺术，现实主义","《小说月报》；与创造社并立"],"mem":"对照记：文学“研究”人生，所以为人生、写实；“创造”靠个性，所以为艺术、浪漫。地点也能区分：文研会在北京（国内），创造社在东京（留日学生）。顺序：1月文研会，6月创造社。","mix":"创造社1921年6月成立于东京，郭沫若、郁达夫属创造社；文研会的代表作家是茅盾、叶圣陶、冰心、朱自清。","mcq":[{"q":"主张“为人生而艺术”的社团是","o":["创造社","新月社","语丝社","文学研究会"],"a":3,"w":"创造社主张“为艺术而艺术”。"},{"q":"文学研究会的主要会刊是","o":["《创造》季刊","《新月》","革新后的《小说月报》","《语丝》"],"a":2,"w":"1921年起沈雁冰主编，后由郑振铎接编。"}],"rel":[{"t":"创造社","n":"对立并存的社团"},{"t":"《小说月报》","n":"主要会刊"},{"t":"茅盾","n":"发起人之一"},{"t":"郑振铎","n":"发起人之一"},{"t":"唯美主义","n":"“为艺术而艺术”的对照"}],"more":"1921年1月4日 在北京成立\n发起人共12人：周作人、朱希祖、耿济之、郑振铎、瞿世英、王统照、沈雁冰、蒋百里、叶绍钧、郭绍虞、孙伏园、许地山","exam":[]},{"id":"b08-005","t":"《三体》","cid":"08i","p":1,"kind":"作品","exam":["2025名解"],"alias":["三体","三体三部曲","黑暗森林","死神永生"],"one":"刘慈欣长篇科幻三部曲，2015年获雨果奖最佳长篇。","ans":"《三体》是**刘慈欣创作的长篇科幻小说三部曲**，包括《三体》《三体Ⅱ·黑暗森林》《三体Ⅲ·死神永生》，**2006年起在《科幻世界》连载**。小说讲述**地球文明与三体文明的接触与博弈**，提出“**黑暗森林法则**”等宇宙社会学设想，展现宏大的时空尺度和对人性、文明的思考。**2015年《三体》英译本（刘宇昆译）获第73届雨果奖最佳长篇小说奖**，刘慈欣是**亚洲首位获此奖的作家**。它推动中国科幻走向世界，并被改编为电视剧。","pts":["刘慈欣科幻三部曲，《科幻世界》连载","地球与三体文明，黑暗森林法则","2015年雨果奖，亚洲首位"],"mem":"三部曲书名连成一条线：**三体（相遇）→黑暗森林（躲藏）→死神永生（终局）**。获奖挂钩：**2015年《三体》，2016年《北京折叠》**，雨果奖连续两年落在中国作家手里。","mix":"雨果奖是科幻奖，以雨果·根斯巴克命名，与法国作家维克多·雨果无关；《球状闪电》《流浪地球》是刘慈欣的其他作品，不属于《三体》三部曲；2015年获奖的是长篇，2016年郝景芳获的是中短篇。","mcq":[{"q":"2015年，刘慈欣的《三体》获得的奖项是","o":["雨果奖","星云奖","茅盾文学奖","诺贝尔文学奖"],"a":0,"w":"《三体》获第73届雨果奖最佳长篇小说奖。"},{"q":"下列作品中，不属于《三体》三部曲的是","o":["《三体》","《黑暗森林》","《死神永生》","《球状闪电》"],"a":3,"w":"《球状闪电》是刘慈欣的另一部长篇，不属于三部曲。"}],"rel":[{"t":"刘慈欣","n":"作者"},{"t":"雨果奖","n":"2015年获奖"},{"t":"《科幻世界》","n":"最初连载刊物"},{"t":"郝景芳《北京折叠》","n":"次年雨果奖得主"}],"more":"2015年第73届雨果奖在美国斯波坎颁发，刘宇昆译《三体》获最佳长篇小说奖。\n刘慈欣另有《流浪地球》《球状闪电》《诗云》。"},{"id":"b08-006","t":"《黄河大合唱》","cid":"08g","p":1,"kind":"作品","exam":["2026选择"],"alias":["黄河大合唱","黄河颂","保卫黄河"],"one":"1939年光未然词、冼星海曲的八乐章大合唱，抗战音乐代表作。","ans":"《黄河大合唱》是**1939年由光未然作词、冼星海作曲的大型合唱声乐套曲**，同年在**延安**首演。作品属**抗战音乐**，以黄河为背景，通过歌颂与控诉，展现**中华民族在抗日战争中的苦难与抗争**。全曲共**八个乐章**，包括《黄河船夫曲》《黄河颂》《黄水谣》《保卫黄河》《怒吼吧！黄河》等，其中《保卫黄河》以轮唱表现全民抗战。它气势磅礴，被誉为“**中华民族的伟大史诗**”，是抗战时期最具代表性的音乐作品之一，后被改编为**钢琴协奏曲《黄河》**。","pts":["1939年光未然词、冼星海曲，延安首演","八乐章，黄河象征民族抗争","中华民族的伟大史诗，改编钢琴协奏曲"],"mem":"作者搭档：**光**未然加**星**海，“星光”配成一对，词曲不会记反。八个乐章顺着情绪走：**船夫搏浪、颂黄河、天上来（朗诵）→黄水谣、对口曲、黄河怨（受苦）→保卫黄河、怒吼吧黄河（反抗）**，由颂到苦再到战。","mix":"《义勇军进行曲》是田汉词、聂耳曲，电影《风云儿女》主题曲，1949年被定为代国歌，不属于《黄河大合唱》；《黄河颂》《保卫黄河》才是大合唱的乐章。冼星海另有《生产大合唱》等作品，别与《黄河大合唱》混淆。","mcq":[{"q":"《黄河大合唱》的作词者是","o":["田汉","光未然","艾青","郭沫若"],"a":1,"w":"光未然作词，冼星海作曲，1939年延安首演。"},{"q":"下列歌曲中，不属于《黄河大合唱》乐章的是","o":["《黄河颂》","《黄水谣》","《保卫黄河》","《义勇军进行曲》"],"a":3,"w":"《义勇军进行曲》是电影《风云儿女》的主题曲，田汉词、聂耳曲。"}],"rel":[{"t":"冼星海与光未然","n":"词曲作者搭档"},{"t":"《义勇军进行曲》","n":"同为抗战名曲，易混"},{"t":"延安文艺座谈会","n":"同在延安，1942年"},{"t":"黄河","n":"作品的象征对象"}],"more":"八个乐章：《黄河船夫曲》《黄河颂》《黄河之水天上来》（朗诵）《黄水谣》《河边对口曲》《黄河怨》《保卫黄河》《怒吼吧！黄河》。\n《黄河颂》名句：我站在高山之巅，望黄河滚滚，奔腾向东，惊涛澎湃，掀起万丈狂澜。"},{"id":"b08-007","t":"延安新华广播电台","cid":"08g","p":1,"kind":"常识","exam":["2026选择"],"alias":["延安新华广播电台","XNCR","延安台"],"one":"中共第一座广播电台，1940年12月30日在延安开播，呼号XNCR。","ans":"延安新华广播电台是**中国共产党创建的第一座广播电台**，**1940年12月30日在延安开始播音**，呼号**XNCR**，标志着**人民广播事业的开端**。**1941年12月3日**，它开始用**日语**对外播音，这是人民广播**第一次对外广播**，12月3日后来成为**中国国际广播电台**的建台纪念日。电台在抗日战争和解放战争中宣传党的主张，后发展为**中央人民广播电台**，现为中央广播电视总台的组成部分。","pts":["中共第一座广播电台，1940年12月30日开播","1941年12月3日日语广播，第一次对外广播","人民广播开端，后发展为中央人民广播电台"],"mem":"两个年底，数字互换：**1940年12月30日**对内开播，**1941年12月3日**对外日语广播，“30”和“3”前后各出现一次。记画面：延安窑洞里的电台，第一次对外说的是日语，对象是日军。","mix":"新华社的前身是1931年在瑞金成立的红色中华通讯社，是通讯社不是电台；“第一次对外广播”指1941年的日语播音，不是1940年的开播。","mcq":[{"q":"中国共产党创建的第一座广播电台开始播音的时间是","o":["1937年","1940年","1945年","1949年"],"a":1,"w":"延安新华广播电台1940年12月30日开始播音。"},{"q":"1941年12月3日，延安新华广播电台第一次对外广播使用的语言是","o":["英语","俄语","日语","朝鲜语"],"a":2,"w":"这是人民广播第一次对外广播，对象为日本，12月3日后来成为中国国际广播电台建台纪念日。"}],"rel":[{"t":"延安文艺座谈会","n":"同在延安，宣传文化阵地"},{"t":"《黄河大合唱》","n":"同属延安抗战文化"},{"t":"2025年九三阅兵","n":"同为抗战纪念主题"}],"more":"呼号XNCR；12月3日为中国国际广播电台建台纪念日。\n新华社前身：红色中华通讯社（1931年，瑞金）。"},{"id":"b08-008","t":"五四新文化运动","cid":"08a","p":1,"kind":"事件","alias":["新文化运动"],"one":"1915年《新青年》创刊为开端，以民主与科学为旗帜的思想启蒙运动。","ans":"新文化运动是**20世纪初中国的思想启蒙运动**，以**1915年陈独秀在上海创办《青年杂志》（次年改名《新青年》）为开端**，陈独秀、李大钊、胡适、鲁迅等为代表人物。它高举**“民主”与“科学”**两面旗帜，提倡新道德、反对旧道德，提倡新文学、反对旧文学。1917年胡适《文学改良刍议》、陈独秀《文学革命论》掀起**文学革命**。1919年五四运动后，运动转向传播**马克思主义**，为1921年中国共产党的成立奠定思想基础。","pts":["1915年《新青年》创刊，陈独秀、胡适、鲁迅","民主与科学，新道德、新文学","五四后传播马克思主义，为建党奠基"],"mem":"三个年份隔两年一步：1915 办刊（思想），1917 文学革命（文学），1919 五四运动（行动）。顺序可记成“刊、文、动”。《青年杂志》1916年才改名《新青年》，别把改名年份当创刊年份。","mix":"新文化运动（1915，思想启蒙）与五四运动（1919，爱国政治运动）是两件事，选择题常以年份区分；《青年杂志》创刊于上海，1917年随陈独秀迁到北京。","mcq":[{"q":"新文化运动的开端是","o":["1917年胡适发表《文学改良刍议》","1915年陈独秀创办《青年杂志》","1919年北京学生五四游行","1921年中国共产党成立"],"a":1,"w":"1915年《青年杂志》创刊是通行的开端标志，后者是其后的事件。"},{"q":"新文化运动高举的两面旗帜是","o":["民主与科学","自由与平等","救亡与启蒙","革命与改良"],"a":0,"w":"“德先生”（民主）和“赛先生”（科学）。"}],"rel":[{"t":"《新青年》","n":"运动阵地"},{"t":"文学革命","n":"文学领域的突破"},{"t":"陈独秀","n":"创办者"},{"t":"启蒙运动","n":"西方18世纪思想对照"}],"more":"1915年 陈独秀创办《青年杂志》\n1916年 改名《新青年》\n1917年 胡适《文学改良刍议》、陈独秀《文学革命论》\n1918年 鲁迅《狂人日记》\n1919年 五四运动","exam":[]},{"id":"b08-009","t":"莫言","cid":"08i","p":1,"kind":"人物","exam":["2013名解"],"alias":["莫言","管谟业","高密东北乡"],"one":"原名管谟业，山东高密人，2012年获诺贝尔文学奖，首位中国籍得主。","ans":"莫言（1955年生），**原名管谟业，山东高密人，当代作家**。他以故乡**“高密东北乡”**为文学地理，作品融合民间故事、历史与现实，代表作有**《红高粱家族》《丰乳肥臀》《生死疲劳》《蛙》**，其中《蛙》获第八届茅盾文学奖。**2012年获诺贝尔文学奖，是首位获此奖的中国籍作家**，颁奖词称其作品将**魔幻现实主义**与民间故事、历史和当代社会融合。张艺谋据《红高粱》改编的电影获1988年柏林电影节金熊奖。","pts":["原名管谟业，山东高密人，高密东北乡","《红高粱家族》《丰乳肥臀》《生死疲劳》《蛙》","2012年诺贝尔文学奖，魔幻现实主义"],"mem":"笔名“莫言”对应本名“管谟业”，考试常考这一对。五部代表作取首字：**红、乳、生、蛙、檀**（《红高粱家族》《丰乳肥臀》《生死疲劳》《蛙》《檀香刑》）。画面：一片红高粱地，高密东北乡。年份：2000年高行健（法籍），2012年莫言（中国籍）。","mix":"高行健2000年获诺贝尔文学奖，但已入法国籍；莫言才是首位中国籍得主。阿里斯托芬也有喜剧《蛙》，与莫言的《蛙》同名；莫言受马尔克斯、福克纳影响，被评价为“魔幻现实主义”。","mcq":[{"q":"莫言获得诺贝尔文学奖的年份是","o":["2000年","2008年","2012年","2019年"],"a":2,"w":"莫言2012年获奖，是首位中国籍诺贝尔文学奖得主。"},{"q":"莫言的原名是","o":["周树人","管谟业","沈德鸿","舒庆春"],"a":1,"w":"莫言原名管谟业；周树人是鲁迅，沈德鸿是茅盾，舒庆春是老舍。"}],"rel":[{"t":"诺贝尔文学奖","n":"2012年得主"},{"t":"魔幻现实主义","n":"颁奖词提及的风格"},{"t":"葛浩文","n":"主要英译者"},{"t":"寻根文学","n":"《红高粱》常被归入"},{"t":"马尔克斯","n":"影响莫言的作家"}],"more":"代表作：《红高粱家族》《丰乳肥臀》《檀香刑》《生死疲劳》《蛙》《透明的红萝卜》。\n《蛙》获第八届茅盾文学奖；英译者葛浩文。"},{"id":"b08-010","t":"《狂人日记》","cid":"08b","p":1,"kind":"作品","one":"1918年发表于《新青年》，鲁迅首篇白话小说，揭露礼教“吃人”。","ans":"《狂人日记》是**鲁迅1918年5月发表在《新青年》上的短篇小说**，**首次使用“鲁迅”笔名**，是**中国现代文学史上第一篇白话小说**。作品采用日记体，以“迫害狂”患者的视角，从“仁义道德”的字缝里看出满本都写着两个字：**“吃人”**，揭露封建礼教和家族制度的本质，结尾发出**“救救孩子”**的呼喊。小说受俄国果戈理同名小说启发，后收入《呐喊》，为白话文学立下实绩，是新文化运动反封建的代表作。","pts":["1918年《新青年》，首次署名鲁迅","第一篇现代白话小说，日记体","“吃人”的礼教，“救救孩子”"],"mem":"画面：狂人深夜翻历史，满本“仁义道德”，字缝里全是“吃人”。年份记忆：1917 胡适提出主张，1918 鲁迅交出第一篇白话小说，先理论后实绩。","mix":"果戈理《狂人日记》（1835）是俄国同名小说；《阿Q正传》（1921）晚于《狂人日记》，不是第一篇白话小说。","mcq":[{"q":"中国现代文学史上第一篇白话小说是","o":["《阿Q正传》","《狂人日记》","《沉沦》","《药》"],"a":1,"w":"1918年5月鲁迅《狂人日记》。"},{"q":"《狂人日记》中，狂人从历史字缝里看出的两个字是","o":["吃人","虚伪","麻木","愚昧"],"a":0,"w":"“吃人”是对礼教本质的揭露。"}],"rel":[{"t":"鲁迅","n":"作者"},{"t":"《呐喊》","n":"收录小说集"},{"t":"果戈理","n":"同名小说对照"},{"t":"文学革命","n":"白话文创作实绩"},{"t":"《新青年》","n":"发表阵地"}],"more":"文体：日记体，十三则，前有文言小序\n名句：救救孩子！\n收入《呐喊》（1923）","exam":[]},{"id":"b08-011","t":"沈从文","cid":"08f","p":1,"kind":"人物","alias":["沈岳焕"],"one":"京派代表作家，写湘西，中篇《边城》，散文集《湘行散记》。","ans":"沈从文（1902–1988），**湖南凤凰人，京派代表作家**，早年从军，后到北平以写作为业。他以**湘西世界**为题材，用抒情笔调写自然人性之美。**中篇小说《边城》**（1934）以茶峒为背景，写船总女儿**翠翠**与天保、傩送兄弟的爱情悲剧；**散文集《湘行散记》**含《鸭窠围的夜》。1949年后离开文坛，转入文物研究，著有**《中国古代服饰研究》**，在服饰史上有开创之功。","pts":["湖南凤凰人，京派代表","中篇《边城》，翠翠","散文集《湘行散记》；《中国古代服饰研究》"],"mem":"体裁对照：《边城》是小说，《湘行散记》是散文，别互换。画面：渡船、白塔、翠翠等待傩送。晚年转行：从文学转到文物，写服饰史。","mix":"京派（沈从文，写乡土）与老舍的“京味”（写北京市民）不同；《鸭窠围的夜》是357科目2022届汉译英选文。","mcq":[{"q":"沈从文的代表中篇小说是","o":["《长河》","《湘行散记》","《呼兰河传》","《边城》"],"a":3,"w":"《湘行散记》是散文集，《呼兰河传》是萧红的作品。"},{"q":"沈从文所属的流派是","o":["海派","新感觉派","京派","创造社"],"a":2,"w":"京派以沈从文《边城》为代表。"}],"rel":[{"t":"京派与海派","n":"所属流派"},{"t":"《边城》","n":"代表作"},{"t":"萧红","n":"同写故乡"},{"t":"汪曾祺","n":"受其影响的弟子"},{"t":"东北作家群","n":"乡土题材对照"}],"more":"主要作品：中篇小说《边城》（1934）、散文集《湘行散记》（含《鸭窠围的夜》）、《长河》、《中国古代服饰研究》","exam":[]},{"id":"b08-012","t":"冼星海与光未然","cid":"08g","p":2,"kind":"人物","alias":["冼星海","光未然","张光年"],"one":"《黄河大合唱》的作曲者冼星海与作词者光未然（张光年）。","ans":"冼星海（1905–1945）与光未然（原名张光年）是**《黄河大合唱》的作曲者与作词者**。1939年初光未然在延安写成歌词，冼星海短短数日谱成曲，同年4月在延安首演。作品共**八个乐章**，含《黄河船夫曲》《黄河颂》《保卫黄河》《怒吼吧！黄河》等，以黄河象征民族精神，是**抗战时期最有影响的大型声乐作品**。冼星海另有《生产大合唱》，被誉为**“人民音乐家”**，1945年病逝于莫斯科。","pts":["冼星海作曲，光未然作词","《黄河大合唱》1939年延安首演，共八个乐章","冼星海另有《生产大合唱》，人民音乐家"],"mem":"**“星海谱曲，光未然写词”**：光未然的名字里就有“光”，写词的人带来“光”。八个乐章从“船夫曲”起、到“怒吼吧”收，像一条黄河从船夫的号子奔向抗战的怒吼。","mix":"《义勇军进行曲》是田汉作词、聂耳作曲，别和《黄河大合唱》的作者对调；《生产大合唱》作曲也是冼星海。","mcq":[{"q":"《黄河大合唱》的作词者是","o":["田汉","光未然","艾青","郭沫若"],"a":1,"w":"光未然（张光年）作词，冼星海作曲。"}],"rel":[{"t":"《黄河大合唱》","n":"二人合作的作品"},{"t":"聂耳","n":"另一位抗战音乐家"},{"t":"延安鲁迅艺术学院","n":"冼星海在鲁艺任教"},{"t":"《义勇军进行曲》","n":"同属抗战音乐经典"}],"more":"《黄河大合唱》八个乐章：《黄河船夫曲》《黄河颂》《黄河之水天上来》《黄水谣》《河边对口曲》《黄河怨》《保卫黄河》《怒吼吧！黄河》。","exam":[]},{"id":"b08-013","t":"《英雄儿女》","cid":"08g","p":1,"kind":"作品","exam":["2025选择"],"alias":["英雄儿女","英雄赞歌","王成","向我开炮"],"one":"1964年抗美援朝题材电影，改编自巴金《团圆》，插曲《英雄赞歌》。","ans":"《英雄儿女》是**1964年上映的战争电影**，由**武兆堤**执导，长春电影制片厂摄制，改编自**巴金的短篇小说《团圆》**，是**抗美援朝题材**的红色经典。影片讲述志愿军战士**王成**在阵地上呼叫炮火，喊出“**为了胜利，向我开炮！**”后壮烈牺牲，其妹**王芳**成为文工团歌唱演员，在战场上唱起**《英雄赞歌》**。插曲《英雄赞歌》由公木作词、刘炽作曲，传唱至今。影片塑造志愿军英雄群像，体现**革命英雄主义与集体主义**。","pts":["1964年电影，改编自巴金《团圆》","王成“为了胜利，向我开炮”","插曲《英雄赞歌》，抗美援朝题材"],"mem":"三个名字连成一条线：**巴金《团圆》→电影《英雄儿女》→王成喊“向我开炮”→王芳唱《英雄赞歌》**。小说名“团圆”写亲人在战场重逢，电影名“英雄儿女”写英雄与他的亲人。2025年是抗美援朝出国作战75周年，这部电影因此成为考点。","mix":"巴金的代表作是激流三部曲、《寒夜》，改编电影的是短篇《团圆》；《上甘岭》（1956年）是另一部抗美援朝电影，插曲是《我的祖国》，不要与《英雄儿女》的《英雄赞歌》混淆。","mcq":[{"q":"电影《英雄儿女》改编自巴金的","o":["《团圆》","《寒夜》","《憩园》","《家》"],"a":0,"w":"电影1964年上映，改编自巴金短篇小说《团圆》。"},{"q":"电影《英雄儿女》中，王成喊出的名句是","o":["向我开炮","为了新中国，前进","打好今天这一仗","我是中国人民志愿军"],"a":0,"w":"“为了胜利，向我开炮！”是影片的经典台词。"}],"rel":[{"t":"巴金","n":"《团圆》作者"},{"t":"抗美援朝战争","n":"影片题材背景"},{"t":"红色经典","n":"同属红色经典"},{"t":"《义勇军进行曲》","n":"同为红色经典歌曲"}],"more":"插曲《英雄赞歌》：公木词，刘炽曲。\n2025年是抗美援朝出国作战75周年。"},{"id":"b08-014","t":"创造社","cid":"08c","p":1,"kind":"流派","one":"1921年东京成立的新文学社团，郭沫若、郁达夫、成仿吾，主张“为艺术而艺术”。","ans":"创造社是**五四时期与文学研究会并立的新文学社团**，**1921年6月在日本东京成立**，主要发起人是**郭沫若、郁达夫、成仿吾**，另有张资平、田汉、郑伯奇等留日学生。它**主张“为艺术而艺术”**，重视作家内心表现与个性，作品带有**浪漫主义**色彩，代表作有郭沫若诗集《女神》、郁达夫小说集《沉沦》。出版《创造》季刊、《创造周报》《创造月刊》等刊物。1920年代中期转向倡导**革命文学**，成员后来多加入左联。","pts":["1921年东京成立，郭沫若、郁达夫、成仿吾","为艺术而艺术，浪漫主义","《女神》《沉沦》；后转向革命文学"],"mem":"三位发起人首字串成“郭郁成”。对照文学研究会：文研会在北京、为人生、写实；创造社在东京、为艺术、浪漫，“创造”自我，所以重个性表现。","mix":"创造社与文学研究会同在1921年成立，前者6月东京，后者1月北京；田汉也曾参加创造社。","mcq":[{"q":"下列作家中，属于创造社的是","o":["叶圣陶","郁达夫","朱自清","冰心"],"a":1,"w":"叶圣陶、朱自清、冰心属文学研究会。"},{"q":"创造社1921年成立于","o":["日本东京","北京","上海","广州"],"a":0,"w":"主要成员多为留日学生。"}],"rel":[{"t":"文学研究会","n":"对立并存的社团"},{"t":"郭沫若","n":"创始人之一"},{"t":"郁达夫","n":"创始人之一"},{"t":"郭沫若《女神》","n":"代表作"},{"t":"唯美主义","n":"为艺术而艺术的对照"}],"more":"1921年6月 成立于东京\n刊物：《创造》季刊、《创造周报》《创造月刊》\n代表作：郭沫若《女神》、郁达夫《沉沦》","exam":[]},{"id":"b08-015","t":"左联","cid":"08g","p":1,"kind":"流派","alias":["左联","中国左翼作家联盟","左翼作家联盟"],"one":"1930年在上海成立的中共领导下的作家团体，鲁迅为旗手。","ans":"左联即**中国左翼作家联盟**，**1930年3月在上海成立**，是**中国共产党领导下的革命文学团体**。它以**鲁迅为旗手**，成员有冯雪峰、夏衍、茅盾、田汉、丁玲等，主张文学为无产阶级革命服务，机关刊物有《萌芽月刊》《拓荒者》《前哨》等。左联批判新月派和民族主义文学，反对国民党文化“围剿”，培养了一批青年作家，1931年柔石等五位成员被害。1936年为适应抗日民族统一战线而解散，它**开创了革命文学传统**，对延安文艺有直接影响。","pts":["1930年上海成立，中共领导","鲁迅为旗手，机关刊物《萌芽月刊》等","1931年五烈士被害，1936年解散"],"mem":"年份三个节点：**1930成立，1931五烈士，1936解散**。成立大会上鲁迅演讲《对于左翼作家联盟的意见》，记住“鲁迅=旗手”。左联的“联”是联盟，对照1921年的两个社团（文学研究会、创造社）：社团在前，联盟在后。","mix":"左联不是“左翼戏剧家联盟”（1931年成立）；文学研究会、创造社是1921年的五四社团，新月派是以闻一多、徐志摩为代表的诗歌流派，三者都不属于左联。","mcq":[{"q":"左联成立于","o":["1921年","1927年","1930年","1942年"],"a":2,"w":"左联1930年3月在上海成立，鲁迅为旗手。"},{"q":"下列刊物中，属于左联机关刊物的是","o":["《新青年》","《萌芽月刊》","《创造季刊》","《语丝》"],"a":1,"w":"《萌芽月刊》是左联机关刊物；《新青年》是新文化运动刊物，《创造季刊》属创造社，《语丝》属语丝社。"}],"rel":[{"t":"鲁迅","n":"左联旗手"},{"t":"左联五烈士","n":"1931年遇害的五位成员"},{"t":"延安文艺座谈会","n":"左翼文艺传统的延续"},{"t":"文学研究会","n":"1921年五四社团，先于左联"}],"more":"鲁迅在左联成立大会上作《对于左翼作家联盟的意见》。\n1931年左联五烈士：柔石、殷夫、胡也频、冯铿、李伟森。","exam":[]},{"id":"b08-016","t":"延安文艺座谈会","cid":"08g","p":1,"kind":"事件","alias":["延安文艺座谈会","文艺座谈会","在延安文艺座谈会上的讲话","延安讲话"],"one":"1942年5月在延安召开，毛泽东提出文艺为人民大众、首先为工农兵服务。","ans":"延安文艺座谈会是**1942年5月在延安召开的文艺工作会议**，由中共中央组织，**毛泽东**作引言和结论，讲话后整理为《在延安文艺座谈会上的讲话》，1943年10月在《解放日报》发表。讲话提出**文艺为人民大众，首先是为工农兵服务**，讨论文艺的**立场、对象、普及与提高、文艺与政治**等问题，号召文艺工作者深入工农兵生活。会后《白毛女》、赵树理小说、秧歌剧等相继出现，座谈会奠定了**中国共产党文艺政策的基础**，影响此后几十年的当代文艺。","pts":["1942年5月，毛泽东讲话","文艺为人民大众，首先为工农兵服务","催生《白毛女》、赵树理小说，奠定文艺政策"],"mem":"逻辑线：**为谁（工农兵）→怎么写（深入生活）→怎么提高（普及基础上提高）**。年份挂钩：1942年也是延安整风运动展开的一年。会后作品的名单可以背成一串：赵树理（山药蛋派）、孙犁（荷花淀派）、《白毛女》。","mix":"《黄河大合唱》（1939年）、《义勇军进行曲》（1935年）都早于座谈会；座谈会不是“左联成立会”（1930年）。“为人民服务”“为社会主义服务”（“二为”方向）是后来的提法。","mcq":[{"q":"提出“文艺为人民大众，首先为工农兵服务”的会议召开于","o":["1930年","1938年","1942年","1949年"],"a":2,"w":"延安文艺座谈会1942年5月召开。"},{"q":"下列作品中，创作于延安文艺座谈会之后的是","o":["《黄河大合唱》","《义勇军进行曲》","《子夜》","《白毛女》"],"a":3,"w":"歌剧《白毛女》1945年创作；《黄河大合唱》1939年，《义勇军进行曲》1935年，《子夜》1933年。"}],"rel":[{"t":"延安鲁迅艺术学院","n":"座谈会后文艺实践的重要阵地"},{"t":"歌剧《白毛女》","n":"座谈会精神的代表成果"},{"t":"山药蛋派","n":"赵树理方向的流派"},{"t":"左联","n":"此前左翼文艺传统"}],"more":"《在延安文艺座谈会上的讲话》1943年10月19日发表于《解放日报》。\n会议于1942年5月2日至23日召开。","exam":[]},{"id":"b08-017","t":"《新青年》","cid":"08a","p":2,"kind":"作品","alias":["《青年杂志》"],"one":"1915年陈独秀在上海创办，原名《青年杂志》，新文化运动的主阵地。","ans":"《新青年》是**1915年9月陈独秀在上海创办**的综合性月刊，原名**《青年杂志》**，1916年改名《新青年》，是**新文化运动的主阵地**。刊物倡导“民主”与“科学”，1917年随陈独秀迁到北京，先后发表胡适《文学改良刍议》、陈独秀《文学革命论》，1918年5月刊出鲁迅**《狂人日记》**。它推动白话文取代文言文，后来成为传播马克思主义的重要刊物。","pts":["1915年陈独秀创办，原名《青年杂志》","倡导民主与科学，新文化运动主阵地","发表《文学改良刍议》《狂人日记》"],"mem":"年份一对一：1915年《青年杂志》，1916年《新青年》。刊物上三篇关键文章按月份排成一条线：1917年1月胡适《文学改良刍议》（改良），2月陈独秀《文学革命论》（革命），1918年5月鲁迅《狂人日记》（第一篇白话小说），顺序是“改良、革命、小说”。","mix":"据说改名是因为与上海基督教青年会的《上海青年》相近；文学研究会的刊物是《小说月报》，创造社的刊物是《创造季刊》，别和《新青年》混淆。","mcq":[{"q":"1915年陈独秀在上海创办、次年改名为《新青年》的刊物原名是","o":["《新潮》","《青年杂志》","《小说月报》","《语丝》"],"a":1,"w":"《青年杂志》1915年9月创刊，1916年起改称《新青年》。"}],"rel":[{"t":"陈独秀","n":"创办人"},{"t":"五四新文化运动","n":"以此刊为阵地"},{"t":"文学革命","n":"在刊上发动"},{"t":"《狂人日记》","n":"1918年载于该刊"}],"more":"1917年1月　胡适《文学改良刍议》\n1917年2月　陈独秀《文学革命论》\n1918年5月　鲁迅《狂人日记》","exam":[]},{"id":"b08-018","t":"鲁迅逝世90周年","cid":"08b","p":1,"kind":"时事","one":"鲁迅1936年10月19日在上海逝世，2026年10月19日满90周年。","ans":"鲁迅逝世90周年是**2026年的重要文化纪念**。**鲁迅（1881–1936）于1936年10月19日在上海逝世**，终年55岁，2026年10月19日满90年。他是**中国现代文学的奠基人**，晚年定居上海，任**左联旗手**，留下《呐喊》《彷徨》《野草》和大量杂文。灵柩覆盖“**民族魂**”旗帜，初葬万国公墓，1956年迁葬虹口公园，该园后改称鲁迅公园。2026年同时是《朝花夕拾》创作100周年。","pts":["1936年10月19日逝世于上海","2026年满90周年","民族魂，左联旗手"],"mem":"算术锚点：1936+90=2026。2026年的文学周年可串成一组：鲁迅逝世90（1936）、老舍逝世60（1966）、茅盾诞辰130（1896），《朝花夕拾》创作100（1926）。","mix":"2026年老舍是逝世60周年，茅盾是诞辰130周年，别与鲁迅逝世90周年混淆。","mcq":[{"q":"2026年是鲁迅逝世多少周年","o":["80周年","100周年","70周年","90周年"],"a":3,"w":"1936年逝世，2026年满90周年。"},{"q":"鲁迅逝世于","o":["1936年北京","1927年广州","1936年上海","1937年上海"],"a":2,"w":"1936年10月19日，上海。"}],"rel":[{"t":"鲁迅","n":"纪念对象"},{"t":"《朝花夕拾》创作100周年","n":"同年周年"},{"t":"茅盾、郁达夫诞辰130周年","n":"同年周年"},{"t":"左联","n":"晚年身份"}],"more":"2026年周年：鲁迅逝世90周年（10月19日）；《朝花夕拾》创作100周年；老舍逝世60周年；茅盾、郁达夫诞辰130周年","exam":[]},{"id":"b08-019","t":"茅盾、郁达夫诞辰130周年","cid":"08c","p":2,"kind":"时事","alias":["茅盾诞辰130周年","郁达夫诞辰130周年"],"one":"2026年是茅盾、郁达夫诞辰130周年，二人均生于1896年。","ans":"2026年是**茅盾与郁达夫诞辰130周年**，二人均生于**1896年**，同为浙江人。茅盾（沈德鸿，字雁冰）生于桐乡乌镇，是**文学研究会发起人**之一，代表作有《子夜》《蚀》三部曲和农村三部曲，晚年捐出稿费设立**茅盾文学奖**。郁达夫生于富阳，是**创造社发起人**之一，以《沉沦》开创自叙传抒情小说，1945年被日军杀害于印尼苏门答腊。","pts":["二人均生于1896年，2026年130周年","茅盾：文学研究会，《子夜》，茅盾文学奖","郁达夫：创造社，《沉沦》，1945年遇害"],"mem":"一人一社：茅盾属“研究会”（为人生，写实），郁达夫属“创造社”（为艺术，浪漫）；一人一奖一书：茅盾对应《子夜》和茅盾文学奖，郁达夫对应《沉沦》。年份：1896 加 130 年等于 2026。","mix":"鲁迅逝世90周年（1936年逝世）与这两个周年同在2026年，别把“诞辰”和“逝世”弄混；茅盾属文学研究会，郁达夫属创造社。","mcq":[{"q":"2026年是下列哪两位作家诞辰130周年","o":["茅盾、郁达夫","巴金、老舍","鲁迅、郭沫若","冰心、朱自清"],"a":0,"w":"茅盾、郁达夫均生于1896年；巴金1904年、老舍1899年、冰心1900年、朱自清1898年。"}],"rel":[{"t":"茅盾","n":"诞辰130周年"},{"t":"郁达夫","n":"诞辰130周年"},{"t":"鲁迅逝世90周年","n":"同为2026年周年"},{"t":"《朝花夕拾》创作100周年","n":"同为2026年周年"}],"more":"茅盾：1896–1981，原名沈德鸿，浙江桐乡人\n郁达夫：1896–1945，浙江富阳人","exam":[]},{"id":"b08-020","t":"郭沫若《女神》","cid":"08c","p":2,"kind":"作品","alias":["女神"],"one":"郭沫若1921年出版的诗集，新诗的奠基之作。","ans":"《女神》是**郭沫若的第一部新诗集**，1921年由泰东图书局出版，是**中国新诗的奠基之作**，也是**浪漫主义诗歌**的代表。诗集收入《凤凰涅槃》《天狗》《炉中煤》《地球，我的母亲》等，歌颂破坏与创造、个性解放，充满五四时代精神，诗风受惠特曼《草叶集》影响。胡适《尝试集》（1920）是第一部白话诗集，《女神》则在气势与内容上开创了新诗的新境界。","pts":["郭沫若，1921年，新诗奠基之作","《凤凰涅槃》《天狗》《炉中煤》","浪漫主义，五四时代精神"],"mem":"对比记：《尝试集》（1920，胡适）是“第一”，《女神》（1921，郭沫若）是“奠基”。口诀“尝第一，神奠基”。内容抓三首：凤凰涅槃（新生）、天狗（吞日月，狂放）、炉中煤（爱国）。","mix":"第一部白话诗集是胡适《尝试集》，不是《女神》；《女神》属创造社，倾向浪漫抒情，与文学研究会写实风格相对。","mcq":[{"q":"被称为中国新诗奠基之作的诗集是","o":["《尝试集》","《红烛》","《女神》","《繁星》"],"a":2,"w":"郭沫若《女神》（1921）奠基新诗；《尝试集》是第一部白话诗集。"}],"rel":[{"t":"郭沫若","n":"作者"},{"t":"创造社","n":"所属社团"},{"t":"胡适","n":"《尝试集》作者"},{"t":"惠特曼","n":"风格受其影响"}],"more":"名篇：《凤凰涅槃》《天狗》《炉中煤》《地球，我的母亲》《晨安》《立在地球边上放号》\n《尝试集》（胡适，1920）：第一部白话新诗集","exam":[]},{"id":"b08-021","t":"老舍","cid":"08e","p":1,"kind":"人物","alias":["舒庆春","舒舍予","舍予"],"one":"北京满族作家，京味文学代表，《骆驼祥子》《茶馆》作者，人民艺术家。","ans":"老舍（1899–1966），**原名舒庆春，满族，北京人，现代小说家、剧作家**，**“京味文学”**的代表。长篇**《骆驼祥子》**写人力车夫祥子三起三落的悲剧，**《四世同堂》**写抗战时期北平的市民；话剧**《茶馆》**（1957）以三幕写清末到抗战后的社会变迁；他因话剧**《龙须沟》**获北京市政府授予的**“人民艺术家”**称号。1966年8月24日逝世，2026年是逝世60周年。","pts":["原名舒庆春，满族，京味文学","《骆驼祥子》《四世同堂》《茶馆》","因《龙须沟》获“人民艺术家”称号"],"mem":"三个数字对三部作品：祥子“三起三落”，茶馆“三幕三个时代”，四世同堂“祁家四代”。再记“骆驼祥子拉车，茶馆王利发掌柜，龙须沟得称号”。","mix":"老舍是“京味”，沈从文是“京派”，写湘西；《龙须沟》是老舍的话剧，《雷雨》是曹禺的话剧。","mcq":[{"q":"老舍被授予“人民艺术家”称号，与哪部作品相关","o":["《茶馆》","《骆驼祥子》","《四世同堂》","《龙须沟》"],"a":3,"w":"话剧《龙须沟》。"},{"q":"下列作品不属于老舍的是","o":["《骆驼祥子》","《四世同堂》","《雷雨》","《茶馆》"],"a":2,"w":"《雷雨》是曹禺的话剧。"}],"rel":[{"t":"《骆驼祥子》","n":"代表长篇"},{"t":"《茶馆》","n":"代表话剧"},{"t":"《四世同堂》","n":"抗战题材长篇"},{"t":"曹禺","n":"同为话剧大家"},{"t":"狄更斯","n":"早期小说受其影响"}],"more":"主要作品：《骆驼祥子》《四世同堂》《月牙儿》《正红旗下》；话剧《茶馆》《龙须沟》\n2026年 逝世60周年（1966年8月24日）","exam":[]},{"id":"b08-022","t":"曹禺《雷雨》","cid":"08e","p":2,"kind":"作品","alias":["雷雨"],"one":"曹禺1934年的话剧，周鲁两家的悲剧，现代话剧成熟的标志。","ans":"《雷雨》是**曹禺的处女作**，**1934年**发表于《文学季刊》，是**中国现代话剧成熟的标志**。剧本分四幕，另有序幕与尾声，围绕**周家与鲁家**三十年的恩怨展开，写周朴园、侍萍、繁漪、周萍、四凤等人在一天内的悲剧，揭示封建大家庭的罪恶与命运的无情。结构紧凑，受古希腊悲剧和易卜生影响，与《日出》《原野》《北京人》并称曹禺四大剧。","pts":["曹禺处女作，1934年，话剧成熟标志","周鲁两家三十年恩怨","结构紧凑，受古希腊悲剧影响"],"mem":"人物记两家：周家周朴园、繁漪、周萍、周冲；鲁家侍萍、四凤、鲁大海。画面：闷热的一天，雷雨欲来，所有秘密在一天内爆发。年份挂钩：1934年《雷雨》，之后《日出》（1936）。","mix":"《雷雨》是话剧成熟的标志，话剧开端是1907年春柳社演出；《茶馆》是老舍的话剧；《日出》写陈白露。","mcq":[{"q":"曹禺话剧《雷雨》中的两个家庭是","o":["高家与冯家","曾家与愫家","周家与鲁家","祁家与冠家"],"a":2,"w":"《雷雨》写周家与鲁家三十年恩怨。"}],"rel":[{"t":"曹禺","n":"作者"},{"t":"曹禺四大剧","n":"同属四大剧"},{"t":"三一律","n":"结构接近"},{"t":"易卜生","n":"所受影响来源"}],"more":"人物：周朴园、鲁侍萍、繁漪、周萍、周冲、四凤、鲁大海\n1934年　《文学季刊》发表","exam":[]},{"id":"b08-023","t":"朱自清","cid":"08c","p":2,"kind":"人物","alias":["佩弦"],"one":"散文家、学者，文学研究会成员，《背影》《荷塘月色》作者。","ans":"朱自清（1898–1948），字佩弦，**江苏扬州人**，现代**散文家、诗人、学者**，**文学研究会**成员，任教于清华大学。散文**《背影》**写父爱，**《荷塘月色》**写月下荷塘，另有《匆匆》《春》《桨声灯影里的秦淮河》，语言朴素细腻；学术著作有《经典常谈》。他1948年因胃病去世，生前拒领美国救济粮，毛泽东称赞他有骨气。","pts":["散文家，文学研究会，字佩弦","《背影》《荷塘月色》《匆匆》","拒领美国救济粮，1948年逝世"],"mem":"画面：父亲爬月台买橘子的背影，加月色下的荷塘，两幅图对应两篇名作。情感口诀：“背影写父爱，荷塘写心境”。气节挂钩：他是“宁可饿死，不领美国救济粮”的学者。","mix":"《故都的秋》是郁达夫，《白杨礼赞》是茅盾，《想北平》是老舍；《桨声灯影里的秦淮河》是朱自清与俞平伯同题之作。","mcq":[{"q":"下列作品中，作者是朱自清的是","o":["《荷塘月色》","《故都的秋》","《白杨礼赞》","《想北平》"],"a":0,"w":"《故都的秋》郁达夫，《白杨礼赞》茅盾，《想北平》老舍。"}],"rel":[{"t":"文学研究会","n":"所属社团"},{"t":"郁达夫","n":"散文名篇常对举"},{"t":"叶圣陶","n":"同属文学研究会"},{"t":"周作人","n":"现代散文名家"}],"more":"《背影》《荷塘月色》《匆匆》《春》《桨声灯影里的秦淮河》\n诗集《踪迹》；学术著作《经典常谈》","exam":[]},{"id":"b08-024","t":"新月派与新诗“三美”","cid":"08d","p":1,"kind":"流派","alias":["新月派","新月社","三美","新格律诗"],"one":"闻一多提出新诗“三美”：音乐美、绘画美、建筑美；代表诗人徐志摩。","ans":"新月派是**1920年代以新月社和《新月》月刊命名的新诗流派**，代表诗人有**徐志摩、闻一多**，另有朱湘、陈梦家、林徽因等。新月社1923年成立于北京，《晨报副刊·诗镌》是重要阵地。闻一多1926年提出新诗应具**音乐美（音节）、绘画美（词藻）、建筑美（节的匀称和句的均齐）**，称**“三美”**，倡导新格律诗。徐志摩《再别康桥》（1928）是代表作，闻一多有《红烛》《死水》。新月派推动新诗从自由体走向格律化。","pts":["新月社，徐志摩、闻一多","三美：音乐美、绘画美、建筑美","《再别康桥》《死水》；新格律诗"],"mem":"“三美”记“音、绘、建”：耳朵听音乐，眼睛看图画，用尺子量建筑，对应音节、词藻、匀称整齐。《再别康桥》开头“轻轻的我走了，正如我轻轻的来”，节与节对称，正好是建筑美的例子。","mix":"“三美”由闻一多提出，不是徐志摩；戴望舒《雨巷》属现代派，重象征与音乐性，与新月派的格律主张不同。","mcq":[{"q":"提出新诗“三美”主张的是","o":["徐志摩","闻一多","戴望舒","郭沫若"],"a":1,"w":"闻一多1926年在《诗的格律》中提出。"},{"q":"下列不属于闻一多“三美”的是","o":["哲理美","音乐美","绘画美","建筑美"],"a":0,"w":"三美是音乐美、绘画美、建筑美。"}],"rel":[{"t":"徐志摩","n":"新月派代表"},{"t":"闻一多","n":"三美提出者"},{"t":"戴望舒","n":"现代派，对举"},{"t":"林徽因","n":"新月派成员"},{"t":"古体诗与近体诗（格律诗）","n":"旧格律与新格律对照"}],"more":"代表作：徐志摩《再别康桥》（1928）；闻一多《红烛》《死水》\n“三美”：音乐美（音节）、绘画美（词藻）、建筑美（节的匀称、句的均齐）","exam":[]},{"id":"b08-025","t":"郁达夫","cid":"08c","p":2,"kind":"人物","alias":["《沉沦》"],"one":"创造社发起人，小说集《沉沦》，散文《故都的秋》，1945年遇害。","ans":"郁达夫（1896–1945），**浙江富阳人**，**创造社**发起人之一，现代作家。1921年出版小说集**《沉沦》**，被视为现代第一部白话短篇小说集，以大胆的自我暴露开创**“自叙传”抒情小说**，另有《春风沉醉的晚上》。散文**《故都的秋》**写北平秋色，笔调清悲。他1942年起流亡苏门答腊，**1945年被日军杀害于印尼**。2026年是他诞辰130周年。","pts":["创造社发起人，浪漫抒情，自叙传","小说集《沉沦》（1921），散文《故都的秋》","1945年在印尼被日军杀害"],"mem":"一社一集：创造社的《沉沦》。《沉沦》与《女神》同在1921年、同由泰东图书局出版，一小说一诗歌，合起来代表创造社的“浪漫抒情”。《故都的秋》抓三字：清、静、悲凉。","mix":"《春风沉醉的晚上》是357科目2023届汉译英选文；《故都的秋》是郁达夫，朱自清的名篇是《荷塘月色》《背影》。","mcq":[{"q":"散文《故都的秋》的作者是","o":["朱自清","老舍","冰心","郁达夫"],"a":3,"w":"《故都的秋》是郁达夫名篇。"}],"rel":[{"t":"创造社","n":"所属社团"},{"t":"郭沫若《女神》","n":"同年同社名作"},{"t":"茅盾、郁达夫诞辰130周年","n":"2026年周年"},{"t":"朱自清","n":"散文名家对照"}],"more":"《沉沦》（1921）《春风沉醉的晚上》《迟桂花》\n散文《故都的秋》《钓台的春昼》","exam":[]},{"id":"b08-026","t":"钱锺书《围城》","cid":"08f","p":2,"kind":"作品","alias":["围城","方鸿渐"],"one":"钱锺书的讽刺小说，“城外的人想冲进去，城里的人想逃出来”。","ans":"《围城》是**钱锺书的长篇讽刺小说**，1947年出版，写**方鸿渐**留洋归国后在婚姻、职业中的际遇，涉及唐晓芙、孙柔嘉、赵辛楣等人。书名取意于“城外的人想冲进去，城里的人想逃出来”，**象征人生困境**。小说语言机智，善用比喻，是**现代讽刺小说**的代表，被誉为“新儒林外史”。钱锺书另著学术巨著**《管锥编》**《谈艺录》。","pts":["钱锺书1947年长篇讽刺小说","方鸿渐的婚姻职业困境","“围城”象征人生困境"],"mem":"一句话：“城外想进，城里想出”，对应婚姻与职业。人物三问：方鸿渐（主人公）、唐晓芙（心上人）、孙柔嘉（妻子）。作者线：钱锺书写《围城》，夫人杨绛写《我们仨》。","mix":"钱锺书《围城》写知识分子，张爱玲《金锁记》写旧式家庭；“新儒林外史”的说法把它与吴敬梓《儒林外史》相联。","mcq":[{"q":"“城外的人想冲进去，城里的人想逃出来”形容的是","o":["《骆驼祥子》","《子夜》","《边城》","《围城》"],"a":3,"w":"这句话说明《围城》的主题。"}],"rel":[{"t":"钱锺书","n":"作者"},{"t":"《儒林外史》与吴敬梓","n":"讽刺传统的对照"},{"t":"张爱玲","n":"同期都市作家"},{"t":"京派与海派","n":"所属文学语境"}],"more":"主要人物：方鸿渐、唐晓芙、孙柔嘉、赵辛楣、苏文纨\n钱锺书其他著作：《管锥编》《谈艺录》《宋诗选注》","exam":[]},{"id":"b08-027","t":"张爱玲","cid":"08f","p":2,"kind":"人物","alias":["张煐"],"one":"原名张煐，写上海香港都市，《金锁记》《倾城之恋》。","ans":"张爱玲（1920–1995），原名**张煐**，上海人，现代作家，长期生活于上海、香港。她1943年发表《沉香屑·第一炉香》走红，1944年出版小说集**《传奇》**、散文集《流言》。代表作有**《金锁记》**（曹七巧）、**《倾城之恋》**（白流苏与范柳原）、《红玫瑰与白玫瑰》，长篇**《半生缘》**（原名《十八春》）。她以苍凉的笔调写都市男女，傅雷曾撰文评论《金锁记》。","pts":["原名张煐，写上海香港都市男女","《金锁记》《倾城之恋》《半生缘》","小说集《传奇》，散文集《流言》"],"mem":"配对记：《金锁记》锁住曹七巧，《倾城之恋》倾倒白流苏。关键词“苍凉”。《半生缘》原名《十八春》，“半生”对“十八”记一个原名关系。","mix":"《围城》是钱锺书，《呼兰河传》是萧红；《金锁记》常考，也与《红玫瑰与白玫瑰》并列。","mcq":[{"q":"张爱玲小说《倾城之恋》的男女主人公是","o":["方鸿渐与孙柔嘉","白流苏与范柳原","曹七巧与姜季泽","祥林嫂与贺老六"],"a":1,"w":"《倾城之恋》写白流苏与范柳原；曹七巧是《金锁记》主人公。"}],"rel":[{"t":"傅雷","n":"评论过《金锁记》"},{"t":"钱锺书","n":"同期上海作家"},{"t":"萧红","n":"同期女作家对照"},{"t":"京派与海派","n":"海派文学语境"}],"more":"小说：《金锁记》《倾城之恋》《红玫瑰与白玫瑰》《半生缘》\n小说集《传奇》；散文集《流言》","exam":[]},{"id":"b08-028","t":"萧红","cid":"08f","p":2,"kind":"人物","alias":["张廼莹","萧红"],"one":"东北作家群代表，《生死场》《呼兰河传》，鲁迅为《生死场》作序。","ans":"萧红（1911–1942），原名**张廼莹**，黑龙江呼兰人，**东北作家群**代表作家。1935年出版**《生死场》**，鲁迅为之作序，写东北农民在日寇入侵下的生死挣扎；1940年在香港写成**《呼兰河传》**，以回忆笔触写故乡呼兰河小城的人情风物，具有散文化与诗化的特点。她1942年在香港病逝，年仅31岁，作品有葛浩文英译本。","pts":["原名张廼莹，东北作家群","《生死场》（鲁迅作序），《呼兰河传》","1942年香港病逝，年仅31岁"],"mem":"配对记：《生死场》（东北农民，鲁迅序），《呼兰河传》（故乡小城，回忆体）。画面：后园里的祖父、蓝天白云下的呼兰河，是《呼兰河传》的底色。年龄记：只活了31岁。","mix":"《生死场》写农民抗日，《呼兰河传》写故乡小城，别混；《边城》是沈从文，《金锁记》是张爱玲。","mcq":[{"q":"鲁迅为其小说《生死场》作序的作家是","o":["张爱玲","萧红","丁玲","冰心"],"a":1,"w":"鲁迅为萧红《生死场》作序，称其“力透纸背”。"}],"rel":[{"t":"东北作家群","n":"所属群体"},{"t":"鲁迅","n":"为《生死场》作序"},{"t":"张爱玲","n":"同期女作家"},{"t":"《边城》","n":"同为抒情乡土小说"}],"more":"《生死场》（1935）、《呼兰河传》（1940）、《小城三月》、《商市街》\n鲁迅序：北方人民对于生的坚强，对于死的挣扎……","exam":[]},{"id":"b08-029","t":"赵树理","cid":"08g","p":2,"kind":"人物","alias":["山药蛋派开创者"],"one":"山药蛋派开创者，解放区文学代表，《小二黑结婚》作者。","ans":"赵树理（1906–1970），**山西沁水人，现代作家**，**“山药蛋派”的开创者**，解放区文学的代表。他自觉贯彻《在延安文艺座谈会上的讲话》精神，以农民喜闻乐见的口语和故事写农村。代表作有**《小二黑结婚》《李有才板话》**（1943）和长篇**《三里湾》**（1955）。他的创作使新文学走向大众，被称为**“农民作家”**，影响了马烽、西戎等山西作家。","pts":["山西沁水人，山药蛋派开创者","《小二黑结婚》《李有才板话》《三里湾》","解放区文学代表，文学大众化"],"mem":"**“山药蛋”就是山西的土豆**，味道土、实在，对应赵树理的写作：口语、农民、故事。代表作按时间记：1943一年出两部（《小二黑结婚》《李有才板话》），1955《三里湾》。","mix":"“荷花淀派”是孙犁，“山药蛋派”是赵树理；两人都写解放区，前者诗意抒情，后者通俗幽默。","mcq":[{"q":"“山药蛋派”的开创者是","o":["孙犁","周立波","赵树理","丁玲"],"a":2,"w":"孙犁是荷花淀派，赵树理是山药蛋派。"}],"rel":[{"t":"山药蛋派","n":"其开创的流派"},{"t":"《小二黑结婚》","n":"代表作"},{"t":"孙犁","n":"荷花淀派，常对举"},{"t":"延安文艺座谈会","n":"创作方向的思想来源"}],"more":"主要作品：《小二黑结婚》《李有才板话》（1943）、《李家庄的变迁》（1946）、《三里湾》（1955）。\n山药蛋派成员还有马烽、西戎、李束为、孙谦、胡正。","exam":[]},{"id":"b08-030","t":"艾青","cid":"08d","p":2,"kind":"人物","alias":["蒋海澄"],"one":"原名蒋海澄，诗人，《大堰河》《我爱这土地》，“土地”“太阳”意象。","ans":"艾青（1910–1996），原名**蒋海澄**，浙江金华人，**现代诗人**。1933年在狱中写成**《大堰河》**，以乳母的形象写出对农民的深情，并首次用笔名“艾青”。抗战时期作**《我爱这土地》**《雪落在中国的土地上》《北方》和长诗《向太阳》，以**“土地”“太阳”**为核心意象，诗风沉郁。“为什么我的眼里常含泪水？因为我对这土地爱得深沉……”广为传诵，其自由体诗被称为有“散文美”。","pts":["原名蒋海澄，现代诗人","《大堰河》（1933），《我爱这土地》（1938）","土地与太阳意象，抗战诗歌代表"],"mem":"画面：诗人含泪望着土地，对应名句“我爱这土地”。意象二词：土地（《我爱这土地》《北方》）、太阳（《向太阳》）。成名作《大堰河》写的是保姆，想“保姆大堰河，笔名艾青”。","mix":"艾青与七月诗派关系密切，但不是九叶诗派成员；《再别康桥》是徐志摩，《雨巷》是戴望舒。","mcq":[{"q":"“为什么我的眼里常含泪水？因为我对这土地爱得深沉”出自","o":["《我爱这土地》","《再别康桥》","《雨巷》","《死水》"],"a":0,"w":"出自艾青《我爱这土地》（1938）。"}],"rel":[{"t":"七月诗派","n":"关系密切"},{"t":"东北作家群","n":"同为抗战时期流亡文学"},{"t":"九叶诗派","n":"同期另一诗派"},{"t":"《黄河大合唱》","n":"同属抗战文艺"}],"more":"为什么我的眼里常含泪水？因为我对这土地爱得深沉……｜《我爱这土地》\n《大堰河》《北方》《向太阳》《雪落在中国的土地上》","exam":[]},{"id":"b08-032","t":"茅盾文学奖","cid":"08i","p":1,"kind":"制度","alias":["茅盾文学奖","茅奖","茅盾奖"],"one":"1981年依茅盾遗愿设立，奖励长篇小说，四年一届。","ans":"茅盾文学奖是**中国作家协会主办的长篇小说奖**，**1981年依茅盾遗愿设立**，茅盾捐出稿费25万元作为奖励基金。**每四年评选一次**，奖励优秀长篇小说，首届于1982年揭晓，古华《芙蓉镇》、姚雪垠《李自成》（第二卷）等获奖。此后获奖的有路遥《平凡的世界》（第三届）、陈忠实《白鹿原》（第四届）、莫言《蛙》（第八届）、金宇澄《繁花》（第九届）、孙甘露《千里江山图》（第十一届）。它与**鲁迅文学奖**并为国内两大文学奖，是**当代长篇小说**的重要风向标。","pts":["1981年依茅盾遗愿设立，奖长篇小说","每四年一届，中国作协主办","《平凡的世界》《白鹿原》《蛙》《繁花》等获奖"],"mem":"口诀“**茅长鲁中短**”：茅盾奖奖长篇，鲁迅奖奖中短篇与多文体。年份挂钩：茅盾1981年去世，遗愿设奖，同年设立。代表获奖作品用地名记：**陕西两部（《平凡的世界》《白鹿原》）、上海两部（《繁花》《千里江山图》）、山东一部（《蛙》）**。","mix":"茅盾文学奖只奖长篇小说，鲁迅文学奖奖中篇、短篇等七类；《围城》《活着》《骆驼祥子》都没有获得茅盾文学奖；莫言获的是诺贝尔文学奖和茅盾文学奖两项，不要混为一谈。","mcq":[{"q":"茅盾文学奖奖励的文学体裁是","o":["诗歌","长篇小说","短篇小说","散文"],"a":1,"w":"茅盾文学奖奖励优秀长篇小说，鲁迅文学奖奖励中短篇等七类。"},{"q":"下列作品中，获得茅盾文学奖的是","o":["《围城》","《活着》","《呐喊》","《平凡的世界》"],"a":3,"w":"《平凡的世界》获第三届茅盾文学奖（1991年）。"}],"rel":[{"t":"茅盾","n":"依其遗愿设奖"},{"t":"鲁迅文学奖","n":"对举，奖中短篇等"},{"t":"首届茅盾文学奖","n":"1982年首次评奖"},{"t":"第十一届茅盾文学奖","n":"近年一届"},{"t":"《白鹿原》","n":"第四届获奖作品"}],"more":"茅盾文学奖获奖作品举例：《平凡的世界》（路遥，第三届）、《白鹿原》（陈忠实，第四届）、《蛙》（莫言，第八届）、《繁花》（金宇澄，第九届）、《千里江山图》（孙甘露，第十一届）。","exam":[]},{"id":"b08-033","t":"鲁迅文学奖","cid":"08i","p":1,"kind":"制度","alias":["鲁迅文学奖","鲁奖"],"one":"中国作协主办，1997年首评，四年一届，设七个门类。","ans":"鲁迅文学奖是**中国作家协会主办的国家级文学奖**，**1997年创立并首次评奖**，**四年一届**，设**中篇小说、短篇小说、报告文学、诗歌、散文杂文、文学理论评论、文学翻译**七个门类，与奖励长篇小说的茅盾文学奖并称。2026年8月28日揭晓第九届，共35篇（部）作品获奖，外卖骑手王计兵获诗歌奖。该奖以鲁迅命名，涵盖**多种文体**，其中**文学翻译奖**体现了对译者工作的重视，是翻译领域的重要荣誉。","pts":["中国作协主办，1997年创立","四年一届，设七个门类","涵盖中短篇、诗歌、翻译等，与茅奖对举"],"mem":"口诀“**茅长鲁中短**”：茅盾奖奖长篇，鲁迅奖奖中短篇等。七个门类口诀（自编）：**中短报诗散评译**（中篇、短篇、报告文学、诗歌、散文杂文、理论评论、翻译）。年份：1981年茅奖，1997年鲁奖，鲁奖晚16年。","mix":"鲁迅文学奖不设长篇小说奖，长篇归茅盾文学奖；文学翻译奖是鲁奖七类之一，与专门的“鲁迅文学奖文学翻译奖”词条同源，不要与国际翻译奖项混淆。","mcq":[{"q":"下列不属于鲁迅文学奖门类的是","o":["报告文学","诗歌","长篇小说","文学翻译"],"a":2,"w":"长篇小说归茅盾文学奖，鲁迅文学奖设中篇、短篇、报告文学、诗歌、散文杂文、理论评论、文学翻译七类。"},{"q":"鲁迅文学奖首次评奖的年份是","o":["1981年","1997年","2008年","2012年"],"a":1,"w":"鲁迅文学奖1997年创立并首次评奖；1981年是茅盾文学奖设立年。"}],"rel":[{"t":"茅盾文学奖","n":"对举，奖长篇"},{"t":"第九届鲁迅文学奖","n":"2026年揭晓"},{"t":"鲁迅文学奖文学翻译奖","n":"七个门类之一"},{"t":"鲁迅","n":"奖项冠名人"}],"more":"第九届鲁迅文学奖于2026年8月28日揭晓，35篇（部）作品获奖，外卖骑手王计兵《低空飞行》获诗歌奖。\n第八届为2022年揭晓。","exam":[]},{"id":"b08-034","t":"第九届鲁迅文学奖","cid":"08i","p":2,"kind":"时事","alias":["鲁迅文学奖第九届","第九届鲁奖"],"one":"2026年7月15日揭晓，评选2022至2025年作品，七类共35部获奖。","ans":"第九届鲁迅文学奖于**2026年7月15日揭晓**，评选**2022至2025年**的作品，**七个门类共35部**获奖。文学翻译奖5部，包括蒲隆译《约翰生传》、**戴从容译《芬尼根的守灵夜》**、**袁筱一译《战争，战争，战争》**等。“外卖诗人”**王计兵《低处飞行》获诗歌奖**。上海有3部获奖，颁奖活动在**上海**举行，适逢**鲁迅逝世90周年**。","pts":["2026年7月15日揭晓，七类共35部","文学翻译奖5部，含戴从容译《芬尼根的守灵夜》","王计兵《低处飞行》获诗歌奖；颁奖在上海"],"mem":"数字：**7类×5部＝35部**（文学翻译奖也是5部）。“外卖诗人”王计兵、颁奖在上海、鲁迅逝世90周年，三者连成一条线，选择题里常出现这类“地点＋周年”信息。","mix":"鲁迅文学奖（1997年首评）奖中短篇、诗歌、散文、翻译等七类，茅盾文学奖奖长篇；两奖别混。","mcq":[{"q":"第九届鲁迅文学奖文学翻译奖获奖译作《芬尼根的守灵夜》的译者是","o":["蒲隆","戴从容","张芸","刘洪波"],"a":1,"w":"戴从容译《芬尼根的守灵夜》（乔伊斯作品）。"}],"rel":[{"t":"鲁迅文学奖","n":"所属奖项"},{"t":"鲁迅逝世90周年","n":"颁奖时间背景"},{"t":"鲁迅文学奖文学翻译奖","n":"其中翻译类奖项"},{"t":"乔伊斯","n":"《芬尼根的守灵夜》作者"}],"more":"获奖译作：蒲隆译《约翰生传》，戴从容译《芬尼根的守灵夜》，张芸译《人类的末日》，刘洪波译《拉夫尔》，袁筱一译《战争，战争，战争》。\n上海获奖：薛舒（散文），戴从容、袁筱一（译作）。","exam":[]},{"id":"b08-035","t":"红色经典","cid":"08g","p":2,"kind":"合称","alias":["十七年文学","三红一创"],"one":"建国后“十七年”革命历史与农村题材长篇，《红岩》《创业史》等。","ans":"红色经典指**1949至1966年“十七年”间产生的、以革命历史和农村合作化为题材的长篇小说**，后来也泛指同类影视改编。代表作有**罗广斌、杨益言《红岩》**、**曲波《林海雪原》**、**杨沫《青春之歌》**、**柳青《创业史》**。其中“三红一创”指《红日》《红旗谱》《红岩》《创业史》。这批作品塑造英雄形象，影响了几代读者，也成为红色旅游与影视改编的重要来源。","pts":["十七年间革命历史与农村题材长篇","《红岩》《林海雪原》《青春之歌》《创业史》","三红一创：红日、红旗谱、红岩、创业史"],"members":[["《红岩》","罗广斌、杨益言；重庆渣滓洞、白公馆狱中斗争"],["《林海雪原》","曲波；剿匪斗争，杨子荣"],["《青春之歌》","杨沫；知识青年林道静走向革命"],["《创业史》","柳青；陕西农业合作化，梁生宝"]],"mem":"两串口诀：**“三红一创”＝红日、红旗谱、红岩、创业史；“保林青山”＝保卫延安、林海雪原、青春之歌、山乡巨变**。题面给的四部里，《红岩》《创业史》属前一串，《林海雪原》《青春之歌》属后一串。","mix":"《林海雪原》《青春之歌》不在“三红一创”里，而在“保林青山”里；《创业史》作者柳青，别与写《山乡巨变》的周立波混淆。","mcq":[{"q":"下列作品中，属于“三红一创”的是","o":["《林海雪原》","《青春之歌》","《保卫延安》","《红岩》"],"a":3,"w":"三红一创是《红日》《红旗谱》《红岩》《创业史》。"}],"rel":[{"t":"《红岩》","n":"代表作"},{"t":"《创业史》","n":"农村题材代表"},{"t":"三红一创、保林青山","n":"红色经典的两串口诀"},{"t":"周立波","n":"《山乡巨变》作者"},{"t":"《英雄儿女》","n":"同脉的红色电影"}],"more":"《保卫延安》（杜鹏程，1954）、《红日》（吴强，1957）、《红旗谱》（梁斌，1957）、《林海雪原》（曲波，1957）、《青春之歌》（杨沫，1958）、《山乡巨变》（周立波，1958）、《创业史》（柳青，1960起）、《红岩》（1961）。","exam":[]},{"id":"b08-036","t":"《义勇军进行曲》","cid":"08g","p":2,"kind":"作品","alias":["义勇军进行曲","国歌"],"one":"田汉作词、聂耳作曲，《风云儿女》主题曲，1982年定为国歌。","ans":"《义勇军进行曲》是**田汉作词、聂耳作曲**的抗战歌曲，原为1935年电影**《风云儿女》**的主题曲，以“起来！不愿做奴隶的人们”号召全民抗战，在抗战时期广为传唱。1949年新中国成立前夕被确定为**国歌**（代国歌），1982年**五届全国人大五次会议正式确定为国歌**，2004年写入宪法。它是**中国现代音乐与抗战救亡歌曲的代表作**。","pts":["田汉作词、聂耳作曲","1935年电影《风云儿女》主题曲","1949年作代国歌，1982年正式定为国歌"],"mem":"**“田词聂曲，35年风云；49年代国歌，82年正式”**。四个数字：1935（电影）、1949（代国歌）、1982（正式国歌）、2004（入宪）。聂耳只活了23岁，1935年夏在日本逝世，歌曲是他留下的绝唱。","mix":"《黄河大合唱》是冼星海作曲、光未然作词；《义勇军进行曲》作词是田汉，不是光未然。国歌歌词曾在1978年改动，1982年恢复原词。","mcq":[{"q":"国歌《义勇军进行曲》的作曲者是","o":["冼星海","聂耳","贺绿汀","黄自"],"a":1,"w":"田汉作词、聂耳作曲。"}],"rel":[{"t":"聂耳","n":"作曲者"},{"t":"田汉","n":"作词者"},{"t":"国家象征","n":"国歌是国家象征之一"},{"t":"《黄河大合唱》","n":"同属抗战音乐经典"}],"more":"电影《风云儿女》（1935，电通公司，许幸之导演）。\n歌词首句：起来！不愿做奴隶的人们！把我们的血肉，筑成我们新的长城！","exam":[]},{"id":"b08-037","t":"京派与海派","cid":"08f","p":2,"kind":"流派","alias":["京派","海派","京海之争"],"one":"1930年代京海之争：京派沈从文等写乡土人性，海派含新感觉派写都市。","ans":"京派与海派是**1930年代中国文坛的两个文学群体**，起因是1933至1934年沈从文《文学者的态度》《论“海派”》引发的论争。**京派**以北平、天津为中心，成员有**沈从文、废名、朱光潜**等，依托《大公报·文艺》，多写乡土与人性，风格冲淡。**海派**以上海为中心，含**新感觉派施蛰存、穆时英、刘呐鸥**，书写都市与商业生活。两派对举，反映了文学与城市环境的关系。","pts":["1930年代京海之争，起于沈从文批评海派","京派：沈从文、废名、朱光潜，写乡土人性","海派：新感觉派施蛰存、穆时英、刘呐鸥"],"mem":"地名定性格：**京派在古城，写乡村，慢；海派在上海，写都市，快**。人名串联：京派“沈废朱”（沈从文、废名、朱光潜），海派新感觉派“施穆刘”（施蛰存、穆时英、刘呐鸥）。","mix":"海派在广义上还包括通俗的鸳鸯蝴蝶派；狭义的海派文学常指新感觉派。张爱玲写上海，通常单列，不归入新感觉派。","mcq":[{"q":"下列作家中，属于新感觉派（海派）的是","o":["沈从文","穆时英","废名","朱光潜"],"a":1,"w":"新感觉派以施蛰存、穆时英、刘呐鸥为代表；沈从文、废名、朱光潜属京派。"}],"rel":[{"t":"沈从文","n":"京派领袖"},{"t":"新感觉派","n":"海派的现代派一支"},{"t":"海派文化","n":"上海城市文化背景"},{"t":"鸳鸯蝴蝶派","n":"广义海派的通俗一脉"}],"more":"沈从文《文学者的态度》（1933）、《论“海派”》（1934）。\n刊物：京派有《大公报·文艺》，海派新感觉派有施蛰存主编的《现代》。","exam":[]},{"id":"b08-038","t":"鸳鸯蝴蝶派","cid":"08f","p":3,"kind":"流派","exam":[],"alias":[],"one":"清末民初通俗言情小说流派，张恨水《啼笑因缘》","ans":"清末民初通俗言情小说流派，张恨水《啼笑因缘》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b08-039","t":"《朝花夕拾》创作100周年","cid":"08b","p":3,"kind":"时事","exam":[],"alias":[],"one":"1926年写成，1928年结集出版","ans":"1926年写成，1928年结集出版","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"b08-041","t":"冰心","cid":"08c","p":2,"kind":"人物","alias":["谢婉莹","冰心体"],"one":"原名谢婉莹，文学研究会成员，小诗《繁星》《春水》，《寄小读者》。","ans":"冰心（1900–1999），原名**谢婉莹**，福建长乐人，**文学研究会**重要成员，现代女作家。她受泰戈尔《飞鸟集》启发写成小诗集**《繁星》《春水》**，以哲理短诗歌颂母爱、童心与自然，被称为**“冰心体”**。通讯集**《寄小读者》**是中国现代儿童文学的经典，她还翻译了泰戈尔《吉檀迦利》《园丁集》和纪伯伦《先知》。","pts":["原名谢婉莹，文学研究会成员","小诗《繁星》《春水》，冰心体","《寄小读者》；译泰戈尔、纪伯伦"],"mem":"口诀“繁星春水冰心体”，加“爱的哲学”：母爱、童心、自然。译作配对：泰戈尔《吉檀迦利》《园丁集》，纪伯伦《先知》，三部都由冰心翻译。","mix":"泰戈尔《飞鸟集》《新月集》的早期译者是郑振铎，不是冰心；《繁星》《春水》是诗集，《寄小读者》是通讯集。","mcq":[{"q":"冰心的小诗集《繁星》《春水》主要受哪位外国诗人影响","o":["拜伦","雪莱","泰戈尔","惠特曼"],"a":2,"w":"冰心受泰戈尔《飞鸟集》的影响写成小诗。"}],"rel":[{"t":"文学研究会","n":"所属社团"},{"t":"泰戈尔","n":"所译与所受影响"},{"t":"纪伯伦","n":"所译《先知》"},{"t":"郑振铎","n":"泰戈尔另一译者"}],"more":"诗集：《繁星》《春水》\n通讯集：《寄小读者》\n译作：泰戈尔《吉檀迦利》《园丁集》，纪伯伦《先知》","exam":[]},{"id":"b08-042","t":"叶圣陶","cid":"08c","p":3,"kind":"人物","exam":[],"alias":[],"one":"文学研究会作家，童话集《稻草人》，小说《倪焕之》","ans":"文学研究会作家，童话集《稻草人》，小说《倪焕之》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"= 叶圣陶 | B | 1894–1988 | 名绍钧 |\n作 *长篇《倪焕之》 / 童话集《稻草人》\n群 文学研究会发起人之一","todo":1},{"id":"b08-043","t":"丁玲","cid":"08g","p":2,"kind":"人物","alias":["蒋冰之"],"one":"现代女作家，《莎菲女士的日记》，《太阳照在桑干河上》获斯大林文学奖。","ans":"丁玲（1904–1986），**湖南临澧人，现代女作家**，左联成员。她以**《莎菲女士的日记》**（1928）登上文坛，塑造了追求个性解放又陷入苦闷的知识女性莎菲。抗战时期奔赴延安，后以土地改革为题材写成长篇**《太阳照在桑干河上》**（1948），1951年获**斯大林文学奖**。她的创作从个人情感走向工农斗争，是**现代文学从五四到解放区文学转变的代表作家**之一。","pts":["湖南临澧人，左联成员","《莎菲女士的日记》写知识女性苦闷","《太阳照在桑干河上》获斯大林文学奖"],"mem":"丁玲两个“一”：**一个“莎菲”，一个“桑干河”**。前者在五四之后的都市，后者在土改之后的农村，作家轨迹从个人到群众。记“桑干河”＝“土地改革”＝“斯大林奖”。","mix":"《暴风骤雨》写东北土改，作者是周立波，也获斯大林文学奖；《太阳照在桑干河上》写河北涿鹿土改，作者是丁玲。","mcq":[{"q":"长篇小说《太阳照在桑干河上》的作者是","o":["周立波","赵树理","丁玲","孙犁"],"a":2,"w":"丁玲此作写土地改革，获1951年斯大林文学奖。"}],"rel":[{"t":"左联","n":"丁玲是成员"},{"t":"周立波","n":"《暴风骤雨》与之并称土改小说"},{"t":"赵树理","n":"同属解放区作家"},{"t":"延安文艺座谈会","n":"创作转向的背景"}],"more":"主要作品：《梦珂》《莎菲女士的日记》（1928）、《水》（1931）、《太阳照在桑干河上》（1948）。","exam":[]},{"id":"b08-044","t":"戴望舒","cid":"08d","p":3,"kind":"人物","exam":[],"alias":[],"one":"现代派诗人，《雨巷》，“雨巷诗人”","ans":"现代派诗人，《雨巷》，“雨巷诗人”","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"= 戴望舒 | B | 1905–1950 |  |\n作 *《雨巷》\n群 “雨巷诗人”；现代派诗歌代表","todo":1},{"id":"b08-045","t":"余光中","cid":"08h","p":3,"kind":"人物","exam":[],"alias":[],"one":"台湾诗人，《乡愁》","ans":"台湾诗人，《乡愁》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"= 余光中 | B | 1928–2017 | 台湾诗人 |\n作 *《乡愁》\n句 小时候，乡愁是一枚小小的邮票，我在这头，母亲在那头。｜《乡愁》","todo":1},{"id":"b08-046","t":"金庸","cid":"08h","p":3,"kind":"人物","exam":[],"alias":[],"one":"武侠小说家，《射雕英雄传》《天龙八部》《鹿鼎记》","ans":"武侠小说家，《射雕英雄传》《天龙八部》《鹿鼎记》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"= 金庸 | B | 1924–2018 | 原名查良镛 |\n作 *《射雕英雄传》 / 《神雕侠侣》 / 《天龙八部》 / 《笑傲江湖》 / 《鹿鼎记》\n群 十四部作品首字联：“飞雪连天射白鹿，笑书神侠倚碧鸳”","todo":1},{"id":"z60-001","t":"黄遵宪","cid":"08a","p":2,"kind":"人物","alias":["黄公度","人境庐"],"one":"晚清外交家、诗人，“诗界革命”旗帜，主张“我手写我口”。","ans":"黄遵宪（1848–1905）是**晚清外交家、诗人**，广东嘉应州（今梅州）人，曾任驻日使馆参赞、驻旧金山总领事等职。他是梁启超所倡**“诗界革命”**的旗帜，主张“**我手写我口**，古岂能拘牵”，要求以口语和新事物入诗。代表作有诗集**《人境庐诗草》**和史书**《日本国志》**，诗作以新思想、新见闻入旧体，为后来白话新诗铺了路。","pts":["晚清外交家、诗人，诗界革命旗帜","“我手写我口”（《杂感》）","《人境庐诗草》《日本国志》"],"mem":"画面：一个人提笔，笔尖流出的是口语，这就是“我手写我口”。分工口诀：梁启超“倡”，黄遵宪“旗”。书名对应：《日本国志》写日本，《人境庐诗草》的“人境”取自陶渊明“结庐在人境”。","mix":"提出“诗界革命”口号的是梁启超（1899年），黄遵宪是实践者和旗帜；“我手写我口”与胡适后来的白话诗主张相通，但黄遵宪写的仍是旧体诗。","mcq":[{"q":"“我手写我口，古岂能拘牵”的作者是","o":["梁启超","康有为","黄遵宪","胡适"],"a":2,"w":"出自黄遵宪《杂感》，是诗界革命的代表主张。"}],"rel":[{"t":"诗界革命","n":"他是旗帜"},{"t":"梁启超","n":"提出诗界革命"},{"t":"胡适","n":"白话诗主张的后继"}],"more":"我手写我口，古岂能拘牵！｜《杂感》\n诗集：《人境庐诗草》\n史书：《日本国志》","exam":[]},{"id":"z60-002","t":"梁启超","cid":"08a","p":1,"kind":"人物","alias":["梁任公","任公","饮冰室主人","卓如"],"one":"晚清维新派领袖，倡诗界、小说界、文界革命，著《少年中国说》。","ans":"梁启超（1873–1929），字卓如，号任公，**广东新会人，晚清维新派领袖**，与康有为并称“康梁”。戊戌变法失败后流亡日本，创办《清议报》《新民丛报》《新小说》，倡导**“诗界革命”“小说界革命”“文界革命”**，1902年发表**《论小说与群治之关系》**，主张以小说改良群治、新民。代表作有**《少年中国说》**《新民说》，著作汇编为《饮冰室合集》。晚年任**清华国学研究院导师**，为四大导师之一。","pts":["康梁，戊戌变法失败后流亡日本","诗界、小说界、文界三革命","《少年中国说》；清华四大导师之一"],"mem":"“三界革命”顺序记“诗、小说、文”。清华四大导师自编口诀“梁王陈赵”（梁启超、王国维、陈寅恪、赵元任）。《少年中国说》名句用“智、富、强”三字：少年智则国智，少年富则国富，少年强则国强。","mix":"“诗界革命”理论由梁启超倡导，实践代表诗人是黄遵宪；清华四大导师含赵元任，不含胡适；“康梁”中康有为是维新领袖，梁启超是其弟子。","mcq":[{"q":"1902年发表《论小说与群治之关系》、倡导“小说界革命”的是","o":["严复","王国维","黄遵宪","梁启超"],"a":3,"w":"梁启超1902年在《新小说》创刊时发表此文。"},{"q":"下列人物中，不属于清华国学研究院四大导师的是","o":["梁启超","王国维","胡适","陈寅恪"],"a":2,"w":"四大导师为梁启超、王国维、陈寅恪、赵元任。"}],"rel":[{"t":"诗界革命","n":"三界革命之一"},{"t":"“小说界革命”","n":"三界革命之一"},{"t":"黄遵宪","n":"诗界革命实践者"},{"t":"清华国学研究院四大导师","n":"四大导师之一"},{"t":"严复","n":"同为晚清思想家"}],"more":"名句：少年智则国智，少年富则国富，少年强则国强。｜《少年中国说》\n主要作品：《少年中国说》《论小说与群治之关系》《新民说》《饮冰室合集》","exam":[]},{"id":"z60-003","t":"王国维","cid":"08a","p":1,"kind":"人物","alias":["王静安","静安","观堂","王观堂"],"one":"近代学者，《人间词话》提出“境界说”，清华四大导师之一。","ans":"王国维（1877–1927），字静安，号观堂，**浙江海宁人，近代学者**，清华国学研究院四大导师之一。他把西方哲学美学引入传统批评，在**《人间词话》**中提出**“境界说”**，以“有境界”为词的最高标准，并分有我之境与无我之境，又以三种境界喻治学。所著**《宋元戏曲史》**是第一部系统的中国戏曲史；史学上倡**“二重证据法”**，以地下出土材料印证文献。1927年投颐和园昆明湖自尽。","pts":["《人间词话》，“境界说”","《宋元戏曲史》；二重证据法","清华四大导师，号观堂，列甲骨四堂"],"mem":"治学三境界出处：晏殊（昨夜西风凋碧树）、柳永（衣带渐宽终不悔）、辛弃疾（众里寻他千百度）。自编口诀“晏柳辛”，对应立志、执着、顿悟。“观堂”入甲骨四堂：雪观彦鼎（罗振玉、王国维、董作宾、郭沫若）。","mix":"三境界引的是晏殊《蝶恋花》、柳永《凤栖梧》、辛弃疾《青玉案》，王国维只是借用；《人间词话》是词论，不是诗论。","mcq":[{"q":"《人间词话》的作者是","o":["梁启超","王国维","胡适","陈寅恪"],"a":1,"w":"王国维在《人间词话》中提出“境界说”。"},{"q":"“众里寻他千百度，蓦然回首，那人却在灯火阑珊处”，被王国维引为治学第三境界，其作者是","o":["辛弃疾","晏殊","柳永","李清照"],"a":0,"w":"出自辛弃疾《青玉案·元夕》。"}],"rel":[{"t":"《人间词话》","n":"代表作"},{"t":"清华国学研究院四大导师","n":"四大导师之一"},{"t":"甲骨四堂","n":"号观堂"},{"t":"梁启超","n":"同为清华导师"}],"more":"名句：古今之成大事业、大学问者，必经过三种之境界。｜《人间词话》\n主要作品：《人间词话》《宋元戏曲史》《殷周制度论》《红楼梦评论》","exam":[]},{"id":"z60-006","t":"谭嗣同","cid":"08a","p":3,"kind":"人物","exam":[],"alias":[],"one":"1865–1898，戊戌六君子之一","ans":"1865–1898，戊戌六君子之一","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《仁学》 / 《狱中题壁》\n句 我自横刀向天笑，去留肝胆两昆仑。｜《狱中题壁》","todo":1},{"id":"z60-007","t":"秋瑾","cid":"08a","p":3,"kind":"人物","exam":[],"alias":[],"one":"1875–1907，号鉴湖女侠","ans":"1875–1907，号鉴湖女侠","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《满江红·小住京华》 / 《宝刀歌》","todo":1},{"id":"z60-009","t":"胡适","cid":"08a","p":1,"kind":"人物","alias":["胡适之","适之"],"one":"新文化运动领袖，《文学改良刍议》发动文学革命，《尝试集》为首部白话新诗集。","ans":"胡适（1891–1962），字适之，**安徽绩溪人，新文化运动代表人物**，曾留学美国，受业于杜威，后任北京大学教授。1917年1月在《新青年》发表**《文学改良刍议》**，提出**“八事”**，主张以白话取代文言，成为**文学革命**的发端。1920年出版**《尝试集》**，是**第一部白话新诗集**。他还著有《中国哲学史大纲》《白话文学史》，治学倡导**“大胆假设，小心求证”**。他的主张使白话文进入文学与教育，奠定现代汉语书面语的方向。","pts":["《文学改良刍议》（1917），“八事”","《尝试集》（1920），第一部白话新诗集","大胆假设，小心求证；杜威弟子"],"mem":"“八事”前四后四各取一字：物、古、法、病，套、典、对、俗（言之有物、不摹仿古人、讲求文法、不作无病呻吟，务去烂调套语、不用典、不讲对仗、不避俗字俗语）。自编。年份挂钩：17 年刍议，20 年尝试。","mix":"胡适提出“八事”，陈独秀《文学革命论》提出“三大主义”；《尝试集》（1920）是最早的白话新诗集，郭沫若《女神》（1921）是新诗奠基之作。","mcq":[{"q":"第一部白话新诗集是","o":["郭沫若《女神》","闻一多《红烛》","冰心《繁星》","胡适《尝试集》"],"a":3,"w":"《尝试集》1920年出版。"},{"q":"胡适在《文学改良刍议》中提出的主张称为","o":["三大主义","三美","八事","五不"],"a":2,"w":"陈独秀的主张才是“三大主义”。"}],"rel":[{"t":"文学革命","n":"发动者之一"},{"t":"陈独秀","n":"并肩倡导者"},{"t":"郭沫若《女神》","n":"新诗奠基之作"},{"t":"《新青年》","n":"发表阵地"}],"more":"名句：大胆假设，小心求证。\n主要作品：《文学改良刍议》（1917）、《尝试集》（1920）、《中国哲学史大纲》、《白话文学史》","exam":[]},{"id":"z60-010","t":"陈独秀","cid":"08a","p":2,"kind":"人物","alias":["仲甫"],"one":"《新青年》创办者，发表《文学革命论》，中国共产党创始人之一。","ans":"陈独秀（1879–1942）字仲甫，**安徽怀宁人**，新文化运动的主要发起人。1915年他在上海创办**《青年杂志》**，次年改名**《新青年》**，倡导民主与科学。1917年他发表**《文学革命论》**，提出推倒贵族文学、古典文学、山林文学，建设国民文学、写实文学、社会文学的**“三大主义”**，与胡适《文学改良刍议》相呼应，同年出任北京大学文科学长。他也是中国共产党的创始人之一。","pts":["1915年创办《青年杂志》（《新青年》）","1917年《文学革命论》，文学三大主义","与胡适并为文学革命发动者"],"mem":"口诀“胡八陈三”：胡适《文学改良刍议》提“八不主义”，陈独秀《文学革命论》提“三大主义”。胡适讲“改良”，陈独秀讲“革命”，措辞更激烈，所以后人把这一场运动叫“文学革命”。","mix":"《文学改良刍议》（胡适，八不主义）与《文学革命论》（陈独秀，三大主义）常被对举；钱玄同、刘半农支持二人，1918年唱“双簧信”。","mcq":[{"q":"1917年在《新青年》发表《文学革命论》，提出推倒“贵族文学、古典文学、山林文学”的是","o":["胡适","陈独秀","钱玄同","李大钊"],"a":1,"w":"陈独秀《文学革命论》提出三大主义；胡适的文章是《文学改良刍议》。"}],"rel":[{"t":"《新青年》","n":"他所创办"},{"t":"胡适","n":"与之并为发动者"},{"t":"文学革命","n":"《文学革命论》发动"},{"t":"五四新文化运动","n":"主要发起人"}],"more":"《文学革命论》（1917年2月，《新青年》2卷6号）\n三大主义：推倒雕琢的阿谀的贵族文学，建设平易的抒情的国民文学；推倒陈腐的铺张的古典文学，建设新鲜的立诚的写实文学；推倒迂晦的艰涩的山林文学，建设明了的通俗的社会文学。","exam":[]},{"id":"z60-011","t":"周作人","cid":"08c","p":3,"kind":"人物","exam":[],"alias":[],"one":"1885–1967，鲁迅二弟","ans":"1885–1967，鲁迅二弟","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《人的文学》 / 散文《乌篷船》\n群 文学研究会发起人之一","todo":1},{"id":"z60-012","t":"郭沫若","cid":"08c","p":1,"kind":"人物","alias":["郭开贞","鼎堂","沫若"],"one":"创造社发起人，《女神》奠基新诗，历史剧《屈原》作者。","ans":"郭沫若（1892–1978），**原名郭开贞，四川乐山人，诗人、剧作家、历史学家**，**创造社**发起人之一。1921年出版诗集**《女神》**，含《凤凰涅槃》《天狗》《炉中煤》，以奔放的自由体表现五四时代精神，是**中国新诗的奠基之作**。抗战时期创作历史剧**《屈原》**（1942），另有《棠棣之花》《蔡文姬》等；史论《甲申三百年祭》总结李自成起义的教训。他在古文字和古史研究上有成就，号**鼎堂**，列“甲骨四堂”。","pts":["原名郭开贞，创造社发起人","诗集《女神》，新诗奠基","历史剧《屈原》；号鼎堂，甲骨四堂"],"mem":"《女神》三篇画面：凤凰在烈火中重生（凤凰涅槃），天狗吞下日月（天狗），煤在炉中燃烧自比祖国（炉中煤）。甲骨四堂口诀“雪观彦鼎”：罗振玉雪堂、王国维观堂、董作宾彦堂、郭沫若鼎堂。","mix":"话剧《屈原》作者是郭沫若，《雷雨》才是曹禺；《尝试集》最早，《女神》是奠基之作。","mcq":[{"q":"诗集《女神》的作者是","o":["胡适","闻一多","徐志摩","郭沫若"],"a":3,"w":"1921年出版。"},{"q":"“甲骨四堂”中，号“鼎堂”的是","o":["王国维","罗振玉","郭沫若","董作宾"],"a":2,"w":"观堂是王国维，雪堂罗振玉，彦堂董作宾。"}],"rel":[{"t":"创造社","n":"所属社团"},{"t":"郭沫若《女神》","n":"代表诗集"},{"t":"甲骨四堂","n":"号鼎堂"},{"t":"曹禺","n":"同为话剧作家"},{"t":"屈原","n":"历史剧《屈原》的主人公"}],"more":"主要作品：诗集《女神》（1921），历史剧《屈原》《棠棣之花》《蔡文姬》，史论《甲申三百年祭》\n《女神》名篇：《凤凰涅槃》《天狗》《炉中煤》","exam":[]},{"id":"z60-016","t":"曹禺","cid":"08e","p":1,"kind":"人物","alias":["万家宝"],"one":"原名万家宝，《雷雨》作者，中国现代话剧成熟的标志。","ans":"曹禺（1910–1996），**原名万家宝，天津人，祖籍湖北潜江，现代剧作家**，**中国现代话剧成熟的标志性人物**。1934年发表处女作**《雷雨》**，写周、鲁两家三十年的恩怨，人物有周朴园、繁漪、鲁侍萍、周萍、四凤；此后有**《日出》《原野》《北京人》**，并把巴金《家》改编为话剧。他的剧作结构严谨，心理刻画深，揭露封建家庭与旧社会的罪恶，**确立了现代话剧的艺术高度**。《雷雨》有王佐良、巴恩斯合译的英文版。","pts":["原名万家宝，现代话剧成熟标志","《雷雨》《日出》《原野》《北京人》","改编巴金《家》；周朴园、繁漪"],"mem":"四部名作按时间排：雷雨（1934）、日出（1936）、原野（1937）、北京人（1941），自编口诀“雷日原北”。前三部名字像天气与旷野，最后一部才点出“人”。《雷雨》人物顺口记“朴园繁漪，侍萍四凤”。","mix":"《茶馆》是老舍的话剧，《屈原》是郭沫若的话剧；曹禺把巴金小说《家》改编成话剧，作者仍是巴金。","mcq":[{"q":"下列人物出自曹禺《雷雨》的是","o":["王利发","周朴园","祥子","吴荪甫"],"a":1,"w":"王利发出自《茶馆》，祥子出自《骆驼祥子》，吴荪甫出自《子夜》。"},{"q":"下列作品不属于曹禺的是","o":["《茶馆》","《日出》","《原野》","《北京人》"],"a":0,"w":"《茶馆》是老舍的话剧。"}],"rel":[{"t":"曹禺《雷雨》","n":"代表作"},{"t":"老舍","n":"同为话剧大家"},{"t":"春柳社与中国话剧开端","n":"中国话剧的起点"},{"t":"易卜生","n":"西方现代戏剧对照"},{"t":"巴金","n":"改编其小说《家》"}],"more":"主要作品：《雷雨》（1934）、《日出》（1936）、《原野》（1937）、《北京人》（1941）；改编巴金《家》（1942）","exam":[]},{"id":"z60-018","t":"徐志摩","cid":"08d","p":2,"kind":"人物","alias":["志摩"],"one":"新月派代表诗人，《再别康桥》作者。","ans":"徐志摩（1897–1931），**浙江海宁人**，**新月派**代表诗人。他早年游学英国剑桥，受浪漫主义诗歌影响，回国后参与创办新月社和《新月》月刊。诗集有《志摩的诗》《翡冷翠的一夜》《猛虎集》，代表作**《再别康桥》**“轻轻的我走了，正如我轻轻的来”，兼具**音乐美、绘画美、建筑美**，是格律新诗的典范。1931年11月因飞机失事去世。","pts":["新月派代表诗人，浙江海宁","《再别康桥》《沙扬娜拉》《猛虎集》","格律诗，音乐美绘画美建筑美"],"mem":"口诀“徐康桥，闻死水”：徐志摩《再别康桥》，闻一多《死水》，二人同属新月派。画面：金柳、夕阳、软泥上的青荇，《再别康桥》全诗是一幅画。","mix":"“三美”理论是闻一多提出的，徐志摩的《再别康桥》是实践；《雨巷》是现代派戴望舒，不是新月派。","mcq":[{"q":"“轻轻的我走了，正如我轻轻的来”出自","o":["《死水》","《雨巷》","《再别康桥》","《我爱这土地》"],"a":2,"w":"出自徐志摩《再别康桥》。"}],"rel":[{"t":"新月派与新诗“三美”","n":"所属流派"},{"t":"闻一多","n":"同属新月派"},{"t":"戴望舒","n":"现代派对照"},{"t":"雪莱","n":"所受浪漫主义影响"}],"more":"轻轻的我走了，正如我轻轻的来；我轻轻的招手，作别西天的云彩。｜《再别康桥》\n《志摩的诗》《翡冷翠的一夜》《猛虎集》《云游》\n《沙扬娜拉》《偶然》","exam":[]},{"id":"z60-019","t":"闻一多","cid":"08d","p":2,"kind":"人物","alias":["闻一多"],"one":"新月派诗人、学者，《红烛》《死水》，提出新诗“三美”。","ans":"闻一多（1899–1946），**湖北浠水人**，**新月派**诗人、学者。他在《诗的格律》中提出新诗**“三美”**：**音乐美、绘画美、建筑美**。诗集有**《红烛》《死水》**，1925年留学美国时写下组诗**《七子之歌》**，其中《澳门》在1999年澳门回归时广为传唱。抗战后期任教西南联大，1946年7月在昆明发表《最后一次讲演》后遇刺牺牲。","pts":["新月派，提出“三美”","《红烛》《死水》《七子之歌》","1946年发表《最后一次讲演》后遇刺"],"mem":"三美口诀“音、画、建”：音乐美（音节）、绘画美（词藻）、建筑美（节匀句齐）。画面：《死水》每节四行、每行九字，整齐如豆腐块，就是建筑美。人物线：诗人闻一多变成战士，最后一次讲演后牺牲。","mix":"许渊冲译诗“三美”是意美、音美、形美，与闻一多的“三美”不同；《七子之歌·澳门》1999年传唱，作者是闻一多。","mcq":[{"q":"闻一多提出的新诗“三美”是","o":["意美、音美、形美","音乐美、绘画美、建筑美","情美、景美、境美","音美、形美、神美"],"a":1,"w":"闻一多“三美”为音乐美、绘画美、建筑美；意美、音美、形美是许渊冲的译诗主张。"}],"rel":[{"t":"新月派与新诗“三美”","n":"所属流派与主张"},{"t":"徐志摩","n":"同属新月派"},{"t":"许渊冲“三美”","n":"同名不同义"},{"t":"艾青","n":"同为现代诗人"}],"more":"诗集：《红烛》（1923）、《死水》（1928）\n组诗《七子之歌》（1925）\n这是一沟绝望的死水，清风吹不起半点漪沦。｜《死水》\n《最后一次讲演》（1946年7月15日）","exam":[]},{"id":"z60-029","t":"钱锺书","cid":"08f","p":2,"kind":"人物","alias":["钱钟书","默存"],"one":"现代学者、作家，长篇小说《围城》作者，学术巨著《管锥编》。","ans":"钱锺书（1910–1998），字默存，**江苏无锡人，现代学者、作家**。他的长篇小说**《围城》**（1947）写留学归国的方鸿渐在婚姻与职业上的困境，以讽刺笔调刻画知识分子，“围在城里的人想逃出来，城外的人想冲进去”广为流传。学术著作有**《管锥编》《谈艺录》《宋诗选注》**，散文集有《写在人生边上》。他提出翻译的**“化境”说**，夫人是杨绛。","pts":["无锡人，学者兼小说家，字默存","《围城》（1947）讽刺知识分子；《管锥编》《谈艺录》","提出翻译“化境”说，夫人杨绛"],"mem":"一人三面：**小说《围城》，学问《管锥编》，翻译“化境”**。《围城》名句可以记成“城里想出，城外想进”，看到“围”字就联想钱锺书。夫妻对举：钱写《围城》，杨绛写《我们仨》。","mix":"《干校六记》《我们仨》是杨绛的作品；“信达雅”是严复，“神似”是傅雷，“化境”才是钱锺书。","mcq":[{"q":"下列作品中，不属于钱锺书的是","o":["《管锥编》","《谈艺录》","《宋诗选注》","《干校六记》"],"a":3,"w":"《干校六记》是杨绛的作品。"}],"rel":[{"t":"杨绛","n":"夫人，作家与翻译家"},{"t":"钱锺书《围城》","n":"代表小说"},{"t":"钱锺书“化境”","n":"翻译理论"},{"t":"傅雷","n":"“神似”与“化境”常对举"}],"more":"《围城》最初连载于《文艺复兴》，1947年由晨光出版公司出版。\n翻译“化境”说见《林纾的翻译》（1964）。","exam":[]},{"id":"z60-030","t":"杨绛","cid":"08f","p":2,"kind":"人物","alias":["杨季康"],"one":"作家、翻译家，钱锺书夫人，《我们仨》作者，《堂吉诃德》译者。","ans":"杨绛（1911–2016），原名杨季康，祖籍江苏无锡，**现代作家、翻译家、剧作家**，钱锺书的夫人。她的散文《干校六记》（1981）记述在干校的生活，**《我们仨》**（2003）回忆与钱锺书、女儿钱瑗的三口之家，长篇小说有**《洗澡》**。她从**西班牙文直接翻译《堂吉诃德》**，译本质量被广泛推崇。她活到105岁。","pts":["钱锺书夫人，作家兼翻译家","《我们仨》《干校六记》《洗澡》","从西班牙文直译《堂吉诃德》"],"mem":"“杨绛三件事”：**写《我们仨》，记《干校六记》，译《堂吉诃德》**。她的译本从西班牙文直接译出，不是从英文转译，选择题常问这一点。","mix":"《围城》是钱锺书所作，不是杨绛；《堂吉诃德》的作者是塞万提斯，杨绛是中文译者。","mcq":[{"q":"《堂吉诃德》的中文直译本（从西班牙文译出）的译者是","o":["杨绛","傅雷","朱生豪","钱锺书"],"a":0,"w":"杨绛从西班牙文原著直接译出《堂吉诃德》，1978年出版。"}],"rel":[{"t":"钱锺书","n":"丈夫"},{"t":"《堂吉诃德》","n":"其代表译作"},{"t":"塞万提斯","n":"《堂吉诃德》原作者"},{"t":"傅雷","n":"现代著名翻译家"}],"more":"主要作品：《我们仨》《干校六记》《洗澡》《将饮茶》；剧本《称心如意》《弄真成假》；译作《堂吉诃德》。","exam":[]},{"id":"z60-033","t":"孙犁","cid":"08g","p":3,"kind":"人物","exam":[],"alias":[],"one":"1913–2002","ans":"1913–2002","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《荷花淀》\n群 “荷花淀派”","todo":1},{"id":"z60-034","t":"周立波","cid":"08g","p":3,"kind":"人物","exam":[],"alias":[],"one":"1908–1979","ans":"1908–1979","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《暴风骤雨》 / 《山乡巨变》","todo":1},{"id":"z60-035","t":"夏衍","cid":"08e","p":3,"kind":"人物","exam":[],"alias":[],"one":"1900–1995","ans":"1900–1995","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 报告文学《包身工》（上海纱厂女工） / 话剧《上海屋檐下》","todo":1},{"id":"z60-036","t":"臧克家","cid":"08d","p":3,"kind":"人物","exam":[],"alias":[],"one":"1905–2004","ans":"1905–2004","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《有的人》（纪念鲁迅） / 《老马》\n句 有的人活着，他已经死了；有的人死了，他还活着。｜《有的人》","todo":1},{"id":"z60-037","t":"卞之琳","cid":"08d","p":3,"kind":"人物","exam":[],"alias":[],"one":"1910–2000","ans":"1910–2000","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《断章》\n句 你站在桥上看风景，看风景人在楼上看你。｜《断章》","todo":1},{"id":"z70-001","t":"路遥","cid":"08i","p":2,"kind":"人物","alias":["王卫国"],"one":"陕西作家，《平凡的世界》获第三届茅盾文学奖，中篇《人生》。","ans":"路遥（1949–1992），原名**王卫国**，**陕西清涧人，当代作家**，写作植根陕北黄土高原。中篇小说**《人生》**（1982）写农村青年高加林的进城与回乡，引起广泛讨论。三部六卷长篇**《平凡的世界》**（1986–1988）以孙少安、孙少平兄弟为主线，展现改革开放初期农村的变迁，获**第三届茅盾文学奖**（1991）。他的作品以现实主义见长，是**陕西作家群的代表**。","pts":["陕西作家，原名王卫国","中篇《人生》，长篇《平凡的世界》","《平凡的世界》获第三届茅盾文学奖"],"mem":"**“路遥—人生—平凡”**：先《人生》（高加林），再《平凡的世界》（孙少平）。与陈忠实并记：**路遥《平凡的世界》（第三届）、陈忠实《白鹿原》（第四届）**，两位陕西作家的茅奖连着两届。","mix":"陈忠实《白鹿原》属第四届茅奖，别与《平凡的世界》（第三届）混；余华《活着》并未获茅盾文学奖。","mcq":[{"q":"路遥的《平凡的世界》获得的是","o":["第一届茅盾文学奖","第二届茅盾文学奖","第四届茅盾文学奖","第三届茅盾文学奖"],"a":3,"w":"《平凡的世界》获1991年第三届茅盾文学奖。"}],"rel":[{"t":"《平凡的世界》","n":"代表作"},{"t":"陈忠实","n":"同为陕西作家"},{"t":"贾平凹","n":"同为陕西作家"},{"t":"茅盾文学奖","n":"所获奖项"}],"more":"主要作品：《人生》《平凡的世界》；散文《早晨从中午开始》。\n《人生》主人公高加林，《平凡的世界》主人公孙少安、孙少平。","exam":[]},{"id":"z70-002","t":"陈忠实","cid":"08i","p":2,"kind":"人物","alias":["陈忠实老师"],"one":"陕西作家，《白鹿原》作者，获第四届茅盾文学奖。","ans":"陈忠实（1942–2016），**陕西西安人，当代作家**。长篇小说**《白鹿原》**（1993年出版）以白、鹿两家的恩怨为主线，写渭河平原从**清末到新中国成立前后**半个世纪的变迁，塑造了**白嘉轩、鹿子霖**等人物，卷首引巴尔扎克“小说是一个民族的秘史”。它获**第四届茅盾文学奖**（1997），被视为**当代长篇小说的经典**，与路遥同属陕西作家群。","pts":["陕西作家，《白鹿原》（1993）","白、鹿两家，写清末到新中国成立前后","获第四届茅盾文学奖"],"mem":"**“白鹿原＝白家＋鹿家”**：白嘉轩与鹿子霖，两家人对一片原。年份连记：路遥1991（三），陈忠实1997（四）；“陕西双雄”。","mix":"《平凡的世界》（路遥）是第三届茅奖，《白鹿原》（陈忠实）是第四届；贾平凹《秦腔》是第七届茅奖。","mcq":[{"q":"下列作品中，作者是陈忠实的是","o":["《白鹿原》","《平凡的世界》","《废都》","《秦腔》"],"a":0,"w":"《平凡的世界》是路遥，《废都》《秦腔》是贾平凹。"}],"rel":[{"t":"《白鹿原》","n":"代表作"},{"t":"路遥","n":"同为陕西作家"},{"t":"贾平凹","n":"同为陕西作家"},{"t":"茅盾文学奖","n":"所获奖项"}],"more":"陈忠实《白鹿原》1993年出版，是“陕军东征”的代表作之一。\n人物：白嘉轩、鹿子霖、黑娃、田小娥。","exam":[]},{"id":"z70-004","t":"余华","cid":"08i","p":2,"kind":"人物","alias":["余华老师"],"one":"先锋作家，《活着》《许三观卖血记》，浙江海盐人。","ans":"余华（1960– ），**浙江海盐人，当代作家**，**先锋文学的代表**，后转向现实主义。早期有《十八岁出门远行》《现实一种》等，以冷峻的叙述著称。长篇小说**《活着》**（1992）写福贵一生中亲人相继离世，仍然顽强活下去，后被**张艺谋改编为同名电影**；**《许三观卖血记》**（1995）写底层人的生存。另有《在细雨中呼喊》《兄弟》《文城》。","pts":["浙江海盐人，先锋文学代表","《活着》（张艺谋改编）《许三观卖血记》","《在细雨中呼喊》《兄弟》《文城》"],"mem":"**“余华—活着—福贵”**，电影“活着”是张艺谋，卖血的是许三观。记三个书名：“活着”（福贵）、“卖血”（许三观）、“呼喊”（细雨中），都是写苦难里人的韧性。","mix":"《活着》并未获茅盾文学奖；《许三观卖血记》不是张艺谋所拍；余华是浙江人，不是陕西作家。","mcq":[{"q":"被张艺谋改编为同名电影的余华小说是","o":["《活着》","《许三观卖血记》","《兄弟》","《文城》"],"a":0,"w":"《活着》（1992）后由张艺谋改编电影。"}],"rel":[{"t":"《活着》","n":"代表作"},{"t":"先锋文学","n":"所属思潮"},{"t":"莫言","n":"同时代重要作家"},{"t":"史铁生","n":"同为新时期作家"}],"more":"主要作品：《十八岁出门远行》《现实一种》《在细雨中呼喊》《活着》《许三观卖血记》《兄弟》《文城》。","exam":[]},{"id":"z70-005","t":"贾平凹","cid":"08i","p":3,"kind":"人物","exam":[],"alias":[],"one":"1952–，陕西人","ans":"1952–，陕西人","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《废都》 / *《秦腔》（第七届茅盾文学奖） / 《山本》","todo":1},{"id":"z70-006","t":"王安忆","cid":"08i","p":2,"kind":"人物","alias":["王安忆老师"],"one":"上海作家，《长恨歌》获第五届茅盾文学奖，写王琦瑶四十年。","ans":"王安忆（1954– ），**上海作家**，母亲是作家茹志鹃。她早年的《小鲍庄》（1985）带有寻根色彩，长篇小说**《长恨歌》**（1995）写上海女子**王琦瑶**从1940年代的选美，到1980年代的**四十年**命运，以女性的一生写出上海的城市史，获**第五届茅盾文学奖**（2000）。她另有《天香》《一把刀，千个字》，是**海派文学在当代的重要传人**。","pts":["上海作家，《小鲍庄》《天香》","《长恨歌》写王琦瑶四十年","获第五届茅盾文学奖"],"mem":"**“长恨歌＝王琦瑶＝上海”**。“长恨歌”三个字别和白居易混：**白居易写李杨悲剧，王安忆写上海小姐**。上海三作家茅奖：王安忆《长恨歌》（五）、金宇澄《繁花》（九）、孙甘露《千里江山图》（十一）。","mix":"白居易《长恨歌》写唐明皇与杨贵妃；王安忆《长恨歌》借题写上海女子。作者不同，别混。","mcq":[{"q":"王安忆《长恨歌》的女主人公是","o":["林道静","王琦瑶","杜丽娘","白流苏"],"a":1,"w":"白流苏是张爱玲《倾城之恋》的人物，王琦瑶才是《长恨歌》女主人公。"}],"rel":[{"t":"白居易《长恨歌》《琵琶行》","n":"同名诗作，别混"},{"t":"金宇澄","n":"同为上海作家"},{"t":"海派文化","n":"海派文学的当代延续"},{"t":"张爱玲","n":"上海书写的前辈"}],"more":"主要作品：《小鲍庄》《长恨歌》《天香》《一把刀，千个字》。\n《长恨歌》获第五届茅盾文学奖（2000）。","exam":[]},{"id":"z70-007","t":"金宇澄","cid":"08i","p":2,"kind":"人物","alias":["金宇澄老师"],"one":"上海作家，以沪语写《繁花》，获第九届茅盾文学奖。","ans":"金宇澄（1952– ），**上海作家**。长篇小说**《繁花》**（2012年发表于《收获》）**以沪语写作**，以1960年代与1990年代两条线索写上海市民生活，语言有浓重的地方特色。《繁花》获**第九届茅盾文学奖**（2015）。2023年底，**王家卫执导**的同名电视剧播出，使这部小说再度受到关注。他是**当代以方言写作的重要作家**。","pts":["上海作家，《繁花》","沪语写作，写1960年代与1990年代上海","获第九届茅盾文学奖，王家卫改编电视剧"],"mem":"**“繁花＝沪语＝1960+1990”**，两个年代两条线。电视剧导演王家卫＝“上海味道”。同届茅奖（第九届）还有王蒙《这边风景》。","mix":"《繁花》（金宇澄，第九届）、《长恨歌》（王安忆，第五届）、《千里江山图》（孙甘露，第十一届）都是上海作家的茅奖作品，别串届别。","mcq":[{"q":"以沪语写作并获第九届茅盾文学奖的小说是","o":["《繁花》","《长恨歌》","《千里江山图》","《白鹿原》"],"a":0,"w":"金宇澄《繁花》获第九届茅盾文学奖（2015）。"}],"rel":[{"t":"王安忆","n":"另一位上海作家"},{"t":"孙甘露","n":"另一位茅奖上海作家"},{"t":"海派文化","n":"上海城市文化背景"},{"t":"茅盾文学奖","n":"所获奖项"}],"more":"《繁花》2012年在《收获》发表，2013年出版；王家卫同名电视剧2023年12月播出。","exam":[]},{"id":"z70-008","t":"孙甘露","cid":"08i","p":3,"kind":"人物","exam":[],"alias":[],"one":"1959–，上海作家","ans":"1959–，上海作家","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 *《千里江山图》（第十一届茅盾文学奖，2023） / 先锋小说《访问梦境》\n群 写 1933 年上海地下党转移中央领导人的行动\n混 北宋王希孟有同名青绿山水画《千里江山图》","todo":1},{"id":"z70-009","t":"刘慈欣","cid":"08i","p":2,"kind":"人物","exam":["2025名解"],"alias":["大刘","Liu Cixin"],"one":"科幻作家，《三体》三部曲作者，2015年获雨果奖，亚洲作家首次。","ans":"刘慈欣（1963– ），**中国当代科幻作家**，长期在山西阳泉工作。代表作**《三体》三部曲**（《三体》《黑暗森林》《死神永生》），其英译本（**刘宇昆译**）**2015年获雨果奖最佳长篇小说**，是**亚洲作家首次获该奖**。另有**《流浪地球》**（2019年改编为郭帆导演的电影）、《球状闪电》。他把中国科幻带到世界舞台，是**中国科幻“四大天王”之一**。","pts":["山西阳泉，科幻作家","《三体》三部曲，2015年雨果奖","《流浪地球》电影（2019）；亚洲首位"],"mem":"**“三体三部曲＝三部名：三体、黑暗森林、死神永生”**；记年份“2015雨果奖，刘宇昆译”。郝景芳2016年凭《北京折叠》获雨果奖中短篇，和刘慈欣相差一年、体裁不同。","mix":"郝景芳《北京折叠》获2016年雨果奖最佳中短篇；刘慈欣《三体》获2015年最佳长篇。中国科幻“四大天王”指刘慈欣、王晋康、韩松、何夕。","mcq":[{"q":"2015年获雨果奖最佳长篇小说的中国作家是","o":["郝景芳","莫言","刘慈欣","余华"],"a":2,"w":"刘慈欣《三体》英译本2015年获雨果奖，亚洲作家首次。"},{"q":"《三体》英译本的译者是","o":["刘宇昆","葛浩文","姜戎","郝景芳"],"a":0,"w":"刘宇昆（Ken Liu）译《三体》，2015年获雨果奖。"}],"rel":[{"t":"《三体》","n":"代表作"},{"t":"《流浪地球》","n":"改编电影代表"},{"t":"雨果奖","n":"所获奖项"},{"t":"郝景芳《北京折叠》","n":"2016年雨果奖，常对比"},{"t":"刘宇昆","n":"《三体》英译者"}],"more":"主要作品：《三体》三部曲、《流浪地球》《球状闪电》《乡村教师》。\n《三体》2006年起在《科幻世界》连载。"},{"id":"z70-010","t":"史铁生","cid":"08h","p":2,"kind":"人物","alias":["铁生"],"one":"当代作家，《我与地坛》作者，21岁双腿瘫痪后写作。","ans":"史铁生（1951–2010），**北京人，当代作家**。他在陕北插队返京后因病，21岁起双腿瘫痪，之后走上写作道路。代表作有写插队生活的**《我的遥远的清平湾》**，长篇随笔**《病隙碎笔》**，以及散文**《我与地坛》**（1991），后者在北京地坛的园子里追问生与死，写母亲的爱，是**当代散文名篇**。他的写作以残疾与生死为思考主线，影响了新时期一代读者。","pts":["北京人，21岁双腿瘫痪","《我与地坛》《我的遥远的清平湾》","《病隙碎笔》，思考生死"],"mem":"一个地点一个人：**“地坛”＝史铁生**。看到“地坛、轮椅、母亲”，就想到《我与地坛》。三部作品按“清平湾（插队）→地坛（散文）→病隙（随笔）”记。","mix":"《我与地坛》是散文，不是小说；汪曾祺也是散淡风格但写的是高邮风物，不要混。","mcq":[{"q":"《我与地坛》的作者是","o":["汪曾祺","史铁生","路遥","余华"],"a":1,"w":"《我与地坛》是史铁生的散文名篇。"}],"rel":[{"t":"汪曾祺","n":"同属新时期散淡写作"},{"t":"余华","n":"同为当代重要作家"},{"t":"寻根文学","n":"同期文学思潮"}],"more":"主要作品：《我的遥远的清平湾》《命若琴弦》《务虚笔记》《我与地坛》《病隙碎笔》。","exam":[]},{"id":"z70-011","t":"汪曾祺","cid":"08h","p":2,"kind":"人物","alias":["汪老"],"one":"沈从文的学生，当代作家，以《受戒》《大淖记事》知名。","ans":"汪曾祺（1920–1997），**江苏高邮人，当代作家**，**沈从文的学生**。他早年就读西南联合大学，受沈从文影响，新时期以短篇小说**《受戒》**（1980）、**《大淖记事》**（1981）重返文坛，写家乡的风土人情与普通人的情感，文字平淡简洁，**散文化、诗化**。他也写散文，如《端午的鸭蛋》。他被视为**京派文学的当代传人**，对寻根文学有影响。","pts":["江苏高邮人，沈从文的学生","《受戒》《大淖记事》","散文化、诗化小说，京派传人"],"mem":"**“汪曾祺学沈从文”＝“京派—高邮”**：沈从文写湘西《边城》，汪曾祺写高邮《受戒》，都是“用乡土写人性”。两人师徒、地点各异。","mix":"《受戒》写小和尚明海与小英子，不是史铁生；沈从文的代表作是《边城》，不是《受戒》。","mcq":[{"q":"短篇小说《受戒》的作者是","o":["沈从文","汪曾祺","史铁生","孙犁"],"a":1,"w":"汪曾祺《受戒》1980年发表，沈从文是他的老师。"}],"rel":[{"t":"沈从文","n":"老师"},{"t":"京派与海派","n":"所属京派传统"},{"t":"史铁生","n":"同期作家"},{"t":"寻根文学","n":"对寻根文学有影响"}],"more":"主要作品：《受戒》《大淖记事》《异秉》《陈小手》；散文《端午的鸭蛋》。","exam":[]},{"id":"z70-012","t":"阿来","cid":"08i","p":3,"kind":"人物","exam":[],"alias":[],"one":"1959–，藏族","ans":"1959–，藏族","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 *《尘埃落定》（第五届茅盾文学奖） / 长篇《格萨尔王》\n混 藏族史诗《格萨尔王传》是 2024 年名解","todo":1},{"id":"z70-014","t":"海子","cid":"08h","p":2,"kind":"人物","alias":["查海生"],"one":"诗人，原名查海生，《面朝大海，春暖花开》，1989年去世。","ans":"海子（1964–1989），原名**查海生**，**安徽怀宁人，当代诗人**，北京大学毕业，1989年3月在山海关去世。他是1980年代**抒情诗**的代表，诗歌以麦地、土地、太阳为核心意象，代表作有**《面朝大海，春暖花开》**《亚洲铜》《麦地》《祖国（或以梦为马）》。他的诗**纯净、悲剧性强**，去世后影响迅速扩大，成为当代诗歌的重要符号。","pts":["原名查海生，安徽怀宁人","《面朝大海，春暖花开》《亚洲铜》","1989年去世，抒情诗代表"],"mem":"**“海子—面朝大海”**：名字里有海，诗里也有海。名句“从明天起，做一个幸福的人”也出自这一首。年份“1989”记成“89年春天”。","mix":"顾城是朦胧诗代表，1993年去世，名句“黑夜给了我黑色的眼睛”；海子是1989年去世，不属朦胧诗派，别与顾城混淆。","mcq":[{"q":"《面朝大海，春暖花开》的作者是","o":["北岛","顾城","舒婷","海子"],"a":3,"w":"海子，原名查海生。"}],"rel":[{"t":"顾城","n":"同样早逝的诗人，常并提"},{"t":"北岛","n":"朦胧诗对照"},{"t":"朦胧诗派","n":"海子晚于朦胧诗"}],"more":"名句：从明天起，做一个幸福的人。喂马，劈柴，周游世界。｜《面朝大海，春暖花开》\n面朝大海，春暖花开。","exam":[]},{"id":"z70-015","t":"北岛","cid":"08h","p":3,"kind":"人物","exam":[],"alias":[],"one":"1949–，朦胧诗派","ans":"1949–，朦胧诗派","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《回答》\n句 卑鄙是卑鄙者的通行证，高尚是高尚者的墓志铭。｜《回答》","todo":1},{"id":"z70-016","t":"舒婷","cid":"08h","p":3,"kind":"人物","exam":[],"alias":[],"one":"1952–，朦胧诗派","ans":"1952–，朦胧诗派","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《致橡树》 / 《祖国啊，我亲爱的祖国》","todo":1},{"id":"z70-017","t":"顾城","cid":"08h","p":3,"kind":"人物","exam":[],"alias":[],"one":"1956–1993，朦胧诗派","ans":"1956–1993，朦胧诗派","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《一代人》\n句 黑夜给了我黑色的眼睛，我却用它寻找光明。｜《一代人》","todo":1},{"id":"z70-019","t":"曹文轩","cid":"08h","p":3,"kind":"人物","exam":[],"alias":[],"one":"1954–","ans":"1954–","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"作 《草房子》 / 《青铜葵花》\n群 2016 年获国际安徒生奖，中国首位","todo":1},{"id":"z70-020","t":"高行健","cid":"08h","p":2,"kind":"人物","alias":["Gao Xingjian"],"one":"法籍华人作家，2000年获诺贝尔文学奖，代表作《灵山》。","ans":"高行健（1940– ），**江西赣州人，法籍华人作家、剧作家**。他早年在北京人民艺术剧院工作，写有先锋话剧**《绝对信号》**，后移居法国。长篇小说**《灵山》**（1990）以流浪与寻找为主线，结构独特。**2000年获诺贝尔文学奖**，是**首位获该奖的华语作家**，评奖理由称他的作品具有“普遍价值”，为中文小说和戏剧开辟了新路。","pts":["江西赣州人，法籍华人","《灵山》《绝对信号》","2000年诺贝尔文学奖，首位华语作家"],"mem":"**“2000—高行健—灵山”**。记住两个“第一”：他是第一位获诺贝尔文学奖的华语作家；莫言（2012）是第一位中国籍获奖者。中间差12年。","mix":"莫言2012年获奖，是中国籍；高行健2000年获奖时为法国籍，两人别混。","mcq":[{"q":"2000年获得诺贝尔文学奖的华语作家是","o":["莫言","北岛","高行健","余华"],"a":2,"w":"高行健2000年获奖，莫言是2012年。"}],"rel":[{"t":"莫言","n":"2012年获奖，常对比"},{"t":"诺贝尔文学奖","n":"所获奖项"},{"t":"先锋文学","n":"同期先锋探索"}],"more":"主要作品：《灵山》《一个人的圣经》；剧作《绝对信号》《车站》《野人》。","exam":[]},{"id":"c-045","t":"激流三部曲（巴金）","cid":"08e","p":2,"kind":"合称","alias":["《家》《春》《秋》","家春秋"],"one":"巴金《家》《春》《秋》，写成都高家的衰败。","ans":"激流三部曲是**巴金的长篇小说《家》《春》《秋》**，写于1930年代至1940年，通过**成都高公馆**四世同堂的衰败，揭露封建大家庭的罪恶。《家》最先写成，1931年起连载（原名《激流》），**1933年出版**，觉慧代表反抗的青年，觉新是妥协的长孙，鸣凤投湖而死。作品以五四后新思潮冲击旧家庭为背景，是现代长篇小说名篇，对一代青年影响很大。","pts":["巴金：《家》《春》《秋》","写成都高家的没落","觉慧反抗，觉新妥协，鸣凤之死"],"mem":"书名“家春秋”顺口连读。三兄弟按“新、民、慧”：觉新（新旧之间，作揖主义）、觉民（民，反抗婚姻）、觉慧（慧，彻底出走）。抓住《家》的要点：觉慧、鸣凤、高老太爷。","mix":"激流三部曲是《家》《春》《秋》，爱情三部曲是《雾》《雨》《电》；《寒夜》《随想录》是独立作品；巴金还有抗战主题的《火》三部曲。","mcq":[{"q":"巴金激流三部曲不包括","o":["《家》","《春》","《秋》","《雾》"],"a":3,"w":"《雾》属爱情三部曲。"}],"members":[["《家》","觉慧、觉新、鸣凤，1933年出版"],["《春》","淑英冲出旧家庭"],["《秋》","高家衰败解体"]],"rel":[{"t":"巴金","n":"作者"},{"t":"爱情三部曲（巴金）","n":"同作者另一组"},{"t":"《随想录》","n":"晚年代表作"},{"t":"《红楼梦》四大家族","n":"同写大家庭衰败"}],"more":"《家》（1933）、《春》（1938）、《秋》（1940）\n主要人物：觉新、觉民、觉慧、鸣凤、瑞珏、梅","exam":[]},{"id":"c-046","t":"爱情三部曲（巴金）","cid":"08e","p":2,"kind":"合称","alias":["《雾》《雨》《电》","雾雨电"],"one":"巴金《雾》《雨》《电》，写青年的爱情与革命。","ans":"爱情三部曲是**巴金的《雾》《雨》《电》**，1930年代初陆续完成，**写青年知识分子的爱情与革命**。《雾》的主人公周如水在爱情中软弱徘徊，《雨》《电》则写吴仁民、李佩珠等革命青年在苦闷中的奋斗。作品受**无政府主义**思想影响，与激流三部曲《家》《春》《秋》并称巴金早期代表作。","pts":["巴金：《雾》《雨》《电》","青年知识分子的爱情与革命","周如水、吴仁民、李佩珠"],"mem":"天气口诀“雾、雨、电”，由朦胧到压抑再到闪亮，正好对应青年从迷茫、苦闷到行动。与激流三部曲对比：激流三部曲写“家”，爱情三部曲写“人”。","mix":"爱情三部曲（《雾》《雨》《电》）与激流三部曲（《家》《春》《秋》）常被混淆；茅盾的《蚀》三部曲是《幻灭》《动摇》《追求》。","mcq":[{"q":"下列作品中，属于巴金爱情三部曲的是","o":["《雨》","《春》","《追求》","《春蚕》"],"a":0,"w":"《春》属激流三部曲，《追求》属茅盾《蚀》，《春蚕》属茅盾农村三部曲。"}],"members":[["《雾》","周如水，爱情中的软弱"],["《雨》","吴仁民，苦闷中的革命者"],["《电》","吴仁民、李佩珠，走向行动"]],"rel":[{"t":"巴金","n":"作者"},{"t":"激流三部曲（巴金）","n":"同作者另一组"},{"t":"《蚀》三部曲（茅盾）","n":"同为现代三部曲"},{"t":"《随想录》","n":"晚年代表作"}],"more":"《雾》（1931）、《雨》（1933），《电》完成于1930年代中期","exam":[]},{"id":"c-047","t":"《蚀》三部曲（茅盾）","cid":"08e","p":2,"kind":"合称","alias":["《幻灭》《动摇》《追求》","蚀"],"one":"茅盾《幻灭》《动摇》《追求》，写大革命前后知识分子。","ans":"《蚀》三部曲是**茅盾的第一部长篇作品**，包括**《幻灭》《动摇》《追求》**，1927至1928年写成，1930年合集出版。作品以**大革命前后**的小资产阶级知识分子为描写对象，写他们在革命浪潮中幻想破灭、动摇不定、追求落空的过程。**《幻灭》**发表时茅盾第一次署名“茅盾”，女主人公章静。","pts":["茅盾：《幻灭》《动摇》《追求》","大革命前后小资产阶级知识分子","茅盾笔名始用于《幻灭》"],"mem":"顺序“幻、动、追”，三个动词连成一条线：先幻灭，再动摇，最后追求落空；“蚀”取日蚀月蚀的“蚀”，象征光明被暂时遮蔽。区分：《蚀》写知识分子，《子夜》写民族资本家吴荪甫。","mix":"《蚀》三部曲与农村三部曲（《春蚕》《秋收》《残冬》）都是茅盾所作，题材不同；巴金的三部曲是激流三部曲和爱情三部曲。","mcq":[{"q":"茅盾《蚀》三部曲包括","o":["《春蚕》《秋收》《残冬》","《家》《春》《秋》","《幻灭》《动摇》《追求》","《雾》《雨》《电》"],"a":2,"w":"《蚀》三部曲为《幻灭》《动摇》《追求》。"}],"members":[["《幻灭》","章静，1927年，首署“茅盾”"],["《动摇》","方罗兰，1928年"],["《追求》","章秋柳，1928年"]],"rel":[{"t":"茅盾","n":"作者"},{"t":"农村三部曲（茅盾）","n":"同作者另一组"},{"t":"《子夜》","n":"茅盾代表长篇"},{"t":"《小说月报》","n":"首载于此刊"}],"more":"《幻灭》（1927）、《动摇》（1928）、《追求》（1928），1930年合为《蚀》出版","exam":[]},{"id":"c-048","t":"农村三部曲（茅盾）","cid":"08e","p":2,"kind":"合称","alias":["《春蚕》《秋收》《残冬》","春蚕","老通宝"],"one":"茅盾《春蚕》《秋收》《残冬》，写江浙农村破产。","ans":"农村三部曲是**茅盾的《春蚕》《秋收》《残冬》**，1932至1933年发表，以江浙农村为背景，写**老通宝一家**养蚕丰收反而破产，秋收谷贱伤农，最后农民走向反抗的过程。《春蚕》的“丰收成灾”最为有名，揭示了帝国主义经济侵略与农村破产。1933年《春蚕》被夏衍改编成电影，是早期左翼电影代表，三部曲也是**“社会剖析派”**的代表。","pts":["茅盾：《春蚕》《秋收》《残冬》","老通宝一家，丰收成灾","社会剖析，江浙农村破产"],"mem":"四季口诀：春蚕、秋收、残冬，缺“夏”，少了夏天；记“丰收成灾”四字：养蚕越多，亏得越多。人物抓老通宝和儿子多多头：老通宝守旧，多多头走向反抗。","mix":"农村三部曲是茅盾，爱情三部曲、激流三部曲是巴金；《林家铺子》也是茅盾，写小镇商人，不属农村三部曲。","mcq":[{"q":"茅盾农村三部曲中，写老通宝养蚕“丰收成灾”的是","o":["《秋收》","《残冬》","《林家铺子》","《春蚕》"],"a":3,"w":"《春蚕》写老通宝养蚕，蚕茧丰收反而更穷。"}],"members":[["《春蚕》","老通宝养蚕丰收成灾，1932年"],["《秋收》","稻熟谷贱，1933年"],["《残冬》","多多头走向反抗，1933年"]],"rel":[{"t":"茅盾","n":"作者"},{"t":"《蚀》三部曲（茅盾）","n":"同作者另一组"},{"t":"《子夜》","n":"同为社会剖析代表"},{"t":"乡土小说","n":"同写农村的另一路"}],"more":"《春蚕》（1932）、《秋收》（1933）、《残冬》（1933）\n另有《林家铺子》（1932）","exam":[]},{"id":"c-049","t":"鲁郭茅巴老曹","cid":"08e","p":1,"kind":"合称","alias":["鲁郭茅巴老曹"],"one":"中国现代文学六大家：鲁迅、郭沫若、茅盾、巴金、老舍、曹禺。","ans":"鲁郭茅巴老曹是**中国现代文学六位代表作家的合称**，指**鲁迅、郭沫若、茅盾、巴金、老舍、曹禺**，取六人姓名首字排列。鲁迅以小说《呐喊》《彷徨》和杂文立现代文学之基；郭沫若《女神》是新诗奠基之作；茅盾《子夜》开社会剖析小说；巴金激流三部曲写封建大家庭；老舍《骆驼祥子》《茶馆》写北京市民；曹禺《雷雨》标志现代话剧成熟。这一说法概括了**现代小说、诗歌、话剧**的主要成就。","pts":["鲁迅、郭沫若、茅盾、巴金、老舍、曹禺","各自代表作：呐喊、女神、子夜、家、茶馆、雷雨","现代小说、诗歌、话剧的代表"],"members":[["鲁迅","《呐喊》《彷徨》，杂文，小说奠基"],["郭沫若","《女神》，历史剧《屈原》"],["茅盾","《子夜》，社会剖析小说"],["巴金","激流三部曲《家》《春》《秋》"],["老舍","《骆驼祥子》《茶馆》，京味"],["曹禺","《雷雨》，现代话剧成熟"]],"mem":"通行口诀就是“鲁郭茅巴老曹”。按体裁分：写小说的鲁、茅、巴、老，写诗与历史剧的郭，写话剧的曹（老舍也写话剧）。原名可串记：周树人、郭开贞、沈德鸿、李尧棠、舒庆春、万家宝。","mix":"沈从文、张爱玲、钱锺书、萧红不在其列；有的说法还把郁达夫、冰心并列，但通行六大家就是这六位。","mcq":[{"q":"下列作家中，不属于“鲁郭茅巴老曹”的是","o":["老舍","茅盾","巴金","沈从文"],"a":3,"w":"六人为鲁迅、郭沫若、茅盾、巴金、老舍、曹禺。"},{"q":"“鲁郭茅巴老曹”中，原名舒庆春的是","o":["巴金","茅盾","老舍","曹禺"],"a":2,"w":"巴金原名李尧棠，茅盾沈德鸿，曹禺万家宝。"}],"rel":[{"t":"鲁迅","n":"六大家之首"},{"t":"茅盾","n":"六大家之一"},{"t":"曹禺","n":"六大家之一"},{"t":"沈从文","n":"常作干扰项"},{"t":"唐宋八大家","n":"姓名首字合称对照"}],"more":"原名：鲁迅周树人、郭沫若郭开贞、茅盾沈德鸿、巴金李尧棠、老舍舒庆春、曹禺万家宝","exam":[]},{"id":"a08-001","t":"文学革命","cid":"08a","p":1,"kind":"事件","alias":["白话文运动"],"one":"1917年胡适、陈独秀发动，以白话文学取代文言文学的运动。","ans":"文学革命是**新文化运动的文学部分**，1917年由《新青年》发动。1917年1月胡适发表**《文学改良刍议》**，提出**“八事”**，主张以白话为文学正宗；2月陈独秀发表**《文学革命论》**，提出推倒贵族文学、古典文学、山林文学，建设国民文学、写实文学、社会文学的**“三大主义”**，钱玄同、刘半农等声援。1918年鲁迅《狂人日记》是第一篇现代白话小说，1920年教育部通令小学国文改用语体文，**白话取代文言**成为正式书面语。","pts":["胡适“八事”，陈独秀“三大主义”","《新青年》为阵地，钱玄同、刘半农响应","白话取代文言，《狂人日记》是实绩"],"mem":"名称对应力度：胡适谦称“改良刍议”，语气温和；陈独秀直呼“革命论”，语气激烈。顺序是1月胡适、2月陈独秀，先理论后声援，随后1918年鲁迅《狂人日记》给出创作实绩。","mix":"胡适是“改良”，陈独秀是“革命”；晚清梁启超的“诗界革命”“小说界革命”仍用文言，早于1917年，不是白话文学革命。","mcq":[{"q":"陈独秀《文学革命论》提出的主张是","o":["八事","三大主义","三美","为人生而艺术"],"a":1,"w":"“八事”属于胡适《文学改良刍议》。"},{"q":"发动文学革命的《文学改良刍议》《文学革命论》发表于","o":["1917年","1915年","1919年","1921年"],"a":0,"w":"1917年1月、2月先后发表于《新青年》。"}],"rel":[{"t":"胡适","n":"八事"},{"t":"陈独秀","n":"三大主义"},{"t":"《新青年》","n":"发表阵地"},{"t":"《狂人日记》","n":"第一篇白话小说"},{"t":"“小说界革命”","n":"晚清改良，对照"}],"more":"1917年1月 胡适《文学改良刍议》（八事）\n1917年2月 陈独秀《文学革命论》（三大主义）\n1918年 鲁迅《狂人日记》\n1920年 教育部通令小学国文改用语体文","exam":[]},{"id":"a08-002","t":"诗界革命","cid":"08a","p":2,"kind":"流派","alias":["诗界革命"],"one":"1899年梁启超提出，黄遵宪为旗帜，要求诗歌有新意境、新语句。","ans":"诗界革命是**1899年梁启超**在《夏威夷游记》中提出的**晚清诗歌改良口号**，与“文界革命”“小说界革命”并称“三界革命”。梁启超主张诗要有“新意境”“新语句”，而又以古人风格入之，**黄遵宪**是其旗帜，提出“**我手写我口**”。同道还有谭嗣同、夏曾佑、蒋智由等。这场革命仍用旧体诗形式，未能突破格律，真正的诗体解放要等五四白话新诗。","pts":["1899年梁启超提出","黄遵宪为旗帜，“我手写我口”","仍用旧形式，新诗革命在五四"],"mem":"逻辑线：晚清先改“内容”（新意境、新语句），五四才改“形式”（白话、自由体），所以诗界革命是旧瓶装新酒，胡适《尝试集》才是换瓶。一人一词：梁启超=提出，黄遵宪=旗帜。","mix":"“三界革命”指诗界、文界、小说界；诗界革命主张的“以古人之风格入之”，正是它与五四白话新诗的分界。","mcq":[{"q":"被称为“诗界革命”旗帜的诗人是","o":["谭嗣同","康有为","梁启超","黄遵宪"],"a":3,"w":"梁启超提出口号，黄遵宪被推为旗帜。"}],"rel":[{"t":"黄遵宪","n":"旗帜"},{"t":"梁启超","n":"提出者"},{"t":"“小说界革命”","n":"三界革命之一"},{"t":"文学革命","n":"后续的五四革命"}],"more":"欲为诗界革命，必先有新意境，其次须有新语句，而又须以古人之风格入之，然后成其为诗。｜梁启超《夏威夷游记》","exam":[]},{"id":"a08-004","t":"《人间词话》","cid":"08a","p":2,"kind":"作品","alias":["人间词话"],"one":"王国维的词学批评著作，提出“境界”说。","ans":"《人间词话》是**王国维**的**词学批评著作**，成书于清末，以**“境界”说**为核心，提出“词以境界为最上”，并区分**“有我之境”与“无我之境”**。书中借晏殊“昨夜西风凋碧树”、柳永“衣带渐宽终不悔”、辛弃疾“众里寻他千百度”三句，比喻成大事业、大学问的**三种境界**。它把中国传统诗论与叔本华等西方美学结合，是近代文学批评的经典。","pts":["王国维著，“境界”说","有我之境与无我之境","三种境界：晏殊、柳永、辛弃疾"],"mem":"三种境界按“晏、柳、辛”顺序，对应“望尽天涯路、为伊消得人憔悴、灯火阑珊处”，从“立志”到“苦求”再到“顿悟”。口诀“晏柳辛，望憔悴阑珊”。无我之境记陶渊明“采菊东篱下，悠然见南山”。","mix":"三种境界的词人是晏殊、柳永、辛弃疾，不要换成欧阳修、李清照；王国维另一部名著是《宋元戏曲史》，写戏曲，不写词。","mcq":[{"q":"《人间词话》中用“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”比喻治学的第三种境界，该词句的作者是","o":["晏殊","柳永","李清照","辛弃疾"],"a":3,"w":"第三境界引辛弃疾《青玉案·元夕》。"}],"rel":[{"t":"王国维","n":"作者"},{"t":"王国维《人间词话》","n":"同书条目"},{"t":"婉约派与豪放派","n":"所论词的流派"},{"t":"吴文英与南宋格律词派","n":"书中有评论"}],"more":"词以境界为最上。有境界则自成高格，自有名句。\n有我之境：泪眼问花花不语，乱红飞过秋千去。\n无我之境：采菊东篱下，悠然见南山。\n第一境：昨夜西风凋碧树，独上高楼，望尽天涯路。（晏殊）\n第二境：衣带渐宽终不悔，为伊消得人憔悴。（柳永）\n第三境：众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。（辛弃疾）","exam":[]},{"id":"a08-005","t":"春柳社与中国话剧开端","cid":"08a","p":2,"kind":"流派","alias":["春柳社","中国话剧开端"],"one":"1906年留日学生在东京成立，1907年演《茶花女》片段，是话剧开端。","ans":"春柳社是**1906年底由留日学生李叔同、曾孝谷等在东京创立**的新剧团体，欧阳予倩后来也加入。1907年春，他们在东京演出**《茶花女》片段**，李叔同男扮女装饰演茶花女；同年夏又演出**五幕剧《黑奴吁天录》**，改编自斯托夫人的《汤姆叔叔的小屋》。这两次演出被视为**中国话剧的开端**，采用分幕、对白的西方戏剧形式，区别于传统戏曲。","pts":["1906年留日学生李叔同等在东京成立","1907年演《茶花女》片段和《黑奴吁天录》","中国话剧（文明戏）的开端"],"mem":"画面：东京的舞台上，李叔同穿着长裙演茶花女。两部戏对应两部外国名著：《茶花女》（小仲马）和《黑奴吁天录》（《汤姆叔叔的小屋》）。年份挂钩：春柳社成立（1906）、首演（1907），同年春阳社在上海演出，一东一西。","mix":"春柳社是留日学生在东京的团体，不在国内；曹禺《雷雨》（1934）标志话剧成熟，不是开端；李叔同后来出家，法号弘一。","mcq":[{"q":"通常被视为中国话剧开端的事件是","o":["1918年《新青年》出版易卜生专号","1934年曹禺发表《雷雨》","1907年春柳社在东京演出《茶花女》片段","1935年《义勇军进行曲》问世"],"a":2,"w":"春柳社1907年在东京的演出是中国话剧的开端；《雷雨》是成熟标志。"}],"rel":[{"t":"学堂乐歌与李叔同《送别》","n":"同一人物李叔同"},{"t":"《茶花女》","n":"首演剧目原著"},{"t":"《汤姆叔叔的小屋》","n":"《黑奴吁天录》原著"},{"t":"曹禺","n":"话剧成熟的代表"}],"more":"1906年冬　春柳社成立于东京\n1907年　演出《茶花女》片段、《黑奴吁天录》","exam":[]},{"id":"a08-006","t":"学衡派","cid":"08a","p":3,"kind":"流派","exam":[],"alias":[],"one":"1922年《学衡》在南京东南大学创刊，梅光迪、吴宓、胡先骕，“昌明国粹，融化","ans":"1922年《学衡》在南京东南大学创刊，梅光迪、吴宓、胡先骕，“昌明国粹，融化新知”","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-007","t":"南社","cid":"08a","p":3,"kind":"流派","exam":[],"alias":[],"one":"1909年在苏州成立，柳亚子、陈去病、高旭发起","ans":"1909年在苏州成立，柳亚子、陈去病、高旭发起","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-008","t":"章太炎逝世90周年","cid":"08a","p":3,"kind":"时事","exam":[],"alias":[],"one":"章太炎（章炳麟）1936年逝世；国学大师，鲁迅曾从其受业","ans":"章太炎（章炳麟）1936年逝世；国学大师，鲁迅曾从其受业","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-009","t":"《阿Q正传》","cid":"08b","p":1,"kind":"作品","alias":["阿Q","精神胜利法"],"one":"鲁迅中篇小说，塑造阿Q，批判“精神胜利法”，收入《呐喊》。","ans":"《阿Q正传》是**鲁迅1921年12月起连载于北京《晨报副刊》的中篇小说**，署名**巴人**，后收入小说集**《呐喊》**。小说写**辛亥革命前后**未庄的雇农阿Q，他地位卑微，却靠**“精神胜利法”**自我安慰，被打后自称“儿子打老子”，最后糊里糊涂被当作革命党枪决。作品批判了**国民劣根性**，也写出辛亥革命没有真正触动农民的局限。阿Q成为文学史上的典型形象，作品被译成多种外文。","pts":["1921年连载于《晨报副刊》，署名巴人","阿Q，精神胜利法","辛亥革命背景，国民劣根性"],"mem":"画面：阿Q挨了打，转头说“儿子打老子”，立刻转败为胜，这就是精神胜利法。归属：中篇，收入《呐喊》，不入《彷徨》。","mix":"《阿Q正传》是中篇，《狂人日记》《孔乙己》是短篇；《祝福》《伤逝》才属《彷徨》。","mcq":[{"q":"“精神胜利法”概括的是哪部作品中人物的性格","o":["《祝福》","《阿Q正传》","《药》","《孔乙己》"],"a":1,"w":"阿Q的典型特征。"},{"q":"《阿Q正传》收入鲁迅的","o":["《呐喊》","《彷徨》","《故事新编》","《朝花夕拾》"],"a":0,"w":"《阿Q正传》是《呐喊》压轴名篇。"}],"rel":[{"t":"鲁迅","n":"作者"},{"t":"《呐喊》","n":"收录小说集"},{"t":"鲁迅笔下人物","n":"典型人物"},{"t":"乡土小说","n":"鲁迅为乡土小说先声"}],"more":"1921年12月起连载于《晨报副刊》“开心话”栏，署名巴人\n典型形象：阿Q；核心：精神胜利法","exam":[]},{"id":"a08-010","t":"《呐喊》","cid":"08b","p":1,"kind":"作品","one":"鲁迅第一部小说集，1923年出版，收《狂人日记》《孔乙己》《药》等。","ans":"《呐喊》是**鲁迅的第一部短篇小说集**，**1923年8月**由北京新潮社出版，收1918至1922年所作小说，共14篇。**《狂人日记》**《孔乙己》《药》《故乡》**《阿Q正传》**等名篇都在其中。《自序》讲述作者在日本因“幻灯片事件”弃医从文，并以**“铁屋子”**比喻沉睡的旧中国，说明自己为唤醒麻木者而“呐喊助威”。集中作品批判封建礼教和国民性，是中国现代小说的奠基之作，与《彷徨》《故事新编》合称鲁迅三部小说集。","pts":["1923年，第一部小说集","《狂人日记》《孔乙己》《药》《故乡》《阿Q正传》","《自序》：幻灯片事件、铁屋子"],"mem":"自编口诀：“狂孔药故阿Q”属《呐喊》；“祝福伤逝酒楼上”属《彷徨》。出版先后：呐喊1923，彷徨1926。","mix":"初版收15篇，含《不周山》，后抽出改题《补天》收入《故事新编》，现通行14篇；《祝福》《伤逝》《在酒楼上》属《彷徨》。","mcq":[{"q":"下列作品不属于《呐喊》的是","o":["《药》","《故乡》","《孔乙己》","《祝福》"],"a":3,"w":"《祝福》收入《彷徨》。"},{"q":"鲁迅的第一部小说集是","o":["《彷徨》","《故事新编》","《呐喊》","《野草》"],"a":2,"w":"1923年出版。"}],"rel":[{"t":"鲁迅","n":"作者"},{"t":"《彷徨》","n":"第二部小说集"},{"t":"《狂人日记》","n":"开卷之作"},{"t":"《阿Q正传》","n":"压轴名篇"},{"t":"《故事新编》","n":"第三部小说集"}],"more":"1923年8月 北京新潮社出版\n名篇：《狂人日记》《孔乙己》《药》《故乡》《阿Q正传》《社戏》\n《自序》：幻灯片事件、“铁屋子”","exam":[]},{"id":"a08-011","t":"《彷徨》","cid":"08b","p":2,"kind":"作品","alias":["彷徨"],"one":"鲁迅第二部短篇小说集，1926年出版，收《祝福》《伤逝》等。","ans":"《彷徨》是**鲁迅的第二部短篇小说集**，1926年出版，收录1924至1925年所作小说11篇。代表作有**《祝福》**（祥林嫂的悲剧）、**《伤逝》**（涓生与子君的爱情悲剧）、**《在酒楼上》**《孤独者》。相比《呐喊》，这部集子笔调更沉郁，表现五四退潮后知识分子的苦闷与探索，卷首引屈原《离骚》“路漫漫其修远兮，吾将上下而求索”，与《呐喊》共同奠定现代短篇小说的成就。","pts":["鲁迅第二部短篇小说集，1926年","《祝福》《伤逝》《在酒楼上》","五四退潮后知识分子的苦闷"],"mem":"一句话串三篇：祥林嫂在“祝福”声中死去，涓生在“酒楼上”回想“伤逝”。与《呐喊》对比：《呐喊》喊出《狂人日记》《孔乙己》《药》《阿Q正传》《故乡》，《彷徨》是喊完之后的沉思。","mix":"《孔乙己》《药》《故乡》《阿Q正传》属《呐喊》；《补天》《铸剑》属《故事新编》；《祝福》《伤逝》属《彷徨》。","mcq":[{"q":"下列作品中，收入鲁迅小说集《彷徨》的是","o":["《孔乙己》","《祝福》","《药》","《故乡》"],"a":1,"w":"《祝福》收入《彷徨》，其余三篇都在《呐喊》中。"}],"rel":[{"t":"鲁迅","n":"作者"},{"t":"《呐喊》","n":"第一部小说集"},{"t":"《故事新编》","n":"第三部小说集"},{"t":"《野草》","n":"同期的散文诗集"}],"more":"《祝福》《在酒楼上》《幸福的家庭》《肥皂》《长明灯》《示众》《高老夫子》《孤独者》《伤逝》《弟兄》《离婚》","exam":[]},{"id":"a08-012","t":"《野草》","cid":"08b","p":2,"kind":"作品","alias":["野草"],"one":"鲁迅唯一的散文诗集，1927年出版，名篇《秋夜》。","ans":"《野草》是**鲁迅唯一的散文诗集**，1927年出版，收录1924至1926年所作散文诗，另有《题辞》。作品运用象征手法，抒写作者内心的孤独、矛盾与韧性，名篇有**《秋夜》《雪》《影的告别》《过客》**等。《秋夜》开头“一株是枣树，还有一株也是枣树”广为人知。它与《呐喊》的现实批判相对，展现鲁迅的内心世界，是现代散文诗的奠基之作。","pts":["鲁迅唯一的散文诗集，1927年","象征手法，抒写内心孤独与矛盾","《秋夜》《雪》《过客》"],"mem":"画面：后园墙外两株枣树，一株是枣树，还有一株也是枣树，这是《秋夜》的开头，一句话记住《野草》。体裁表：《呐喊》《彷徨》《故事新编》是小说，《朝花夕拾》是回忆散文，《野草》是散文诗。","mix":"《朝花夕拾》是回忆性散文集，不是散文诗；《野草》和《朝花夕拾》都写于同一时期，但体裁不同。","mcq":[{"q":"鲁迅唯一的散文诗集是","o":["《朝花夕拾》","《热风》","《坟》","《野草》"],"a":3,"w":"《野草》收《秋夜》《雪》等；《朝花夕拾》是回忆性散文集。"}],"rel":[{"t":"鲁迅","n":"作者"},{"t":"《朝花夕拾》创作100周年","n":"同期散文集"},{"t":"《彷徨》","n":"同时期小说集"},{"t":"鲁迅逝世90周年","n":"2026年周年"}],"more":"名篇：《秋夜》《雪》《影的告别》《过客》《好的故事》《墓碣文》\n在我的后园，可以看见墙外有两株树，一株是枣树，还有一株也是枣树。｜《秋夜》","exam":[]},{"id":"a08-013","t":"《故事新编》","cid":"08b","p":3,"kind":"作品","exam":[],"alias":[],"one":"历史小说集，1936年出版；《补天》《奔月》《铸剑》《理水》","ans":"历史小说集，1936年出版；《补天》《奔月》《铸剑》《理水》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-015","t":"鲁迅笔下人物","cid":"08b","p":1,"kind":"合称","one":"阿Q、孔乙己、祥林嫂、闰土、华老栓、涓生子君等鲁迅小说典型形象。","ans":"鲁迅笔下人物指**鲁迅小说中塑造的一组典型形象**，多为辛亥革命前后的底层民众与知识分子。**阿Q**出自《阿Q正传》，代表“精神胜利法”；**孔乙己**出自同名小说，是科举制度下的落魄读书人；**祥林嫂**出自《祝福》，是被礼教与神权逼死的农妇；**闰土**出自《故乡》，从聪明少年变成麻木的中年人；**华老栓**出自《药》，用人血馒头给儿子治病；**涓生与子君**出自《伤逝》，写个性解放的悲剧。这些形象集中体现鲁迅对**国民劣根性**的批判。","pts":["阿Q精神胜利法；孔乙己落魄书生","祥林嫂《祝福》；闰土《故乡》","华老栓《药》；涓生子君《伤逝》"],"members":[["阿Q","《阿Q正传》，精神胜利法"],["孔乙己","《孔乙己》，咸亨酒店里穿长衫的落魄读书人"],["祥林嫂","《祝福》，鲁镇农妇，丧夫丧子"],["闰土","《故乡》，少年闰土与中年闰土"],["华老栓","《药》，买人血馒头为儿子治病"],["涓生与子君","《伤逝》，自由恋爱的悲剧"],["狂人","《狂人日记》"]],"mem":"自编口诀，作品在前人物在后：祝福祥林，故乡闰土，药是老栓，伤逝涓生。《呐喊》里的人记“阿孔老闰”（阿Q、孔乙己、老栓、闰土），《彷徨》里的人记“祥涓”。","mix":"祥林嫂、涓生、子君属《彷徨》，阿Q、孔乙己、闰土、华老栓属《呐喊》；《风波》中的七斤也出自《呐喊》。","mcq":[{"q":"祥林嫂出自鲁迅的","o":["《药》","《祝福》","《故乡》","《孔乙己》"],"a":1,"w":"《祝福》收入《彷徨》。"},{"q":"下列人物与作品对应错误的是","o":["孔乙己出自《祝福》","闰土出自《故乡》","华老栓出自《药》","涓生出自《伤逝》"],"a":0,"w":"孔乙己出自同名小说《孔乙己》。"}],"rel":[{"t":"《阿Q正传》","n":"阿Q所在"},{"t":"《呐喊》","n":"多数人物所在"},{"t":"《彷徨》","n":"祥林嫂等所在"},{"t":"《骆驼祥子》","n":"同写底层小人物"}],"more":"《孤独者》魏连殳、《在酒楼上》吕纬甫同属《彷徨》中的知识分子形象。","exam":[]},{"id":"a08-016","t":"《小说月报》","cid":"08c","p":3,"kind":"作品","exam":[],"alias":[],"one":"1910年商务印书馆创办，1921年由沈雁冰革新，成为文学研究会阵地","ans":"1910年商务印书馆创办，1921年由沈雁冰革新，成为文学研究会阵地","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-017","t":"语丝社","cid":"08c","p":3,"kind":"流派","exam":[],"alias":[],"one":"1924年在北京创办《语丝》周刊，鲁迅、周作人、林语堂等；“语丝文体”","ans":"1924年在北京创办《语丝》周刊，鲁迅、周作人、林语堂等；“语丝文体”","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-018","t":"乡土小说","cid":"08c","p":2,"kind":"流派","alias":["乡土文学","侨寓文学"],"one":"1920年代以故乡农村为题材的小说流派，受鲁迅影响。","ans":"乡土小说是**1920年代出现的小说流派**，作者多为离乡到北京等地谋生的青年，以**故乡农村**为题材，写宗法制乡村的闭塞与愚昧，受**鲁迅《故乡》《风波》**影响。鲁迅称这些作者为“侨寓”在外的作家，所写的是乡土文学。代表作家有**蹇先艾**《水葬》、**许钦文**《鼻涕阿二》、**王鲁彦**《柚子》、**台静农**《地之子》，后来沈从文的乡土书写也承其余绪。","pts":["1920年代，以故乡农村为题材","受鲁迅影响，写宗法乡村","蹇先艾、许钦文、王鲁彦、台静农"],"mem":"抓两个书名最稳：蹇先艾《水葬》，台静农《地之子》。四人姓氏连读“蹇许王台”。画面：游子在北京写故乡，所以鲁迅称他们为“侨寓”作家。","mix":"乡土小说是1920年代流派，沈从文《边城》属1930年代京派；茅盾《春蚕》写农村，但属社会剖析一派。","mcq":[{"q":"下列作家中，属于1920年代乡土小说作家的是","o":["曹禺","蹇先艾","徐志摩","戴望舒"],"a":1,"w":"蹇先艾以《水葬》知名；曹禺写话剧，徐志摩、戴望舒是诗人。"}],"rel":[{"t":"鲁迅","n":"开创与影响者"},{"t":"沈从文","n":"后来的乡土书写"},{"t":"《边城》","n":"乡土抒情的高峰"},{"t":"农村三部曲（茅盾）","n":"同写农村的另一路"}],"more":"蹇先艾《水葬》\n许钦文《鼻涕阿二》\n王鲁彦《柚子》《黄金》\n台静农《地之子》《建塔者》","exam":[]},{"id":"a08-019","t":"湖畔诗社","cid":"08c","p":3,"kind":"流派","exam":[],"alias":[],"one":"1922年在杭州成立，汪静之、应修人、潘漠华、冯雪峰","ans":"1922年在杭州成立，汪静之、应修人、潘漠华、冯雪峰","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-020","t":"许地山","cid":"08c","p":3,"kind":"人物","exam":[],"alias":[],"one":"笔名落华生，散文《落花生》，小说《春桃》","ans":"笔名落华生，散文《落花生》，小说《春桃》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-021","t":"郑振铎","cid":"08c","p":3,"kind":"人物","exam":[],"alias":[],"one":"主编《小说月报》，著《插图本中国文学史》《中国俗文学史》；译泰戈尔《飞鸟集》","ans":"主编《小说月报》，著《插图本中国文学史》《中国俗文学史》；译泰戈尔《飞鸟集》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-022","t":"现代派诗","cid":"08d","p":2,"kind":"流派","alias":["现代派","《现代》杂志"],"one":"1930年代新诗流派，因《现代》杂志得名，戴望舒、卞之琳。","ans":"现代派诗是**1930年代的新诗流派**，因**1932年施蛰存主编的《现代》杂志**得名，代表诗人有**戴望舒**、卞之琳、何其芳等。他们承接法国象征派，用自由体和口语化的语言，重**意象与暗示**，摆脱新月派的整齐格律。戴望舒的《雨巷》被叶圣陶称为“替新诗的音节开了一个新的纪元”，卞之琳《断章》“你站在桥上看风景”是名作。","pts":["因1932年《现代》杂志得名","戴望舒、卞之琳、何其芳","重意象暗示，承象征派"],"mem":"逻辑线：新月派讲“形”（格律），现代派讲“意”（意象），九叶派讲“思”（玄思），三者前后相继。人物配作品：戴望舒《雨巷》，卞之琳《断章》，何其芳《预言》。","mix":"现代派因《现代》杂志得名，不是现代主义；新月派是格律诗，现代派是自由体；九叶诗派在1940年代。","mcq":[{"q":"现代派诗的名称来源于","o":["《新月》月刊","《小说月报》","《现代》杂志","《新青年》"],"a":2,"w":"现代派因1932年施蛰存主编的《现代》杂志得名。"}],"rel":[{"t":"戴望舒","n":"代表诗人"},{"t":"卞之琳","n":"代表诗人"},{"t":"新月派与新诗“三美”","n":"格律对照"},{"t":"九叶诗派","n":"后继的现代主义"}],"more":"戴望舒《雨巷》《我用残损的手掌》\n卞之琳《断章》：你站在桥上看风景，看风景人在楼上看你。\n何其芳《预言》《画梦录》","exam":[]},{"id":"a08-023","t":"象征诗派","cid":"08d","p":3,"kind":"流派","exam":[],"alias":[],"one":"李金发诗集《微雨》（1925）把法国象征主义引入新诗","ans":"李金发诗集《微雨》（1925）把法国象征主义引入新诗","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-024","t":"七月诗派","cid":"08d","p":3,"kind":"流派","exam":[],"alias":[],"one":"以胡风主编的《七月》等刊物为中心，阿垅、绿原、牛汉等","ans":"以胡风主编的《七月》等刊物为中心，阿垅、绿原、牛汉等","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-025","t":"九叶诗派","cid":"08d","p":2,"kind":"合称","alias":["九叶派","中国新诗派","《九叶集》"],"one":"1940年代现代主义诗派，因1981年《九叶集》得名，共九人。","ans":"九叶诗派是**1940年代形成的现代主义新诗流派**，因**1981年出版的诗选《九叶集》**得名，也称“中国新诗派”。成员九人：**辛笛、陈敬容、杜运燮、杭约赫（曹辛之）、郑敏、唐祈、唐湜、袁可嘉、穆旦**。他们多与《诗创造》《中国新诗》杂志有关，主张现实、象征、玄思相结合，吸收西方现代主义，重视诗的内在节奏与智性。","pts":["1940年代，因1981年《九叶集》得名","九人：辛、陈、杜、杭、郑、二唐、袁、穆","现实、象征、玄思结合"],"mem":"数字挂钩：九叶=九位诗人=九片叶子。成员首字串联：“辛陈杜杭郑，二唐袁穆旦”。其中女诗人两位：陈敬容、郑敏；最有名的是穆旦。","mix":"成员的排列顺序各书略有不同，以九人齐全为准；九叶诗派是1940年代，现代派是1930年代，七月诗派（胡风、艾青等）是抗战时期的现实主义诗派。","mcq":[{"q":"下列诗人中，不属于九叶诗派的是","o":["穆旦","郑敏","辛笛","戴望舒"],"a":3,"w":"戴望舒属1930年代现代派；其余三人是九叶诗人。"}],"members":[["辛笛","《手掌集》"],["陈敬容","《交响集》"],["杜运燮","《诗四十首》"],["杭约赫（曹辛之）","《火烧的城》"],["郑敏","《诗集1942–1947》"],["唐祈","《诗第一册》"],["唐湜","《飞扬的歌》"],["袁可嘉","诗论《论新诗现代化》"],["穆旦","《探险队》《旗》"]],"rel":[{"t":"穆旦","n":"代表诗人"},{"t":"现代派诗","n":"前一阶段现代主义"},{"t":"七月诗派","n":"同期现实主义诗派"},{"t":"朦胧诗派","n":"后来的现代诗潮"}],"more":"诗选：《九叶集》（1981，江苏人民出版社），副题“四十年代九人诗选”\n刊物：《诗创造》《中国新诗》","exam":[]},{"id":"a08-026","t":"穆旦","cid":"08d","p":2,"kind":"人物","alias":["查良铮"],"one":"本名查良铮，九叶诗派代表，译普希金、拜伦、雪莱。","ans":"穆旦（1918–1977），本名**查良铮**，天津人，**九叶诗派代表诗人**，毕业于西南联大。早期诗作如《赞美》《春》《诗八首》，把**现代主义手法与中国现实经验**结合，语言富有张力。1942年他随中国远征军入缅作战，亲历野人山撤退。后半生主要从事翻译，以本名译出**普希金《叶甫盖尼·奥涅金》、拜伦《唐璜》、雪莱抒情诗**等，译笔精准流畅。","pts":["本名查良铮，九叶诗派代表","《赞美》《春》《诗八首》","以本名译普希金、拜伦、雪莱"],"mem":"一人两个名字两张脸：笔名穆旦写诗，本名查良铮译诗。三位被译诗人首字串联“普拜雪”（普希金、拜伦、雪莱）。图像：1942年缅甸野人山，诗人行军，后来写入诗中。","mix":"穆旦是笔名，查良铮是本名；译诗署本名，写诗署笔名。金庸本名也叫查良镛，同姓不同人，别混淆。","mcq":[{"q":"穆旦以本名查良铮翻译的作品不包括","o":["普希金《叶甫盖尼·奥涅金》","拜伦《唐璜》","雪莱的抒情诗","歌德《浮士德》"],"a":3,"w":"《浮士德》的中译者主要是郭沫若、绿原等；穆旦译的是普希金、拜伦、雪莱等。"}],"rel":[{"t":"九叶诗派","n":"代表诗人"},{"t":"拜伦","n":"所译《唐璜》作者"},{"t":"普希金","n":"所译《奥涅金》作者"},{"t":"《叶甫盖尼·奥涅金》","n":"所译名著"}],"more":"诗作：《赞美》《春》《诗八首》《冬》《智慧之歌》\n译作：普希金《普希金抒情诗集》《叶甫盖尼·奥涅金》，拜伦《唐璜》，《雪莱抒情诗选》","exam":[]},{"id":"a08-027","t":"汉园三诗人","cid":"08d","p":3,"kind":"合称","exam":[],"alias":[],"one":"卞之琳、何其芳、李广田，1936年合出《汉园集》","ans":"卞之琳、何其芳、李广田，1936年合出《汉园集》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-028","t":"《子夜》","cid":"08e","p":1,"kind":"作品","one":"茅盾1933年长篇小说，写民族资本家吴荪甫的失败，社会剖析小说代表。","ans":"《子夜》是**茅盾1933年出版的长篇小说**，是**社会剖析小说的代表作**。小说以**1930年代上海**为背景，写**民族资本家吴荪甫**兴办实业的雄心与失败：他与**买办资本家赵伯韬**在公债市场上较量，又受工人罢工、农村破产和军阀混战牵制，最终破产。作品说明**中国民族资本在帝国主义和买办资本压迫下没有出路**，回应了当时关于中国社会性质的论争，奠定茅盾在现代长篇小说中的地位。","pts":["1933年，茅盾，社会剖析小说","吴荪甫与赵伯韬的斗争","民族资本主义没有出路"],"mem":"画面：午夜上海，吴荪甫的实业在赵伯韬的公债交易里一夜败尽，书名“子夜”就是最黑的时刻。人物配对：吴荪甫（民族资本家）对赵伯韬（买办资本家）。","mix":"《林家铺子》写小商人，《子夜》写大资本家；《子夜》不属《蚀》三部曲，也不属农村三部曲。","mcq":[{"q":"《子夜》的主人公是","o":["赵伯韬","吴荪甫","祥子","周朴园"],"a":1,"w":"赵伯韬是对手，祥子出自《骆驼祥子》，周朴园出自《雷雨》。"},{"q":"《子夜》的作者茅盾所属的社团是","o":["文学研究会","创造社","新月社","京派"],"a":0,"w":"茅盾是文学研究会发起人之一。"}],"rel":[{"t":"茅盾","n":"作者"},{"t":"《蚀》三部曲（茅盾）","n":"同一作者"},{"t":"农村三部曲（茅盾）","n":"同一作者"},{"t":"《人间喜剧》","n":"社会全景式小说对照"}],"more":"1933年出版；背景：1930年代上海；主要人物：吴荪甫、赵伯韬","exam":[]},{"id":"a08-029","t":"《骆驼祥子》","cid":"08e","p":1,"kind":"作品","alias":["祥子"],"one":"老舍长篇小说，人力车夫祥子三起三落的悲剧。","ans":"《骆驼祥子》是**老舍1936年起连载的长篇小说**，以**北平人力车夫祥子**为主人公。祥子靠拉车攒钱买车，**三起三落**：第一辆车被乱兵抢走，第二次攒的钱被侦探敲诈，第三辆车为办虎妞的丧事卖掉。小福子自杀后，祥子彻底堕落。小说**写出旧社会个人奋斗的破灭**，语言通俗生动，富有**京味**，是**老舍的代表作**，也是现代长篇小说的名作。","pts":["1936年，老舍，人力车夫祥子","三起三落，虎妞、小福子","个人奋斗破灭；京味"],"mem":"三辆车口诀“抢、诈、葬”：第一辆被乱兵抢，第二辆的钱被侦探诈，第三辆为葬虎妞卖掉。书名里的“骆驼”是祥子从兵营逃出时顺手牵来的三匹骆驼。","mix":"《茶馆》是话剧，《四世同堂》写抗战北平；与祥子成婚的是虎妞，不是小福子或四凤。","mcq":[{"q":"《骆驼祥子》主人公的职业是","o":["茶馆掌柜","码头工人","小学教师","人力车夫"],"a":3,"w":"茶馆掌柜王利发出自《茶馆》。"},{"q":"《骆驼祥子》中，与祥子成婚的人物是","o":["小福子","四凤","虎妞","翠翠"],"a":2,"w":"四凤出自《雷雨》，翠翠出自《边城》。"}],"rel":[{"t":"老舍","n":"作者"},{"t":"《茶馆》","n":"同一作者的话剧"},{"t":"《四世同堂》","n":"同一作者的长篇"},{"t":"鲁迅笔下人物","n":"同写底层小人物"}],"more":"1936年起连载于《宇宙风》；主要人物：祥子、虎妞、小福子","exam":[]},{"id":"a08-030","t":"《茶馆》","cid":"08e","p":1,"kind":"作品","one":"老舍三幕话剧，以裕泰茶馆写清末、民初、抗战后三个时代。","ans":"《茶馆》是**老舍1957年发表的三幕话剧**，是**中国当代话剧的经典**。全剧以北京**裕泰茶馆**及掌柜**王利发**为中心，选取**戊戌变法失败后的清末、民国初年军阀混战时期、抗战胜利后**三个时代的片段，通过常四爷、秦仲义等众多人物，以茶馆的兴衰映照社会变迁。结尾王利发自尽，三位老人撒纸钱为自己送葬，象征旧时代的埋葬。1958年北京人民艺术剧院首演，焦菊隐导演，是**北京人艺的保留剧目**。","pts":["1957年，老舍，三幕话剧","裕泰茶馆，王利发","清末、民初、抗战后三个时代"],"mem":"三幕三个时代，茶馆从兴到衰：清末（戊戌后）、民初（军阀）、抗战胜利后。画面：结尾三位老人给自己撒纸钱。人物配对：王利发（掌柜）、常四爷、秦仲义。","mix":"《龙须沟》是老舍1951年话剧；《雷雨》是曹禺的话剧；《茶馆》是话剧，不是小说。","mcq":[{"q":"老舍话剧《茶馆》共有","o":["两幕","三幕","四幕","五幕"],"a":1,"w":"分别写清末、民初、抗战胜利后。"},{"q":"《茶馆》中的茶馆掌柜是","o":["王利发","常四爷","秦仲义","周朴园"],"a":0,"w":"常四爷、秦仲义是茶客，周朴园出自《雷雨》。"}],"rel":[{"t":"老舍","n":"作者"},{"t":"《骆驼祥子》","n":"同一作者的长篇"},{"t":"曹禺《雷雨》","n":"同为话剧名作"},{"t":"春柳社与中国话剧开端","n":"话剧发展对照"}],"more":"1957年发表；1958年北京人艺首演，焦菊隐导演；主要人物：王利发、常四爷、秦仲义","exam":[]},{"id":"a08-031","t":"《四世同堂》","cid":"08e","p":2,"kind":"作品","alias":["四世同堂"],"one":"老舍长篇小说，三部《惶惑》《偷生》《饥荒》，写北平沦陷。","ans":"《四世同堂》是**老舍的长篇小说**，1944至1950年间写成，共三部：**《惶惑》《偷生》《饥荒》**。小说以北平**小羊圈胡同**祁家四世同堂的遭遇为线索，写北平沦陷八年间普通市民在屈辱、苟活与反抗之间的选择，祁老人、祁瑞宣是主要人物。作品用京味语言描绘市民文化，揭示民族气节与文化心理，是老舍继《骆驼祥子》之后的又一部长篇代表作。","pts":["老舍长篇，三部：惶惑、偷生、饥荒","写北平沦陷期小羊圈胡同祁家","市民群像与民族气节"],"mem":"三部曲的三个词按情绪递进：惶惑（慌）、偷生（忍）、饥荒（饿），一部比一部苦。地点“小羊圈胡同”配“祁家”，想“羊圈里的祁家”。","mix":"《骆驼祥子》写人力车夫，《茶馆》是话剧；《四世同堂》写北平沦陷，不要和巴金写成都高家的《家》混淆。","mcq":[{"q":"老舍《四世同堂》的三部是","o":["《惶惑》《偷生》《饥荒》","《家》《春》《秋》","《春蚕》《秋收》《残冬》","《雾》《雨》《电》"],"a":0,"w":"《惶惑》《偷生》《饥荒》写北平沦陷期祁家的遭遇。"}],"rel":[{"t":"老舍","n":"作者"},{"t":"《骆驼祥子》","n":"代表小说"},{"t":"《茶馆》","n":"代表话剧"},{"t":"激流三部曲（巴金）","n":"同写大家庭"}],"more":"《惶惑》（1944）、《偷生》（1946）、《饥荒》（1950）\n主要人物：祁老人、祁瑞宣、祁瑞丰、祁瑞全","exam":[]},{"id":"a08-032","t":"曹禺四大剧","cid":"08e","p":2,"kind":"合称","alias":["曹禺四大名剧"],"one":"曹禺四部代表话剧：《雷雨》《日出》《原野》《北京人》。","ans":"曹禺四大剧指**《雷雨》《日出》《原野》《北京人》**，是曹禺（万家宝）话剧创作的代表，**1934至1941年**陆续完成。《雷雨》写周鲁两家恩怨，《日出》写交际花陈白露与都市罪恶，《原野》写农民仇虎复仇，《北京人》写北平曾家的衰败。四部作品**把现代话剧推向成熟**，在人物心理与戏剧结构上成就很高。","pts":["《雷雨》《日出》《原野》《北京人》","1934至1941年陆续完成","现代话剧成熟的代表"],"mem":"口诀“雷日原京”：雷雨、日出、原野、北京人。画面：从“雷雨”的夜晚到“日出”的清晨，走过“原野”，来到“北京”。","mix":"《茶馆》是老舍，《关汉卿》是田汉，《家》是曹禺改编巴金；《蜕变》也是曹禺作品但不在四大剧之列。","mcq":[{"q":"下列话剧中，不属于曹禺四大剧的是","o":["《雷雨》","《日出》","《茶馆》","《北京人》"],"a":2,"w":"《茶馆》是老舍的话剧。"}],"members":[["《雷雨》","周鲁两家的悲剧，1934"],["《日出》","陈白露，都市罪恶"],["《原野》","仇虎复仇，农村背景"],["《北京人》","曾家没落，愫方"]],"rel":[{"t":"曹禺","n":"作者"},{"t":"曹禺《雷雨》","n":"其中第一部"},{"t":"《茶馆》","n":"老舍话剧对照"},{"t":"古希腊三大悲剧家","n":"中西悲剧对照"}],"more":"《雷雨》（1934）、《日出》（1936）、《原野》（1937）、《北京人》（1941）","exam":[]},{"id":"a08-033","t":"《随想录》","cid":"08e","p":2,"kind":"作品","alias":["随想录"],"one":"巴金晚年代表作，五集150篇，提倡“讲真话”。","ans":"《随想录》是**巴金晚年的代表作**，1978至1986年写成，共**五集150篇**，即《随想录》《探索集》《真话集》《病中集》《无题集》。作品以散文形式回顾“文革”经历，**反省与忏悔**，提倡**“讲真话”**，并建议建立“文革”博物馆。它以真诚的自省著称，被视为当代散文的重要成就。","pts":["巴金晚年，1978至1986年，五集150篇","反思“文革”，倡导“讲真话”","建议建立“文革”博物馆"],"mem":"数字“五集一百五”：五集、150篇，8年写成。关键词“真话”，五集里正好有一集就叫《真话集》。","mix":"《随想录》是散文，不是小说；巴金的小说是《家》《春》《秋》《寒夜》。","mcq":[{"q":"巴金晚年提倡“讲真话”的作品是","o":["《寒夜》","《随想录》","《激流》","《憩园》"],"a":1,"w":"《随想录》1978至1986年写成，提倡“讲真话”。"}],"rel":[{"t":"巴金","n":"作者"},{"t":"激流三部曲（巴金）","n":"早期代表作"},{"t":"伤痕文学","n":"同期反思“文革”"},{"t":"反思文学","n":"同期反思思潮"}],"more":"五集：《随想录》《探索集》《真话集》《病中集》《无题集》\n建议建立“文革”博物馆。","exam":[]},{"id":"a08-034","t":"田汉","cid":"08e","p":2,"kind":"人物","alias":["田汉","南国社"],"one":"话剧奠基人，《义勇军进行曲》词作者，南国社创办者。","ans":"田汉（1898–1968），**湖南长沙人**，**戏剧家**，与欧阳予倩、洪深并称**中国话剧奠基人**。他创办南国社，话剧有《名优之死》《获虎之夜》，晚年作历史剧**《关汉卿》**（1958）。1935年为电影《风云儿女》写主题歌词，即**《义勇军进行曲》**，聂耳作曲，后成为国歌。他的创作推动了话剧的民族化，他也是左翼戏剧运动的重要人物。","pts":["话剧奠基人，与欧阳予倩、洪深并称","南国社，《名优之死》《关汉卿》","《义勇军进行曲》词作者"],"mem":"一人两首：作歌词《义勇军进行曲》，作剧本《关汉卿》，一首国歌，一部写元曲大家。三位奠基人口诀：“田欧洪”。","mix":"《义勇军进行曲》词是田汉，曲是聂耳；《黄河大合唱》词是光未然，曲是冼星海；《关汉卿》写的是元曲作家关汉卿。","mcq":[{"q":"《义勇军进行曲》的词作者是","o":["聂耳","光未然","田汉","冼星海"],"a":2,"w":"田汉作词，聂耳作曲；《黄河大合唱》才是光未然词、冼星海曲。"}],"rel":[{"t":"《义勇军进行曲》","n":"所作歌词"},{"t":"冼星海与光未然","n":"同期抗战歌曲对照"},{"t":"关汉卿","n":"其剧《关汉卿》的主角"},{"t":"春柳社与中国话剧开端","n":"话剧发展脉络"}],"more":"话剧：《名优之死》《获虎之夜》《关汉卿》《文成公主》\n《义勇军进行曲》（1935，电影《风云儿女》主题歌）","exam":[]},{"id":"a08-035","t":"《边城》","cid":"08f","p":1,"kind":"作品","alias":["边城","茶峒","翠翠"],"one":"沈从文1934年的中篇小说，写湘西茶峒翠翠的爱情，京派代表作。","ans":"《边城》是**沈从文1934年出版的中篇小说**，被视为**京派小说的代表作**。作品以**湘西边城茶峒**为背景，写撑渡船的老船夫与外孙女**翠翠**相依为命，翠翠与船总之子**天保、傩送**兄弟的爱情因误会错位：天保意外淹死，傩送远走，爷爷在雨夜去世，翠翠仍守在渡口，等待那个“也许明天回来”的人。小说语言清新质朴，以牧歌式笔调**赞美淳朴的人情与人性美**，沈从文自称要建造供奉“人性”的小庙，是**中国现代抒情小说**的经典。","pts":["沈从文1934年中篇，京派代表作","湘西茶峒：翠翠、天保、傩送","牧歌笔调，供奉“人性”的小庙"],"mem":"一个画面记全：**一条渡船，一座白塔，三个年轻人**。翠翠守渡口，天保、傩送兄弟同爱一人，哥哥淹死，弟弟出走，爷爷去世，只剩翠翠和结尾那句“这个人也许永远不回来了，也许‘明天’回来”。人名口诀：翠翠等，天保死，傩送走。","mix":"沈从文属京派，与海派（新感觉派、张爱玲）对举；《边城》是中篇，不是长篇；《湘行散记》是他的散文集，《从文自传》是自传，都不是小说。同样写乡土，鲁迅写的是愚昧的农村，沈从文写的是理想化的人性。","mcq":[{"q":"沈从文的中篇小说《边城》以哪里为背景","o":["湘西茶峒","鲁镇","北京胡同","高密东北乡"],"a":0,"w":"《边城》写湘西茶峒的渡船人家与翠翠的爱情；鲁镇是鲁迅小说背景，高密东北乡是莫言的文学地理。"},{"q":"下列作品与作者对应错误的是","o":["沈从文写《边城》","老舍写《骆驼祥子》","萧红写《呼兰河传》","巴金写《边城》"],"a":3,"w":"《边城》是沈从文所作，巴金代表作是《家》《寒夜》等。"}],"rel":[{"t":"沈从文","n":"《边城》作者，京派代表"},{"t":"京派与海派","n":"京派乡土与海派都市对举"},{"t":"萧红","n":"同写故乡，抒情风格相近"},{"t":"《平凡的世界》","n":"另一部乡土长篇，背景在陕北"}],"more":"《边城》结尾：这个人也许永远不回来了，也许“明天”回来！\n沈从文：湖南凤凰人，另有《湘行散记》《从文自传》，晚年转治古代服饰研究（《中国古代服饰研究》）。","exam":[]},{"id":"a08-036","t":"新感觉派","cid":"08f","p":3,"kind":"流派","exam":[],"alias":[],"one":"1930年代上海，刘呐鸥、穆时英、施蛰存，借鉴日本新感觉派写都市心理","ans":"1930年代上海，刘呐鸥、穆时英、施蛰存，借鉴日本新感觉派写都市心理","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-037","t":"东北作家群","cid":"08f","p":2,"kind":"合称","alias":["东北作家","二萧"],"one":"九一八后流亡关内的东北作家，代表萧红、萧军、端木蕻良等。","ans":"东北作家群是**1931年九一八事变后流亡关内的一批东北作家**的合称，在上海、北平等地写作，以故乡的沦陷、抗争与流亡为共同主题。主要成员有**萧红、萧军、端木蕻良、舒群、骆宾基**。萧红《生死场》、萧军《八月的乡村》在**鲁迅**帮助下出版，鲁迅为二萧作序。他们把东北的土地与人民写进现代文学，是**抗战文学的重要一翼**。","pts":["九一八后流亡关内的东北作家","萧红《生死场》、萧军《八月的乡村》","鲁迅为二萧作序，抗战文学重要一翼"],"members":[["萧红","《生死场》《呼兰河传》"],["萧军","《八月的乡村》"],["端木蕻良","《科尔沁旗草原》"],["舒群","《没有祖国的孩子》"],["骆宾基","《边陲线上》"]],"mem":"画面记忆：**黑土地被占，作家流亡，笔下写的全是回不去的家**。人名记“二萧端木舒骆”。二萧夫妻档，萧军写战争（乡村），萧红写生死与童年（生死场、呼兰河）。","mix":"《呼兰河传》是萧红，《八月的乡村》是萧军，别互换；东北作家群不包括沈从文、废名等京派作家。","mcq":[{"q":"长篇小说《八月的乡村》的作者是","o":["萧红","端木蕻良","萧军","舒群"],"a":2,"w":"《八月的乡村》是萧军作品，萧红写《生死场》，二人作品均由鲁迅作序。"}],"rel":[{"t":"萧红","n":"东北作家群代表"},{"t":"鲁迅","n":"为二萧作序、扶持"},{"t":"左联","n":"二萧与左联关系密切"},{"t":"京派与海派","n":"同期另两大文学群体"}],"more":"萧红《生死场》（1935）；萧军《八月的乡村》（1935）；端木蕻良《科尔沁旗草原》；萧红《呼兰河传》（1940）。","exam":[]},{"id":"a08-038","t":"张恨水","cid":"08f","p":3,"kind":"人物","exam":[],"alias":[],"one":"《啼笑因缘》《金粉世家》","ans":"《啼笑因缘》《金粉世家》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-039","t":"林徽因","cid":"08f","p":3,"kind":"人物","exam":[],"alias":[],"one":"《你是人间的四月天》；参与设计国徽和人民英雄纪念碑","ans":"《你是人间的四月天》；参与设计国徽和人民英雄纪念碑","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-040","t":"左联五烈士","cid":"08g","p":1,"kind":"合称","alias":["左联五烈士","龙华五烈士","柔石","殷夫","胡也频","冯铿","李伟森","李求实"],"one":"1931年2月在上海龙华被杀的柔石、殷夫、胡也频、冯铿、李伟森。","ans":"左联五烈士指**1931年2月在上海龙华被国民党当局杀害的五位左联作家**：**柔石、殷夫、胡也频、冯铿、李伟森**（又名李求实）。他们是中国共产党员，在上海参加秘密会议时被捕，与其他共产党人一同遇害，事件发生在左联成立次年，是国民党文化“围剿”的重大惨案。其中冯铿是唯一的女性，胡也频是丁玲的丈夫。**鲁迅**写下《**为了忘却的记念**》（1933年）追述与柔石等人的交往，并作《中国无产阶级革命文学和前驱的血》，使这一事件成为现代文学史的重要纪念。","pts":["1931年2月上海龙华遇害的五位左联作家","柔石、殷夫、胡也频、冯铿、李伟森","鲁迅《为了忘却的记念》悼念"],"members":[["柔石","小说《二月》《为奴隶的母亲》，鲁迅的学生与好友"],["殷夫","诗人，诗集《孩儿塔》，五人中最年轻"],["胡也频","小说家，丁玲的丈夫"],["冯铿","唯一的女性，小说《红的日记》"],["李伟森","笔名李求实，左联党团成员"]],"mem":"首字串联“**柔殷胡冯李**”（自编，读作“柔印糊风里”）。再挂三个记忆点：**一女（冯铿）**，**一夫妻（胡也频与丁玲）**，**一师友（柔石与鲁迅）**。年份：左联1930年成立，五烈士1931年遇害，隔一年。2026年是鲁迅逝世90周年，《为了忘却的记念》是鲁迅杂文名篇之一。","mix":"《记念刘和珍君》写的是1926年三一八惨案，《为了忘却的记念》写的才是左联五烈士，两篇都是鲁迅的悼念文章，常被互换作干扰项。丁玲是五烈士之一胡也频的妻子，本人1933年被捕后获释，不在五烈士之列。","mcq":[{"q":"下列作家中，不属于“左联五烈士”的是","o":["柔石","殷夫","冯铿","丁玲"],"a":3,"w":"左联五烈士是柔石、殷夫、胡也频、冯铿、李伟森；丁玲是胡也频的妻子，并未在此次遇害。"},{"q":"鲁迅为悼念左联五烈士写下的文章是","o":["《记念刘和珍君》","《为了忘却的记念》","《藤野先生》","《拿来主义》"],"a":1,"w":"《为了忘却的记念》1933年写成，追忆柔石等烈士；《记念刘和珍君》悼念三一八惨案死难者。"}],"rel":[{"t":"左联","n":"五烈士所属团体"},{"t":"鲁迅","n":"作《为了忘却的记念》"},{"t":"丁玲","n":"胡也频之妻"},{"t":"鲁迅逝世90周年","n":"2026年鲁迅周年"}],"more":"鲁迅《为了忘却的记念》写于1933年2月；另有《中国无产阶级革命文学和前驱的血》（1931年，载《前哨》纪念专号）。","exam":[]},{"id":"a08-041","t":"两个口号论争","cid":"08g","p":3,"kind":"事件","exam":[],"alias":[],"one":"1936年“国防文学”（周扬等）与“民族革命战争的大众文学”（鲁迅、胡风等）","ans":"1936年“国防文学”（周扬等）与“民族革命战争的大众文学”（鲁迅、胡风等）之争","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-042","t":"山药蛋派","cid":"08g","p":1,"kind":"流派","alias":["山药蛋派","赵树理方向","西李马胡孙"],"one":"以赵树理为代表的山西作家群，语言通俗质朴，面向农民。","ans":"山药蛋派是**20世纪40至50年代以山西作家为主形成的小说流派**，以**赵树理**为代表，成员还有**马烽、西戎、李束为、孙谦、胡正**，合称“西李马胡孙”。因作品**乡土气息浓郁、语言通俗朴实**，像山药蛋一样质朴而得名。他们贯彻延安文艺座谈会精神，**面向农民读者，吸收评书式的白描手法**，真实反映农村生活与农民心理，代表作有赵树理《小二黑结婚》《李有才板话》《三里湾》，马烽、西戎合著《吕梁英雄传》。该流派体现**文艺大众化、民族化**，影响深远。","pts":["赵树理为代表的山西作家群","西李马胡孙，语言通俗质朴","面向农民，大众化、民族化"],"members":[["赵树理","《小二黑结婚》《李有才板话》《三里湾》"],["西戎","《吕梁英雄传》（与马烽合著）"],["李束为","笔名束为，山西作家"],["马烽","《吕梁英雄传》，电影《我们村里的年轻人》"],["胡正","山西作家，《汾水长流》"],["孙谦","山西作家"]],"mem":"通行口诀“**西李马胡孙**”（西戎、李束为、马烽、胡正、孙谦），领头的赵树理单记。画面：山西黄土地上的山药蛋，土里土气，说的是农民自己的话。与荷花淀派对记：**山药蛋（山西，质朴幽默）对荷花（河北白洋淀，清新抒情）**。","mix":"荷花淀派的代表孙犁来自河北，山药蛋派的赵树理来自山西；周立波《暴风骤雨》写东北土改，丁玲《太阳照在桑干河上》写河北土改，都不属于山药蛋派。","mcq":[{"q":"山药蛋派的代表作家是","o":["赵树理","孙犁","周立波","丁玲"],"a":0,"w":"赵树理是山西作家，山药蛋派的代表；孙犁属荷花淀派。"},{"q":"下列作家中，不属于“西李马胡孙”的是","o":["西戎","马烽","胡正","孙犁"],"a":3,"w":"西李马胡孙是西戎、李束为、马烽、胡正、孙谦，孙犁是河北作家，属荷花淀派。"}],"rel":[{"t":"赵树理","n":"流派代表"},{"t":"荷花淀派","n":"北方乡土小说成对流派"},{"t":"延安文艺座谈会","n":"流派形成的文艺政策背景"},{"t":"寻根文学","n":"后来的乡土与文化书写"}],"more":"赵树理（1906–1970），山西沁水人，其创作被称为“赵树理方向”。\n代表作：《小二黑结婚》（1943）《李有才板话》《李家庄的变迁》《三里湾》。","exam":[]},{"id":"a08-043","t":"荷花淀派","cid":"08g","p":1,"kind":"流派","alias":["荷花淀派","荷花淀","白洋淀"],"one":"以孙犁为代表，写河北白洋淀，清新抒情的诗化小说流派。","ans":"荷花淀派是**以孙犁为代表的当代抒情小说流派**，因孙犁**1945年发表的短篇《荷花淀》**得名。作品多取材于**抗日战争时期的河北白洋淀一带**，不直接写战场，而写**水生嫂等普通农村妇女**在战争中的成长，语言清新，富有**诗情画意**，被称为“诗化小说”。孙犁另有《芦花荡》《铁木前传》《风云初记》，后来刘绍棠、从维熙、韩映山等作家受其影响。与山药蛋派的质朴谐趣相对，荷花淀派突出**抒情与人情美**，丰富了革命现实主义创作的审美风格。","pts":["孙犁《荷花淀》得名，写白洋淀","清新抒情的诗化小说","与山药蛋派风格对举"],"mem":"画面：**白洋淀上荷花开，水生嫂在家编席等丈夫**，战争被写成一幅水乡画。与山药蛋派对记：**山药蛋＝山西赵树理，质朴；荷花淀＝河北孙犁，抒情**，一土一雅，一山西一河北。","mix":"孙犁与赵树理同属解放区作家，但孙犁属荷花淀派，赵树理属山药蛋派；荷花淀在河北，不是山西或东北。","mcq":[{"q":"短篇小说《荷花淀》的作者是","o":["赵树理","孙犁","周立波","柳青"],"a":1,"w":"《荷花淀》是孙犁1945年作品，荷花淀派因此得名。"},{"q":"荷花淀派的小说主要描写的地域是","o":["陕北黄土高原","湘西","河北白洋淀一带","山西吕梁"],"a":2,"w":"荷花淀派以孙犁为代表，取材于河北白洋淀一带的抗日斗争。"}],"rel":[{"t":"孙犁","n":"流派代表"},{"t":"山药蛋派","n":"北方乡土小说成对流派"},{"t":"延安文艺座谈会","n":"创作背景"},{"t":"沈从文","n":"同以抒情笔调写乡土"}],"more":"孙犁（1913–2002），河北安平人，代表作《荷花淀》《芦花荡》《铁木前传》《风云初记》。","exam":[]},{"id":"a08-044","t":"《小二黑结婚》","cid":"08g","p":2,"kind":"作品","alias":["小二黑结婚"],"one":"赵树理1943年作，写解放区青年反对包办婚姻，山药蛋派开山作。","ans":"《小二黑结婚》是**赵树理1943年发表的中篇小说**，属解放区文学。小说写太行根据地青年**小二黑与小芹**自由恋爱，遭到小二黑的父亲“二诸葛”、小芹的母亲“三仙姑”等人的阻挠，最后在区政府支持下成婚，批判了**包办婚姻**与封建迷信。作品语言通俗，人物与情节贴近农民，被视为**“山药蛋派”的开山之作**，是文艺大众化的代表。","pts":["赵树理1943年作，解放区文学","小二黑与小芹反对包办婚姻","二诸葛、三仙姑；山药蛋派开山作"],"mem":"人物谐音记：**“二诸葛”迷信风水，“三仙姑”装神弄鬼，小二黑小芹是“自由恋爱一对”**。名字带“诸葛、仙姑”的都是封建落后代表，小二黑小芹是新青年。","mix":"《李有才板话》（同年）是赵树理另一代表作，写农村斗争，别当成《小二黑结婚》；《白毛女》也是解放区作品，但属新歌剧。","mcq":[{"q":"《小二黑结婚》所属的文学流派是","o":["荷花淀派","山药蛋派","新月派","七月诗派"],"a":1,"w":"作者赵树理开创山药蛋派。"}],"rel":[{"t":"赵树理","n":"作者"},{"t":"山药蛋派","n":"所属流派"},{"t":"延安文艺座谈会","n":"创作方向背景"},{"t":"《白毛女》","n":"同属解放区代表作"}],"more":"人物：小二黑、小芹、二诸葛、三仙姑、金旺、兴旺。","exam":[]},{"id":"a08-045","t":"《白毛女》","cid":"08g","p":1,"kind":"作品","alias":["白毛女","白毛仙姑","喜儿","杨白劳"],"one":"1945年延安鲁艺集体创作的新歌剧，写喜儿的遭遇。","ans":"《白毛女》是**1945年延安鲁迅艺术学院集体创作的新歌剧**，由**贺敬之、丁毅执笔**，**马可**等作曲，取材于晋察冀边区流传的“白毛仙姑”传说。剧中**佃农杨白劳**被地主黄世仁逼债而死，其女**喜儿**被抢入黄家，逃入深山，因久不见盐而头发变白，后被八路军战士大春救出。主题是“**旧社会把人变成鬼，新社会把鬼变成人**”。它是**延安文艺座谈会精神的成果**，开创了**民族新歌剧**的道路，后被改编为电影、芭蕾舞剧。","pts":["1945年延安鲁艺集体创作，贺敬之、丁毅执笔","杨白劳、喜儿、黄世仁、大春","旧社会把人变成鬼，新社会把鬼变成人"],"mem":"一个“白”字串起：**杨白劳（白）→白毛女（白）**，人名里的“白”和头发的“白”。主题句要背：“旧社会把人变成鬼，新社会把鬼变成人”。年份：1942年座谈会，1945年《白毛女》，三年后成果。","mix":"《白毛女》是新歌剧，《黄河大合唱》是声乐套曲；两部都出自延安，但《黄河大合唱》写于1939年，早于座谈会。芭蕾舞剧《白毛女》和现代京剧样板戏是后来的改编与创作，不是原作。","mcq":[{"q":"“旧社会把人变成鬼，新社会把鬼变成人”概括的作品是","o":["《小二黑结婚》","《黄河大合唱》","《红岩》","《白毛女》"],"a":3,"w":"《白毛女》写喜儿从被迫逃入深山到重见天日的经历。"},{"q":"新歌剧《白毛女》创作于","o":["延安鲁迅艺术学院","陕北公学","西南联大","上海艺术剧社"],"a":0,"w":"《白毛女》由延安鲁艺集体创作，1945年首演。"}],"rel":[{"t":"歌剧《白毛女》","n":"同一作品的歌剧条目"},{"t":"延安鲁迅艺术学院","n":"创作单位"},{"t":"延安文艺座谈会","n":"创作背景"},{"t":"《黄河大合唱》","n":"同簇延安艺术作品"}],"more":"主要人物：杨白劳、喜儿、黄世仁、王大春。\n插曲《北风吹》《扎红头绳》传唱甚广。","exam":[]},{"id":"a08-046","t":"延安鲁迅艺术学院","cid":"08g","p":3,"kind":"制度","exam":[],"alias":[],"one":"1938年在延安成立，简称鲁艺","ans":"1938年在延安成立，简称鲁艺","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-047","t":"三红一创、保林青山","cid":"08g","p":1,"kind":"合称","alias":["三红一创","保林青山","三红一创保林青山","三红一创，保林青山"],"one":"十七年长篇小说红色经典：红日、红旗谱、红岩，创业史，保卫延安等四部。","ans":"“三红一创，保林青山”是**对1949至1966年长篇小说红色经典的概括**。**三红**指**吴强《红日》、梁斌《红旗谱》、罗广斌和杨益言《红岩》**；**一创**指**柳青《创业史》**；**保林青山**指**杜鹏程《保卫延安》、曲波《林海雪原》、杨沫《青春之歌》、周立波《山乡巨变》**。《红日》《保卫延安》《林海雪原》写革命战争，《红旗谱》写农民斗争，《红岩》写狱中斗争，《创业史》《山乡巨变》写农业合作化，《青春之歌》写知识分子成长。这批作品奠定了**革命历史题材与农村题材**的创作模式。","pts":["三红：红日、红旗谱、红岩","一创：创业史；保林青山：保卫延安等四部","革命历史与农村题材的红色经典"],"members":[["《红日》","吴强，1957年，孟良崮战役"],["《红旗谱》","梁斌，1957年，农民朱老忠"],["《红岩》","罗广斌、杨益言，1961年，重庆狱中斗争"],["《创业史》","柳青，农业合作化，梁生宝"],["《保卫延安》","杜鹏程，1954年，保卫延安战役"],["《林海雪原》","曲波，1957年，杨子荣智取威虎山"],["《青春之歌》","杨沫，1958年，林道静"],["《山乡巨变》","周立波，1958年，农业合作化"]],"mem":"通行口诀“**三红一创，保林青山**”，“保林青山”是四部书名的首字（保卫延安、林海雪原、青春之歌、山乡巨变）。按题材分三组更牢：**战争（红日、保卫延安、林海雪原）、斗争（红旗谱、红岩、青春之歌）、农村（创业史、山乡巨变）**。","mix":"三红里没有《创业史》，它是“一创”；《红楼梦》不是红色经典；周立波的另一部《暴风骤雨》写东北土改，属解放区作品，不在这个口诀里；《林海雪原》作者是曲波，不是杜鹏程。","mcq":[{"q":"“三红”不包括下列哪部作品","o":["《红日》","《红旗谱》","《红岩》","《创业史》"],"a":3,"w":"“三红”是《红日》《红旗谱》《红岩》，《创业史》是“一创”。"},{"q":"《林海雪原》的作者是","o":["曲波","杜鹏程","周立波","杨沫"],"a":0,"w":"曲波《林海雪原》写杨子荣智取威虎山；杜鹏程作《保卫延安》，周立波作《山乡巨变》，杨沫作《青春之歌》。"}],"rel":[{"t":"红色经典","n":"这批作品的总称"},{"t":"《创业史》","n":"一创"},{"t":"《红岩》","n":"三红之一"},{"t":"周立波","n":"《山乡巨变》作者"},{"t":"样板戏","n":"同时期红色文艺形式"}],"more":"《红岩》1961年出版，取材重庆渣滓洞、白公馆狱中斗争，江姐、许云峰为主要人物。\n《林海雪原》中的杨子荣智取威虎山故事后被改编为样板戏。","exam":[]},{"id":"a08-048","t":"《红岩》","cid":"08g","p":2,"kind":"作品","alias":["红岩","江姐"],"one":"罗广斌、杨益言1961年出版，写重庆渣滓洞、白公馆狱中斗争。","ans":"《红岩》是**罗广斌、杨益言合著的长篇小说**，1961年出版，属**“红色经典”“三红一创”之一**。作者本是重庆“11·27”大屠杀的幸存者。小说以**重庆渣滓洞、白公馆**监狱为背景，写共产党员在狱中与国民党特务的斗争，塑造了**江姐、许云峰、成岗**等革命者形象。作品以革命信仰与气节为主题，曾改编为歌剧《江姐》、电影、电视剧，是革命英雄主义教育的重要读本。","pts":["罗广斌、杨益言，1961年出版","写重庆渣滓洞、白公馆狱中斗争","江姐、许云峰；三红一创之一"],"mem":"**“红岩”＝红色岩石＝坚不可摧**，记住地点“渣滓洞、白公馆”（重庆），人物“江姐、许云峰”。作者两人，罗广斌与杨益言，都是狱中幸存者，所以才能写得真。","mix":"《林海雪原》写东北剿匪，《青春之歌》写知识青年，《红岩》写重庆狱中斗争，别串场；《红岩》属“三红一创”，前两部属“保林青山”。","mcq":[{"q":"小说《红岩》的故事背景主要是","o":["延安窑洞","重庆渣滓洞、白公馆","东北林海雪原","陕北农村合作社"],"a":1,"w":"《红岩》写重庆国民党监狱中的地下党斗争，人物有江姐、许云峰。"}],"rel":[{"t":"红色经典","n":"所属类别"},{"t":"三红一创、保林青山","n":"“三红”之一"},{"t":"《创业史》","n":"同属“三红一创”"},{"t":"《英雄儿女》","n":"同脉的革命英雄叙事"}],"more":"作者罗广斌、杨益言曾被关押于渣滓洞、白公馆。\n中国青年出版社1961年12月出版。","exam":[]},{"id":"a08-049","t":"《创业史》","cid":"08g","p":3,"kind":"作品","exam":[],"alias":[],"one":"柳青，写陕西农村合作化，主人公梁生宝","ans":"柳青，写陕西农村合作化，主人公梁生宝","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-050","t":"八个样板戏","cid":"08g","p":3,"kind":"合称","exam":[],"alias":[],"one":"京剧《红灯记》《沙家浜》《智取威虎山》《海港》《奇袭白虎团》，芭蕾舞剧《红色","ans":"京剧《红灯记》《沙家浜》《智取威虎山》《海港》《奇袭白虎团》，芭蕾舞剧《红色娘子军》《白毛女》，交响音乐《沙家浜》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-051","t":"“双百”方针","cid":"08g","p":1,"kind":"制度","alias":["双百方针","百花齐放","百家争鸣","百花齐放百家争鸣","“双百”方针"],"one":"1956年毛泽东提出“百花齐放，百家争鸣”，发展艺术与科学的方针。","ans":"“双百”方针即**“百花齐放，百家争鸣”**，是**1956年由毛泽东提出的发展艺术和科学的方针**，同年5月陆定一代表中共中央作报告《百花齐放，百家争鸣》加以阐释。具体含义是**艺术上不同形式和风格自由发展，学术上不同学派自由争论**，通过讨论和实践判断是非，而不以行政命令强行推行某一种风格或学派。方针提出后，文艺界和学术界一度活跃。1957年毛泽东《关于正确处理人民内部矛盾的问题》又作论述，使它成为**社会主义文化建设的长期方针**。2026年是提出70周年。","pts":["1956年毛泽东提出“百花齐放，百家争鸣”","艺术上百花齐放，学术上百家争鸣","社会主义文化建设的长期方针，2026年70周年"],"mem":"分工记忆：**花对艺术，家对学术**，“百花”是文艺作品的风格，“百家”是学术学派。典故在先秦：“百家争鸣”原指战国诸子并起，所以毛泽东借来作学术方针。年份：1956年提出，2026年正好70周年。","mix":"“双百”方针（1956年，艺术与学术）不同于“为人民服务、为社会主义服务”的“二为”方向（1980年代），也不同于1942年的“文艺为工农兵服务”。百家争鸣的典故属于先秦诸子，方针是借用该词。","mcq":[{"q":"“百花齐放，百家争鸣”作为发展艺术和科学的方针提出于","o":["1949年","1956年","1966年","1978年"],"a":1,"w":"1956年由毛泽东提出，陆定一同年作报告阐释。"},{"q":"“双百”方针中，“百花齐放”主要针对的领域是","o":["军事","学术","艺术","外交"],"a":2,"w":"艺术问题上百花齐放，学术问题上百家争鸣。"}],"rel":[{"t":"百家争鸣","n":"方针借用的先秦典故"},{"t":"延安文艺座谈会","n":"此前的文艺方针"},{"t":"诸子百家","n":"“百家”的历史原型"},{"t":"文艺复兴","n":"中西思想文化繁荣对照"}],"more":"“艺术问题上的百花齐放，学术问题上的百家争鸣。”\n2026年是“双百”方针提出70周年。","exam":[]},{"id":"a08-052","t":"《红星照耀中国》","cid":"08g","p":2,"kind":"作品","alias":["红星照耀中国","西行漫记","Red Star Over China"],"one":"斯诺陕北采访纪实，1937年伦敦出版，1938年中译本名《西行漫记》。","ans":"《红星照耀中国》（Red Star Over China）是**美国记者埃德加·斯诺**的纪实著作。1936年斯诺赴陕北采访，写成此书，**1937年在伦敦出版**。书中向世界首次系统报道了中国共产党、红军、长征及毛泽东等人，打破了当时的信息封锁。**1938年中译本以《西行漫记》为名在上海出版**，在国内外产生巨大影响。它是20世纪重要的新闻报道，也是**翻译史上因译名与时代而改题的典型例子**。","pts":["斯诺1936年访问陕北，1937年伦敦出版","首次向世界系统报道红军与长征","1938年中译本名《西行漫记》"],"mem":"一书两名：**英文 Red Star Over China 直译为《红星照耀中国》，1938年中译本题为《西行漫记》**。年份“36年去、37年出、38年译”。","mix":"作者斯诺是美国人，不是英国人；斯诺另有妻子海伦·斯诺（尼姆·威尔斯）。《红星照耀中国》与《西行漫记》是同一本书。","mcq":[{"q":"1938年在上海出版的《西行漫记》，其英文原著的作者是","o":["赛珍珠","埃德加·斯诺","罗曼·罗兰","海明威"],"a":1,"w":"《西行漫记》即斯诺《红星照耀中国》的中译本。"}],"rel":[{"t":"斯诺《红星照耀中国》","n":"同一著作的另一词条"},{"t":"红军长征","n":"书中重要内容"},{"t":"长征精神","n":"长征胜利90周年相关"},{"t":"《七律·长征》","n":"同主题的毛泽东诗词"}],"more":"2026年是红军长征胜利90周年（1936–2026）。\n中译本由复社组织翻译出版。","exam":[]},{"id":"a08-053","t":"《七律·长征》","cid":"08g","p":2,"kind":"作品","alias":["七律长征","长征诗"],"one":"毛泽东1935年10月作，“红军不怕远征难，万水千山只等闲”。","ans":"《七律·长征》是**毛泽东1935年10月所作的七言律诗**，概括红军长征的历程。首联“**红军不怕远征难，万水千山只等闲**”点出乐观精神，颔联写五岭、乌蒙山，颈联写**金沙江、大渡河泸定桥**，尾联“**更喜岷山千里雪，三军过后尽开颜**”以翻越岷山作结。全诗把艰险写得从容，是**革命浪漫主义的代表作**，也是长征精神的文学表达。2026年是红军长征胜利90周年。","pts":["毛泽东1935年10月作，七言律诗","“红军不怕远征难，万水千山只等闲”","写五岭、乌蒙、金沙江、大渡河、岷山"],"mem":"按行军路线记：**五岭→乌蒙→金沙江→大渡河→岷山**，诗中地名“岭、蒙、沙、桥、岷”就是长征路线图。首联“不怕”，尾联“尽开颜”，一头一尾都是乐观。","mix":"别与同年的《清平乐·六盘山》（“不到长城非好汉”）、1936年的《沁园春·雪》（“北国风光”）混淆；《七律·长征》是律诗，不是词。","mcq":[{"q":"“更喜岷山千里雪，三军过后尽开颜”出自","o":["《沁园春·雪》","《清平乐·六盘山》","《忆秦娥·娄山关》","《七律·长征》"],"a":3,"w":"这是《七律·长征》尾联。"}],"rel":[{"t":"红军长征","n":"诗的历史背景"},{"t":"长征精神","n":"诗的精神内涵"},{"t":"《红星照耀中国》","n":"同主题的纪实著作"},{"t":"红军三大主力会师","n":"长征胜利的标志事件"}],"more":"全诗：红军不怕远征难，万水千山只等闲。五岭逶迤腾细浪，乌蒙磅礴走泥丸。金沙水拍云崖暖，大渡桥横铁索寒。更喜岷山千里雪，三军过后尽开颜。","exam":[]},{"id":"a08-054","t":"《东方红》","cid":"08g","p":3,"kind":"作品","exam":[],"alias":[],"one":"1964年大型音乐舞蹈史诗","ans":"1964年大型音乐舞蹈史诗","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-055","t":"伤痕文学","cid":"08h","p":1,"kind":"流派","alias":["伤痕文学","伤痕小说","《伤痕》","《班主任》"],"one":"新时期文学起点，因卢新华《伤痕》得名，控诉“文革”创伤。","ans":"伤痕文学是**1977至1979年前后出现的文学思潮**，因**卢新华1978年发表的短篇小说《伤痕》**得名，是**新时期文学的起点**。**刘心武《班主任》**（1977年）被视为开端。作品以“文革”中受迫害者的**创伤与苦难**为题材，揭露极左路线对人性和家庭的摧残，代表作还有郑义《枫》、冯骥才《啊！》等。它冲破“文革”文学的“假大空”，恢复了**现实主义传统**，其后发展为追问历史原因的**反思文学**。","pts":["卢新华《伤痕》得名，刘心武《班主任》开端","写“文革”中的创伤与苦难","新时期文学起点，发展为反思文学"],"mem":"新时期思潮顺序，取首字：**伤、反、改、寻、先、新**（伤痕、反思、改革、寻根、先锋、新写实），自编。逻辑线：**先痛（伤痕）→再问为什么（反思）→再往前走（改革）→往文化深处找（寻根）→在形式上试验（先锋）→回到日常（新写实）**。","mix":"《班主任》是开端，但思潮的名字来自《伤痕》；伤痕文学重在控诉苦难，反思文学（王蒙《布礼》、张贤亮《灵与肉》、茹志鹃《剪辑错了的故事》）重在追问历史原因，两者常作为连续的两环出题。","mcq":[{"q":"“伤痕文学”的名称来自","o":["刘心武《班主任》","卢新华《伤痕》","郑义《枫》","阿城《棋王》"],"a":1,"w":"伤痕文学得名于卢新华1978年的短篇小说《伤痕》；《班主任》被视为开端。"},{"q":"下列新时期文学思潮中，出现最早的是","o":["先锋文学","寻根文学","新写实小说","伤痕文学"],"a":3,"w":"伤痕文学1977至1979年出现，随后依次是反思、改革、寻根、先锋、新写实。"}],"rel":[{"t":"反思文学","n":"伤痕文学的后续思潮"},{"t":"改革文学","n":"新时期思潮链下一环"},{"t":"朦胧诗派","n":"同期诗歌思潮"},{"t":"知青文学","n":"同期题材相关"}],"more":"《班主任》刘心武，1977年；《伤痕》卢新华，1978年8月《文汇报》；《枫》郑义，1979年；《啊！》冯骥才，1979年。","exam":[]},{"id":"a08-056","t":"反思文学","cid":"08h","p":2,"kind":"流派","alias":["反思小说"],"one":"1979年前后承接伤痕文学，追问历史与社会根源的小说思潮。","ans":"反思文学是**1979年前后兴起、承接伤痕文学的小说思潮**，不再停留在写个人伤痛，而是**追问悲剧的历史与社会根源**，反思反右、“文革”等历史。代表作有**茹志鹃《剪辑错了的故事》**、**王蒙《蝴蝶》**、**古华《芙蓉镇》**、**高晓声《李顺大造屋》**。它推动新时期文学进入深层的历史思考，并启发了改革文学、寻根文学。","pts":["1979年前后，承接伤痕文学","追问历史与社会根源","《剪辑错了的故事》《蝴蝶》《芙蓉镇》《李顺大造屋》"],"mem":"思潮链首字：**伤、反、改、寻、先、新**（伤痕→反思→改革→寻根→先锋→新写实）。逻辑线：先哭伤口，再问为什么，再往前看，再回头找根，再玩形式，最后回到日常。","mix":"伤痕文学的代表是卢新华《伤痕》、刘心武《班主任》；反思文学代表是《芙蓉镇》《蝴蝶》；《乔厂长上任记》属改革文学。","mcq":[{"q":"下列作品中，属于反思文学的是","o":["《芙蓉镇》","《乔厂长上任记》","《棋王》","《一地鸡毛》"],"a":0,"w":"《芙蓉镇》是古华作品；《乔厂长上任记》是改革文学，《棋王》是寻根文学，《一地鸡毛》是新写实小说。"}],"rel":[{"t":"伤痕文学","n":"前一环"},{"t":"改革文学","n":"后一环"},{"t":"王蒙","n":"《蝴蝶》作者"},{"t":"寻根文学","n":"思潮链后续"}],"more":"其他：鲁彦周《天云山传奇》、张贤亮《灵与肉》。\n古华《芙蓉镇》获首届茅盾文学奖。","exam":[]},{"id":"a08-057","t":"改革文学","cid":"08h","p":2,"kind":"流派","alias":["改革小说"],"one":"1979年起写经济体制改革的思潮，蒋子龙《乔厂长上任记》为开端。","ans":"改革文学是**1979年前后兴起、以经济体制改革与现代化建设为题材**的文学思潮。**蒋子龙《乔厂长上任记》（1979）**被视为开端，写重工业厂长乔光朴整顿企业。其他代表作有**张洁《沉重的翅膀》**、柯云路《新星》。它把目光从批判历史转向**写当下的改革者与阻力**，是新时期文学“向前看”的一环。","pts":["1979年前后，写体制改革","蒋子龙《乔厂长上任记》为开端","《沉重的翅膀》《新星》"],"mem":"思潮链中的第三环：**伤→反→改**。“改”＝改革者“乔厂长”上任，记“**乔厂长＝改革文学开门第一人**”。","mix":"反思文学写过去，改革文学写当下；《乔厂长上任记》是中篇小说，作者蒋子龙，别与路遥《人生》混。","mcq":[{"q":"蒋子龙《乔厂长上任记》属于","o":["伤痕文学","反思文学","寻根文学","改革文学"],"a":3,"w":"《乔厂长上任记》（1979）被视为改革文学的开端。"}],"rel":[{"t":"反思文学","n":"前一环"},{"t":"寻根文学","n":"后一环"},{"t":"路遥","n":"写改革时代农村青年"},{"t":"新写实小说","n":"思潮链末端"}],"more":"蒋子龙《乔厂长上任记》（1979，《人民文学》）；张洁《沉重的翅膀》（1981）；柯云路《新星》（1984）。","exam":[]},{"id":"a08-058","t":"寻根文学","cid":"08h","p":1,"kind":"流派","alias":["寻根文学","寻根小说","文学的“根”","文学的根"],"one":"1985年前后的思潮，韩少功《文学的“根”》为宣言，向民族文化寻根。","ans":"寻根文学是**1985年前后出现的文学思潮**，以**韩少功1985年发表的《文学的“根”》**为宣言，主张文学应**挖掘和反思民族文化传统**，在传统文化、民间风俗与地域文化中寻找民族精神。它受**拉美“文学爆炸”和魔幻现实主义**启发，代表作有**阿城《棋王》、韩少功《爸爸爸》、王安忆《小鲍庄》、贾平凹“商州”系列**，莫言《红高粱》也常被归入。作品多取材乡村与边地，兼有文化批判。寻根文学**拓展了新时期文学的文化视野**，为莫言等人的创作铺路。","pts":["1985年韩少功《文学的“根”》为宣言","棋王、爸爸爸、小鲍庄、商州系列","受拉美魔幻现实主义启发，向民族文化寻根"],"mem":"一盘棋、一声爸、一座庄：**阿城《棋王》、韩少功《爸爸爸》、王安忆《小鲍庄》**。画面：一棵大树，文学是枝叶，文化传统是根，韩少功喊的就是“要找根”。因果线：**马尔克斯《百年孤独》写出拉美的根，中国作家也想写出中国的根**。","mix":"寻根文学向文化深处找内容，先锋文学在形式上实验，二者同在1980年代中期，容易互换；《棋王》也是知青题材，但被归入寻根文学。寻根文学宣言作者是韩少功，不是刘心武或莫言。","mcq":[{"q":"寻根文学的宣言《文学的“根”》的作者是","o":["阿城","莫言","韩少功","王安忆"],"a":2,"w":"韩少功1985年发表《文学的“根”》，寻根文学因此得名。"},{"q":"下列作品中，属于寻根文学的是","o":["《伤痕》","《棋王》","《冈底斯的诱惑》","《班主任》"],"a":1,"w":"阿城《棋王》是寻根文学代表作；《伤痕》《班主任》属伤痕文学，《冈底斯的诱惑》属先锋文学。"}],"rel":[{"t":"魔幻现实主义","n":"外来启发"},{"t":"拉丁美洲“文学爆炸”","n":"外来启发"},{"t":"《百年孤独》","n":"寻根作家的参照"},{"t":"先锋文学","n":"同期并行思潮"},{"t":"莫言","n":"《红高粱》常归入寻根"}],"more":"1984年12月杭州会议（《上海文学》等发起）是寻根思潮的重要起点。\n代表作：阿城《棋王》（1984）、韩少功《爸爸爸》（1985）、王安忆《小鲍庄》（1985）。","exam":[]},{"id":"a08-059","t":"先锋文学","cid":"08h","p":1,"kind":"流派","alias":["先锋文学","先锋小说","叙述圈套","新潮小说"],"one":"1980年代中后期的形式实验小说，马原、余华、苏童、格非、孙甘露、残雪。","ans":"先锋文学是**1980年代中后期兴起的形式实验小说思潮**，又称先锋小说，常以**1985年前后马原《冈底斯的诱惑》**为起点。代表作家有**马原、余华、苏童、格非、孙甘露、残雪**。他们受**西方现代主义和后现代主义**影响，注重**叙述方式和语言形式的革新**，淡化传统的人物与情节，常用叙述圈套、碎片化结构和暴力、死亡等意象，如马原“叙述圈套”、格非《迷舟》、余华《现实一种》。1990年代作家多转向现实题材，余华《活着》即是转型之作，但先锋实验**改变了中国小说的叙事观念**。","pts":["1980年代中后期，形式实验小说","马原、余华、苏童、格非、孙甘露、残雪","叙述圈套，受西方现代主义影响"],"members":[["马原","《冈底斯的诱惑》，“叙述圈套”"],["余华","《十八岁出门远行》《现实一种》，后转向《活着》"],["苏童","《妻妾成群》《罂粟之家》"],["格非","《迷舟》《褐色鸟群》"],["孙甘露","《信使之函》，诗化叙述"],["残雪","《山上的小屋》，梦魇式叙述"]],"mem":"六人串联“**马余苏格孙残**”（自编，读作“马鱼苏哥孙蝉”）。各记一个特点：马原**玩叙述**，余华**写暴力**，苏童**写南方旧事**，格非**写悬疑**（《迷舟》），孙甘露**写诗化语言**，残雪**写梦魇**。","mix":"先锋文学重形式，寻根文学重文化内容，新写实小说（池莉《烦恼人生》、刘震云《一地鸡毛》）写日常生活的琐碎；余华既是先锋代表，又有《活着》这样的现实主义作品，选择题常以此设陷阱。","mcq":[{"q":"下列作家中，不属于先锋文学代表的是","o":["马原","余华","路遥","格非"],"a":2,"w":"路遥是现实主义作家，代表作《平凡的世界》；马原、余华、格非等属先锋文学。"},{"q":"马原1985年的《冈底斯的诱惑》常被视为哪一思潮的起点","o":["伤痕文学","先锋文学","朦胧诗","改革文学"],"a":1,"w":"马原以“叙述圈套”开启先锋小说的形式实验。"}],"rel":[{"t":"余华","n":"先锋代表，后转向《活着》"},{"t":"孙甘露","n":"先锋作家，后获茅盾文学奖"},{"t":"寻根文学","n":"同期并行思潮"},{"t":"新写实小说","n":"随后的思潮"}],"more":"《冈底斯的诱惑》马原，1985年；《十八岁出门远行》余华，1987年；《迷舟》格非，1987年；《信使之函》孙甘露，1987年。","exam":[]},{"id":"a08-060","t":"新写实小说","cid":"08h","p":2,"kind":"流派","alias":["新写实","新写实主义"],"one":"1980年代末写普通人日常生活的小说，池莉、方方、刘震云。","ans":"新写实小说是**1980年代末兴起的小说思潮**，以**“原生态”描写普通人的日常生活**为特点，情感克制，不做英雄化或批判性的抽象处理。代表作有**池莉《烦恼人生》**、**方方《风景》**、**刘震云《一地鸡毛》**。它回应了先锋文学的形式热，回到现实，是**新时期思潮链的最后一环**，也影响了90年代的市民小说与都市写作。","pts":["1980年代末，写日常生活“原生态”","池莉《烦恼人生》、方方《风景》、刘震云《一地鸡毛》","回应先锋文学，思潮链最后一环"],"mem":"记法：**“烦恼、风景、鸡毛”**，三个作品名都是小日子：烦恼的人生、日常的风景、一地鸡毛。口诀“池方刘”＝池莉、方方、刘震云。","mix":"先锋文学重形式实验（余华、马原），新写实重生活原貌；两者前后相接，别互换代表作家。","mcq":[{"q":"《一地鸡毛》的作者是","o":["池莉","方方","余华","刘震云"],"a":3,"w":"刘震云《一地鸡毛》是新写实小说代表。"}],"rel":[{"t":"先锋文学","n":"前一环"},{"t":"寻根文学","n":"思潮链上游"},{"t":"余华","n":"先锋转向现实的作家"},{"t":"改革文学","n":"同属思潮链"}],"more":"池莉《烦恼人生》（1987）；方方《风景》（1987）；刘震云《单位》《一地鸡毛》；刘恒《狗日的粮食》。\n《钟山》1989年起推出“新写实小说大联展”。","exam":[]},{"id":"a08-061","t":"第三代诗歌","cid":"08h","p":3,"kind":"流派","exam":[],"alias":[],"one":"1980年代中期，“他们”诗群韩东、于坚，“非非主义”等","ans":"1980年代中期，“他们”诗群韩东、于坚，“非非主义”等","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-062","t":"知青文学","cid":"08h","p":3,"kind":"流派","exam":[],"alias":[],"one":"梁晓声《今夜有暴风雪》、史铁生《我的遥远的清平湾》、叶辛《蹉跎岁月》","ans":"梁晓声《今夜有暴风雪》、史铁生《我的遥远的清平湾》、叶辛《蹉跎岁月》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-063","t":"王蒙","cid":"08h","p":2,"kind":"人物","alias":["王蒙先生"],"one":"当代作家，《青春万岁》《组织部新来的年轻人》，《这边风景》获茅奖。","ans":"王蒙（1934– ），**河北南皮人，生于北京，当代作家**。1953年写成长篇**《青春万岁》**，1956年发表**《组织部新来的年轻人》**，后被划为右派，在新疆生活多年。新时期他以意识流手法写作，有**《布礼》《蝴蝶》**等，是**反思文学与意识流小说的代表**，曾任文化部部长。2015年**《这边风景》获第九届茅盾文学奖**，2019年获“人民艺术家”国家荣誉称号。","pts":["《青春万岁》《组织部新来的年轻人》","新时期意识流探索，《蝴蝶》","《这边风景》获第九届茅奖"],"mem":"一线串记：**“青春万岁→组织部青年→新疆多年→《蝴蝶》意识流→《这边风景》茅奖”**，把一生过成五个关键词。《这边风景》写新疆伊犁，对应他在新疆的经历。","mix":"《蝴蝶》是反思文学，《青春万岁》是少年心气；王蒙与金宇澄同为第九届茅奖得主（2015）。","mcq":[{"q":"王蒙因哪部作品获第九届茅盾文学奖","o":["《青春万岁》","《蝴蝶》","《这边风景》","《活动变人形》"],"a":2,"w":"《这边风景》获第九届茅盾文学奖（2015）。"}],"rel":[{"t":"反思文学","n":"代表作家"},{"t":"茅盾文学奖","n":"获奖"},{"t":"金宇澄","n":"同届茅奖得主"},{"t":"国家勋章和国家荣誉称号","n":"2019年获“人民艺术家”"}],"more":"主要作品：《青春万岁》《组织部新来的年轻人》《布礼》《蝴蝶》《活动变人形》《这边风景》。","exam":[]},{"id":"a08-064","t":"白先勇","cid":"08h","p":3,"kind":"人物","exam":[],"alias":[],"one":"《台北人》《孽子》；推动青春版《牡丹亭》","ans":"《台北人》《孽子》；推动青春版《牡丹亭》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-065","t":"余秋雨《文化苦旅》","cid":"08h","p":3,"kind":"作品","exam":[],"alias":[],"one":"1992年出版的文化散文集","ans":"1992年出版的文化散文集","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-066","t":"《平凡的世界》","cid":"08i","p":1,"kind":"作品","alias":["平凡的世界","孙少安","孙少平","双水村"],"one":"路遥长篇三部曲，写陕北孙氏兄弟，1991年获第三届茅盾文学奖。","ans":"《平凡的世界》是**路遥创作的长篇小说**，共**三部**，**1986年起陆续出版**，**1991年获第三届茅盾文学奖**。作品以**1975至1985年陕北黄土高原的双水村**为中心，通过**孙少安、孙少平兄弟**的奋斗历程，反映改革开放初期中国城乡的社会变迁。孙少安留在土地上办砖厂，孙少平走出农村去做工，两人代表农民不同的出路。小说以**现实主义手法**书写普通人的尊严与奋斗，被誉为当代青年的励志之书，长期畅销，并被改编为广播剧和电视剧。","pts":["路遥三部长篇，1991年第三届茅奖","陕北双水村，孙少安、孙少平兄弟","现实主义，普通人的奋斗，改革开放初期"],"mem":"一对兄弟，两条路：**少安留下办砖厂，少平出走做工人**，“安”留守、“平”远行。数字挂钩：**第三届茅奖、三部长篇**，都是“三”。路遥另有《人生》（1982年，主人公高加林），不要混作同一部。","mix":"《白鹿原》（陈忠实，关中，第四届茅奖）和《平凡的世界》都是陕西作家的长篇，前者写清末到1949年前后的家族，后者写1975至1985年的陕北农村；《人生》是路遥另一部中篇。","mcq":[{"q":"孙少安、孙少平兄弟是下列哪部作品的主人公","o":["《平凡的世界》","《白鹿原》","《活着》","《骆驼祥子》"],"a":0,"w":"《平凡的世界》以陕北双水村孙氏兄弟的奋斗为线索。"},{"q":"《平凡的世界》故事主要发生的地区是","o":["湘西茶峒","东北呼兰河","陕北双水村","江南小镇"],"a":2,"w":"小说以陕北黄土高原的双水村为中心，写1975至1985年的农村变迁。"}],"rel":[{"t":"路遥","n":"作者"},{"t":"茅盾文学奖","n":"第三届获奖"},{"t":"《白鹿原》","n":"同为陕西作家长篇"},{"t":"陈忠实","n":"陕西作家对举"}],"more":"路遥（1949–1992），陕西清涧人，另有《人生》（1982年）。\n《平凡的世界》1991年获第三届茅盾文学奖。","exam":[]},{"id":"a08-067","t":"《白鹿原》","cid":"08i","p":1,"kind":"作品","alias":["白鹿原","白嘉轩","鹿子霖","民族秘史"],"one":"陈忠实1993年长篇，写关中白鹿原两家，第四届茅盾文学奖。","ans":"《白鹿原》是**陈忠实创作的长篇小说**，**1993年出版**，**1997年获第四届茅盾文学奖**。作品以**关中平原的白鹿原**上**白嘉轩与鹿子霖**两家的纷争为主线，写**清末至1949年前后**半个世纪的家族兴衰与社会变迁，涉及辛亥革命、国共合作与分裂、农民运动等事件，塑造了白嘉轩、鹿子霖、朱先生、黑娃、田小娥等人物。扉页引用巴尔扎克的话“**小说被认为是一个民族的秘史**”，体现以家族写民族的追求，小说也是**陕西作家与新时期现实主义长篇**的代表，曾改编为电影、电视剧、话剧。","pts":["陈忠实1993年长篇，1997年第四届茅奖","白嘉轩与鹿子霖，关中白鹿原","引巴尔扎克“民族的秘史”"],"mem":"一个原上的两个家：**白嘉轩（白家）对鹿子霖（鹿家）**，名字里的“白”与“鹿”就是原名。扉页那句“一个民族的秘史”要背。年份：1993年出版，1997年获奖，《平凡的世界》是1991年，两部陕西长篇相差六年。","mix":"《白鹿原》写关中，《平凡的世界》写陕北；《白鹿原》作者陈忠实，不是贾平凹（《秦腔》《废都》）；“小说被认为是一个民族的秘史”是巴尔扎克的话，被陈忠实引用，不是陈忠实自创。","mcq":[{"q":"扉页引用巴尔扎克“小说被认为是一个民族的秘史”的作品是","o":["《平凡的世界》","《白鹿原》","《活着》","《长恨歌》"],"a":1,"w":"陈忠实《白鹿原》扉页引用了巴尔扎克的这句话。"},{"q":"《白鹿原》的作者是","o":["路遥","贾平凹","莫言","陈忠实"],"a":3,"w":"《白鹿原》是陈忠实1993年的长篇，获第四届茅盾文学奖。"}],"rel":[{"t":"陈忠实","n":"作者"},{"t":"《平凡的世界》","n":"同为陕西作家长篇"},{"t":"茅盾文学奖","n":"第四届获奖"},{"t":"路遥","n":"陕西作家对举"}],"more":"主要人物：白嘉轩、鹿子霖、朱先生、黑娃、田小娥。\n陈忠实（1942–2016），陕西西安人。","exam":[]},{"id":"a08-068","t":"《活着》","cid":"08i","p":1,"kind":"作品","alias":["活着","福贵","余华《活着》"],"one":"余华1992年长篇，写福贵一生，张艺谋1994年改编电影。","ans":"《活着》是**余华1992年发表的长篇小说**，载于《收获》，是**先锋作家转向现实主义的代表作**。小说以**福贵**的一生为线索，从1940年代的地主少爷、赌徒，写到土改、大跃进、“文革”中**家珍、有庆、凤霞、二喜、苦根**等亲人相继离世，最后只与一头老牛相伴。作品以**冷静克制的叙述**写苦难中人对“活着”的承受，**1994年经张艺谋改编为同名电影，获戛纳电影节评审团大奖**，葛优获最佳男演员奖，推动了这部小说的传播。","pts":["余华1992年长篇，主人公福贵","从先锋转向现实主义，写苦难与承受","1994年张艺谋改编电影，获戛纳评审团大奖"],"mem":"画面：**一个老人，一头老牛，牛也叫福贵**。亲人离世的顺序可连成一串：有庆（抽血）、凤霞（难产）、家珍（病）、二喜（事故）、苦根。年份：1992年小说，1994年电影，相隔两年。","mix":"《活着》与《许三观卖血记》都是余华作品，前者主人公福贵，后者许三观；张艺谋同年代的影片还改编过莫言《红高粱》（1987年）、苏童《妻妾成群》（《大红灯笼高高挂》），作者不要混淆。","mcq":[{"q":"小说《活着》的主人公是","o":["祥子","孙少平","福贵","白嘉轩"],"a":2,"w":"福贵是余华《活着》的主人公，祥子是《骆驼祥子》的主人公。"},{"q":"1994年张艺谋导演的电影《活着》改编自下列哪位作家的小说","o":["莫言","苏童","刘震云","余华"],"a":3,"w":"电影改编自余华1992年的小说《活着》。"}],"rel":[{"t":"余华","n":"作者"},{"t":"先锋文学","n":"作者早期所属思潮"},{"t":"莫言","n":"张艺谋也改编其作品"},{"t":"《平凡的世界》","n":"同写普通人的苦难与奋斗"}],"more":"余华（1960年生），浙江海盐人，另有《许三观卖血记》《兄弟》《第七天》。\n电影《活着》（1994）获戛纳评审团大奖，葛优获最佳男演员奖。","exam":[]},{"id":"a08-069","t":"第十一届茅盾文学奖","cid":"08i","p":2,"kind":"时事","alias":["第十一届茅奖","第十一届茅盾文学奖获奖作品"],"one":"2023年8月揭晓，《雪山大地》《宝水》《本巴》《千里江山图》《回响》5部获奖。","ans":"第十一届茅盾文学奖于**2023年8月揭晓**，共**5部**作品获奖：**杨志军《雪山大地》**、**乔叶《宝水》**、**刘亮程《本巴》**、**孙甘露《千里江山图》**、**东西《回响》**。茅盾文学奖1981年设立，是中国长篇小说的最高奖项，每四年评选一届。**孙甘露**是上海作家，《千里江山图》以1930年代的上海地下斗争为背景，是上海作家继《长恨歌》《繁花》之后再获茅奖。","pts":["2023年8月揭晓，5部","《雪山大地》《宝水》《本巴》《千里江山图》《回响》","孙甘露《千里江山图》，上海作家"],"mem":"五部书名好记：**“雪山—宝水—本巴—千里江山—回响”**，一组名词都有山水味。作者“杨乔刘孙东”，对应杨志军、乔叶、刘亮程、孙甘露、东西。","mix":"《繁花》（金宇澄）是第九届，《长恨歌》（王安忆）是第五届；第十届（2019）获奖作品有《人世间》《应物兄》等，别与第十一届混。","mcq":[{"q":"下列作品中，不属于第十一届茅盾文学奖的是","o":["《宝水》","《本巴》","《繁花》","《千里江山图》"],"a":2,"w":"《繁花》获第九届茅盾文学奖。"}],"rel":[{"t":"茅盾文学奖","n":"所属奖项"},{"t":"孙甘露","n":"上海获奖作家"},{"t":"《千里江山图》","n":"获奖作品"},{"t":"第十届茅盾文学奖","n":"前一届"}],"more":"获奖作品：杨志军《雪山大地》，乔叶《宝水》，刘亮程《本巴》，孙甘露《千里江山图》，东西《回响》。\n茅盾文学奖1981年设立，每四年一届。","exam":[]},{"id":"a08-070","t":"第十届茅盾文学奖","cid":"08i","p":3,"kind":"时事","exam":[],"alias":[],"one":"2019年：梁晓声《人世间》、徐怀中《牵风记》、徐则臣《北上》、陈彦《主角》","ans":"2019年：梁晓声《人世间》、徐怀中《牵风记》、徐则臣《北上》、陈彦《主角》、李洱《应物兄》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-071","t":"首届茅盾文学奖","cid":"08i","p":3,"kind":"事件","exam":[],"alias":[],"one":"1982年评出6部：周克芹《许茂和他的女儿们》、魏巍《东方》、姚雪垠《李自成","ans":"1982年评出6部：周克芹《许茂和他的女儿们》、魏巍《东方》、姚雪垠《李自成》（第二卷）、莫应丰《将军吟》、李国文《冬天里的春天》、古华《芙蓉镇》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-072","t":"雨果奖","cid":"08i","p":1,"kind":"制度","alias":["雨果奖","Hugo奖","世界科幻协会奖"],"one":"世界科幻协会颁发，1953年起，以科幻杂志之父雨果·根斯巴克命名。","ans":"雨果奖是**世界科幻协会颁发的科幻文学奖**，**1953年首次颁发**，以**美国科幻杂志创办人雨果·根斯巴克**命名，他被称为“科幻杂志之父”，1926年创办《惊奇故事》。奖项在每年的**世界科幻大会**上颁发，设最佳长篇、中篇、中短篇、短篇小说等奖项，由会员投票评出，与**星云奖**并称为**世界科幻文学两大奖**。**2015年刘慈欣《三体》获最佳长篇小说奖**，**2016年郝景芳《北京折叠》获最佳中短篇小说奖**，2023年世界科幻大会在成都举办。","pts":["世界科幻协会颁发，1953年起","以雨果·根斯巴克命名，与星云奖并称","2015《三体》、2016《北京折叠》获奖"],"mem":"奖杯是一枚**火箭**，记住它是科幻奖，不是文学巨匠奖。名字陷阱：**雨果奖 = 雨果·根斯巴克（美国科幻）≠ 维克多·雨果（法国《悲惨世界》）**。中国得主：**2015刘慈欣，2016郝景芳，2023年成都办大会**。","mix":"雨果奖以“雨果·根斯巴克”命名，与法国作家维克多·雨果无关；星云奖由美国科幻与奇幻作家协会颁发，同为科幻大奖；雨果奖是科幻奖，不是诺贝尔文学奖。","mcq":[{"q":"雨果奖的命名来自","o":["雨果·根斯巴克","维克多·雨果","儒勒·凡尔纳","阿西莫夫"],"a":0,"w":"雨果奖以科幻杂志创办人雨果·根斯巴克命名，与法国作家维克多·雨果无关。"},{"q":"首位获得雨果奖的亚洲作家是","o":["郝景芳","韩松","刘慈欣","王晋康"],"a":2,"w":"2015年刘慈欣《三体》获第73届雨果奖最佳长篇小说奖，为亚洲作家首次。"}],"rel":[{"t":"《三体》","n":"2015年获奖"},{"t":"郝景芳《北京折叠》","n":"2016年获奖"},{"t":"雨果","n":"同名易混的法国作家"},{"t":"中国科幻“四大天王”","n":"中国科幻作家群"}],"more":"雨果·根斯巴克1926年创办《惊奇故事》。\n2015年第73届、2016年第74届，中国作家连续获奖；2023年第81届世界科幻大会在成都举办。","exam":[]},{"id":"a08-073","t":"郝景芳《北京折叠》","cid":"08i","p":1,"kind":"作品","alias":["北京折叠","郝景芳","折叠北京"],"one":"郝景芳科幻中短篇，2016年获第74届雨果奖最佳中短篇小说奖。","ans":"《北京折叠》是**郝景芳创作的中短篇科幻小说**，**2016年获第74届雨果奖最佳中短篇小说奖**，英译者为刘宇昆。小说设想**未来北京被折叠为三个空间**：第一空间居住500万人，第二空间2500万人，第三空间5000万人，**三个空间轮流使用大地，人口越多分到的时间越少**。主人公**老刀**是第三空间的垃圾工，为挣钱在三个空间之间往返送信。作品通过空间分层探讨**阶层固化与社会不平等**，郝景芳成为**继刘慈欣之后第二位获雨果奖的中国作家**。","pts":["郝景芳，2016年第74届雨果奖中短篇","北京折叠为三层空间，老刀送信","探讨阶层固化与不平等"],"mem":"数字“**5·25·50**”：三个空间人口500万、2500万、5000万，最富的人最少、时间最多。年份：**2015刘慈欣《三体》，2016郝景芳《北京折叠》**，雨果奖连续两年给了中国作家。主人公“老刀”是垃圾工，最底层。","mix":"《三体》获最佳长篇，《北京折叠》获最佳中短篇，两者奖项类别不同；《北京折叠》写阶层分层，《流浪地球》（刘慈欣）写太阳危机下的地球流浪，题材完全不同。","mcq":[{"q":"《北京折叠》的作者是","o":["郝景芳","刘慈欣","韩松","何夕"],"a":0,"w":"《北京折叠》是郝景芳的作品，2016年获雨果奖。"},{"q":"在郝景芳之前，唯一获得雨果奖的中国作家是","o":["王晋康","韩松","何夕","刘慈欣"],"a":3,"w":"刘慈欣2015年以《三体》获雨果奖，郝景芳2016年获奖，是第二位。"}],"rel":[{"t":"雨果奖","n":"所获奖项"},{"t":"《三体》","n":"前一年获奖作品"},{"t":"刘慈欣","n":"前一位雨果奖中国作家"},{"t":"中国科幻“四大天王”","n":"相对的中国科幻作家群"}],"more":"第74届雨果奖（2016年，美国堪萨斯城）最佳中短篇小说奖。\n三个空间人口：第一空间500万，第二空间2500万，第三空间5000万。","exam":[]},{"id":"a08-074","t":"海漄《时空画师》与成都世界科幻大会","cid":"08i","p":3,"kind":"时事","exam":[],"alias":[],"one":"2023年获雨果奖最佳短中篇小说奖；同年第81届世界科幻大会在成都举办，中国","ans":"2023年获雨果奖最佳短中篇小说奖；同年第81届世界科幻大会在成都举办，中国首次主办","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-075","t":"《流浪地球》","cid":"08i","p":2,"kind":"作品","alias":["流浪地球"],"one":"刘慈欣2000年发表的科幻中篇，2019年郭帆导演同名电影。","ans":"《流浪地球》是**刘慈欣2000年发表的科幻中篇小说**，发表于《科幻世界》。小说写**太阳即将毁灭**，人类建造行星发动机，推动地球离开太阳系，奔向新家园。作品体现了**集体生存与家园**的主题。**2019年由郭帆导演改编为同名电影**，是中国科幻电影的代表作；2023年上映续集《流浪地球2》。它让刘慈欣的作品从文学走向大众视野。","pts":["刘慈欣2000年发表的科幻中篇","太阳毁灭，推动地球流浪","2019年郭帆导演电影"],"mem":"一句话记全：**“太阳要灭，地球搬家”**。作者刘慈欣、导演郭帆、年份2019（春节档）。“流浪”二字就是地球带着人类“搬家”。","mix":"《三体》写三体文明与地球文明的冲突；《流浪地球》写人类带着地球逃离太阳系，二者都是刘慈欣作品，别混淆情节。","mcq":[{"q":"2019年上映的科幻电影《流浪地球》的导演是","o":["张艺谋","陈凯歌","徐克","郭帆"],"a":3,"w":"郭帆导演，改编自刘慈欣同名小说。"}],"rel":[{"t":"刘慈欣","n":"作者"},{"t":"《三体》","n":"同一作者的代表作"},{"t":"《科幻世界》","n":"首发杂志"},{"t":"雨果奖","n":"刘慈欣另一荣誉"}],"more":"2019年春节档上映；2023年上映《流浪地球2》。","exam":[]},{"id":"a08-076","t":"中国科幻“四大天王”","cid":"08i","p":3,"kind":"合称","exam":[],"alias":[],"one":"刘慈欣、王晋康、韩松、何夕（另有加入星河的说法）","ans":"刘慈欣、王晋康、韩松、何夕（另有加入星河的说法）","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-077","t":"《科幻世界》","cid":"08i","p":3,"kind":"作品","exam":[],"alias":[],"one":"成都，前身为1979年创刊的《科学文艺》","ans":"成都，前身为1979年创刊的《科学文艺》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1},{"id":"a08-078","t":"阎连科与卡夫卡奖","cid":"08i","p":3,"kind":"人物","exam":[],"alias":[],"one":"2014年获卡夫卡文学奖；《受活》《日光流年》","ans":"2014年获卡夫卡文学奖；《受活》《日光流年》","pts":[],"mem":"","mix":"","mcq":[],"rel":[],"more":"","todo":1}],"tables":[{"name":"现代作家与代表作","note":"","rows":[["作家","原名与身份","代表作"],["鲁迅","周树人，浙江绍兴","《狂人日记》《阿Q正传》，小说集《呐喊》《彷徨》《故事新编》"],["郭沫若","郭开贞，创造社","新诗集《女神》，历史剧《屈原》"],["茅盾","沈德鸿（雁冰），文学研究会","《子夜》，《蚀》三部曲（《幻灭》《动摇》《追求》），农村三部曲（《春蚕》《秋收》《残冬》），《林家铺子》"],["巴金","李尧棠","激流三部曲（《家》《春》《秋》），爱情三部曲（《雾》《雨》《电》），《寒夜》《随想录》《团圆》"],["老舍","舒庆春，满族，“人民艺术家”","《骆驼祥子》《四世同堂》，话剧《茶馆》《龙须沟》"],["曹禺","万家宝","话剧《雷雨》《日出》《原野》《北京人》"],["沈从文","湖南凤凰，京派","中篇小说《边城》，散文集《湘行散记》"],["郁达夫","创造社","小说《沉沦》《春风沉醉的晚上》，散文《故都的秋》"],["朱自清","散文家","《背影》《荷塘月色》"],["冰心","谢婉莹","诗集《繁星》《春水》"],["徐志摩、闻一多","新月派","《再别康桥》；《红烛》《死水》（新诗“三美”）"],["钱锺书、张爱玲、萧红","现代小说家","《围城》；《金锁记》《倾城之恋》；《呼兰河传》"],["赵树理、丁玲、周立波","解放区作家","《小二黑结婚》；《太阳照在桑干河上》；《暴风骤雨》"],["莫言","管谟业，山东高密","《红高粱家族》《蛙》，2012年诺贝尔文学奖"],["刘慈欣","科幻作家","《三体》三部曲，《流浪地球》"]]},{"name":"鲁迅作品集与体裁","note":"","rows":[["作品集","体裁","名篇"],["《呐喊》","短篇小说集","《狂人日记》《孔乙己》《药》《阿Q正传》《故乡》"],["《彷徨》","短篇小说集","《祝福》《伤逝》《在酒楼上》"],["《故事新编》","历史小说集","《补天》《奔月》《铸剑》"],["《朝花夕拾》","回忆性散文集（原名《旧事重提》，1926年写成）","《从百草园到三味书屋》《藤野先生》"],["《野草》","散文诗集","《秋夜》《雪》"],["《坟》《热风》《华盖集》《且介亭杂文》等","杂文集","《拿来主义》《记念刘和珍君》"],["《中国小说史略》","学术著作","第一部中国小说通史"]]}]});